/* empc24-questions.js - scored MCQ bank of 185 original board-style practice
 * questions written by Diana Karp, spanning 21 emergency medicine topic areas
 * (trauma, resuscitation, toxicology, ID, cardiology, neuro, obstetrics,
 * endocrine, oncology, pulmonary, and biostatistics/research design).
 *
 * Case vignettes were condensed and every rationale rewritten during import
 * into this app. Rationales cite published guidelines and primary literature
 * by name; those citations credit the guideline authors and do not imply any
 * organization endorsed, reviewed, or produced these questions.
 *
 * Convention matches data/questions.js: the correct answer is authored at
 * index 0 and options are shuffled at display time.
 * Study aid only; verify against current guidelines and institutional protocols. */
window.BCEMP_EMPC24_QUESTIONS = [
  { id: "pe24-001", domain: "trauma", difficulty: 3, tags: ["Blunt Trauma", "TBI"],
    stem: "BB is a 56-year-old man brought in after an assault. He has no medical history and takes no medications. Vitals: HR 116, BP 147/86, RR 16, SpO2 97% on room air. GCS is 12 (E3V4M5). Exam shows bogginess and slight depression over the right parietal region, a 3-cm forehead laceration, and bruising of the right arm. Head CT shows a depressed right parietal skull fracture. Based on Brain Trauma Foundation guidelines for severe TBI, which medication is most appropriate for seizure prophylaxis?",
    options: ["Phenytoin to prevent early post-traumatic seizures", "Phenobarbital to prevent early post-traumatic seizures", "Levetiracetam to prevent late post-traumatic seizures", "Valproate to prevent late post-traumatic seizures"], correctIndex: 0,
    rationale: "A GCS of 12 is moderate TBI by GCS alone, but a depressed skull fracture is a recognized high-risk feature for early post-traumatic seizures. The Brain Trauma Foundation recommends phenytoin to reduce EARLY (first 7 days) post-traumatic seizures when the benefit outweighs the risks. No agent prevents LATE seizures, which rules out the levetiracetam and valproate options on their stated indication alone. Levetiracetam is widely used for early prophylaxis with similar results in studies, but BTF found the evidence insufficient to prefer it over phenytoin. Phenobarbital has no supporting evidence here",
    source: "Brain Trauma Foundation Guidelines for the Management of Severe TBI, 4th ed. (2016)", updated: "2026-11" },

  { id: "pe24-002", domain: "trauma", difficulty: 2, tags: ["Blunt Trauma", "Assessment"],
    stem: "According to Advanced Trauma Life Support (ATLS) guidelines, which of the following is the most objective way of assessing a patient's level of consciousness?",
    options: ["Glasgow Coma Scale (GCS)", "Emergency Severity Index (ESI)", "National Institutes of Health Stroke Scale (NIHSS)", "Los Angeles Motor Scale (LAMS)"], correctIndex: 0,
    rationale: "ATLS identifies the GCS as the quick, simple, objective measure of consciousness. The distractors are all real tools measuring something else: ESI is a triage acuity tool, NIHSS grades neurologic deficit in acute stroke, and LAMS is a prehospital stroke-severity screen derived from motor exam components." },

  { id: "pe24-003", domain: "trauma", difficulty: 3, tags: ["Blunt Trauma", "Anticoagulant Reversal"],
    stem: "EN is a 57-year-old woman brought in after a motor vehicle collision. GCS on arrival was 6 (E1V1M4); vitals HR 97, BP 139/68, RR 14, SpO2 96%. She was intubated in the trauma bay; non-contrast head CT shows a large subdural hematoma. Her husband reports she takes apixaban but does not take it reliably, so the timing of her last dose is unknown. Which agent is most appropriate for apixaban reversal?",
    options: ["Four-factor prothrombin complex concentrate (PCC)", "Protamine", "Recombinant activated factor VII (rFVIIa)", "Three-factor PCC plus recombinant activated factor VII (rFVIIa)"], correctIndex: 0,
    rationale: "Four-factor PCC is now the factor Xa inhibitor reversal agent in the US: andexanet alfa was withdrawn from the US market in December 2025 after its confirmatory trial (ANNEXA-I) showed more thrombosis than usual care (14.6% vs 6.9%). The 2020 ACC pathway suggests a fixed 4F-PCC dose of 2,000 units (25–50 units/kg is also used), and the 2022 AHA/ASA ICH guideline says 4F-PCC or activated PCC may be considered. Protamine reverses heparin, not Xa inhibitors. rFVIIa is not recommended for reversal of any anticoagulant, and three-factor PCC plus rFVIIa adds thrombotic risk without proven benefit",
    source: "FDA safety communication on Andexxa (Dec 2025); 2020 ACC Expert Consensus Decision Pathway on Bleeding in Patients on Oral Anticoagulants; 2022 AHA/ASA ICH guideline", updated: "2026-11" },

  { id: "pe24-004", domain: "trauma", difficulty: 3, tags: ["Blunt Trauma", "Lab Interpretation"],
    stem: "EN, the 57-year-old woman on apixaban with a subdural hematoma, has qualitative coagulation testing sent to determine whether clinically significant drug levels are present. Results (reference ranges in parentheses): INR 0.94 (0.9-1.1), PT 16.8 sec (9.3-11.7), aPTT 24.4 sec (23.1-30.9), thrombin time 19 sec (14-19), anti-Xa calibrated to UFH 0.7 IU/mL (0.3-0.7). Which is the most appropriate interpretation?",
    options: ["Clinically significant apixaban levels are present because the PT is prolonged and the anti-Xa level is not below the lower limit of quantification", "Clinically significant apixaban levels cannot be excluded because the aPTT is within the normal range", "Clinically significant apixaban levels can be excluded because the anti-Xa level is within the therapeutic range", "Clinically significant apixaban levels are present because the thrombin time is prolonged"], correctIndex: 0,
    rationale: "Apixaban is detected qualitatively by a prolonged PT together with any anti-Xa level (calibrated to UFH or LMWH) above the lower limit of quantification — both are true here. A normal aPTT does not exclude drug. A measurable anti-Xa level argues FOR drug being present, not against it. Thrombin time reflects direct thrombin inhibitors and is insensitive to apixaban." },

  { id: "pe24-005", domain: "trauma", difficulty: 2, tags: ["Blunt Trauma", "TBI"],
    stem: "RT is a 47-year-old man brought in after a fall with head strike. Vitals: HR 104, BP 86/43, RR 16, SpO2 97%. GCS is 10 (E2V3M5). He has dyslipidemia and takes atorvastatin. The team wants to address his hypotension before CT. Based on Brain Trauma Foundation guidelines for severe TBI, what is the most appropriate systolic blood pressure goal?",
    options: ["Systolic blood pressure over 110 mm Hg", "Systolic blood pressure over 90 mm Hg", "Systolic blood pressure over 100 mm Hg", "Systolic blood pressure over 140 mm Hg"], correctIndex: 0,
    rationale: "Brain Trauma Foundation guidelines suggest maintaining SBP of at least 110 mm Hg in severe TBI patients aged 15-49 or over 70 to reduce mortality (Level III). RT is 47, so 110 applies. Thresholds of 90 or 100 are too permissive and risk secondary injury from cerebral hypoperfusion; 140 is higher than the guideline supports." },

  { id: "pe24-006", domain: "pain", difficulty: 3, tags: ["Analgesia", "Trauma"],
    stem: "MD is a 93.2-kg 46-year-old man brought in after a motor vehicle collision. He received ketamine 25 mg IV en route, which brought his pain to 4/10. On arrival: HR 135, BP 167/81, RR 16, SpO2 100%. History includes asthma, hyperlipidemia, and coronary artery disease. Secondary survey finds a right lower extremity deformity requiring X-ray. He now reports 9/10 right leg pain and will not let anyone touch it. Which analgesic recommendation is most appropriate now?",
    options: ["Fentanyl 50 mcg IV", "Ketamine 28 mg IV", "Ibuprofen 400 mg orally", "Acetaminophen 1000 mg orally"], correctIndex: 0,
    rationale: "Severe pain plus an urgent imaging need calls for a parenteral agent with rapid onset. Fentanyl 50 mcg is roughly 0.5 mcg/kg here, an appropriate conservative starting dose. Repeat ketamine is a poor fit given his tachycardia, hypertension, and coronary artery disease. Both oral options act too slowly to serve the immediate goal of facilitating the workup, even though acetaminophen is reasonable later as part of multimodal therapy." },

  { id: "pe24-007", domain: "trauma", difficulty: 3, tags: ["Blunt Trauma", "TXA"],
    stem: "GC is a 68-year-old man transferred after a motorcycle accident that occurred approximately 3.5 hours before arrival. Vitals: HR 128, BP 94/62, RR 16, SpO2 94%, temp 36.9°C. GCS is 10. Non-contrast head CT shows a left subdural hematoma. The ED physician asks whether he would benefit from tranexamic acid. Based on available evidence in traumatic brain injury, what is the most appropriate response?",
    options: ["TXA should not be administered because more than 3 hours have elapsed since his head injury", "TXA should not be administered because it may increase his risk of seizures", "TXA should be administered because it may reduce his risk of head injury-related death", "TXA should be administered because it may reduce hematoma expansion in the first 24 hours"], correctIndex: 0,
    rationale: "The 3-hour window is the deciding factor. In CRASH-2, TXA given more than 3 hours after injury increased death due to bleeding (4.4% vs 3.1%), and CRASH-3's primary analysis included only patients treated within 3 hours, where fewer head-injury deaths were seen in mild-to-moderate TBI. Seizure risk is not the reason to withhold it — CRASH-3 showed no significant excess of seizures or stroke",
    source: "CRASH-2 (Lancet 2010, 2011); CRASH-3 (Lancet 2019)", updated: "2026-11" },

  { id: "pe24-008", domain: "resus", difficulty: 2, tags: ["RSI", "TBI"],
    stem: "Which induction agent for rapid sequence intubation decreases cerebral blood flow and cerebral metabolic demand while preserving cerebral perfusion pressure and mean arterial pressure, making it well suited to patients with traumatic brain injury?",
    options: ["Etomidate", "Propofol", "Ketamine", "Fentanyl"], correctIndex: 0,
    rationale: "Etomidate lowers cerebral blood flow and metabolic demand while maintaining MAP and cerebral perfusion pressure — the combination that matters in TBI. Propofol also lowers ICP but frequently causes hypotension, which drops cerebral perfusion pressure. Ketamine's ICP effect is debated. Fentanyl blunts the intubation ICP response but does not reduce cerebral blood flow or metabolic demand and may lower MAP." },

  { id: "pe24-009", domain: "resus", difficulty: 3, tags: ["Shock", "Spinal Cord Injury"],
    stem: "A 22-year-old woman with no medical history is brought in after a diving accident. She is awake and alert but cannot move her legs. Vitals: HR 54, BP 83/46, RR 20, SpO2 98%, temp 37.9°C. Exam is normal except for 0/5 motor strength and absent light touch in both lower extremities. She received 1 L of IV normal saline en route and continues to receive fluid. CT of the head, chest, abdomen, and pelvis shows no acute abnormality. What is the most likely explanation for her hypotension?",
    options: ["Neurogenic shock", "Spinal shock", "Distributive shock", "Hemorrhagic shock"], correctIndex: 0,
    rationale: "The triad of hypotension, BRADYCARDIA, and temperature dysregulation after a cord injury at or above T6 points to neurogenic shock from autonomic dysfunction. Spinal shock refers to loss of muscle tone and reflexes and is not a hemodynamic diagnosis — the classic trap in this question. Distributive shock from sepsis or anaphylaxis would typically produce reflex tachycardia. Imaging shows no bleeding source." },

  { id: "pe24-010", domain: "trauma", difficulty: 3, tags: ["Blunt Trauma", "Antiplatelet Reversal"],
    stem: "BH is a 66-year-old woman who presents after a fall at her nursing home 2 hours earlier. Vitals: HR 131, BP 92/61, RR 16, SpO2 98%, temp 36.7°C. GCS is 15. History includes diabetes, coronary artery disease with prior MI, and remote breast cancer. Medications include aspirin 81 mg daily and ticagrelor 90 mg twice daily. Labs: hemoglobin 9.4 g/dL, platelets 143,000/microliter, serum creatinine 0.9 mg/dL, BUN 19 mg/dL. Head CT shows a right subdural hematoma. What best describes the role of desmopressin here, per the 2020 ACC Expert Consensus Decision Pathway?",
    options: ["It should not be given, because the pathway recommends it only for major bleeding with renal dysfunction and concern for uremia-associated platelet dysfunction", "It should be given, because it is recommended for all patients with intracranial hemorrhage on any antiplatelet agent", "It should not be given, because it is contraindicated in intracranial hemorrhage", "It should not be considered, because it increases the risk of thrombosis"], correctIndex: 0,
    rationale: "The 2020 ACC pathway restricts desmopressin to major bleeding in the setting of renal dysfunction with suspected uremic platelet dysfunction. BH has a normal creatinine and BUN, so she does not qualify. The broader 'all antiplatelet-associated ICH' recommendation comes from the 2016 Neurocritical Care Society guidance, not the ACC pathway. Desmopressin is not contraindicated in ICH, and its thrombosis risk is low." },

  { id: "pe24-011", domain: "trauma", difficulty: 3, tags: ["Penetrating Trauma", "Pediatrics"],
    stem: "LJ is a 45-kg 12-year-old boy who presents after falling from his dirt bike down a steep incline without a helmet. He has a 3-cm laceration to the left lower abdominal quadrant. Paramedics applied a cervical collar and backboard, placed IV access, bandaged the wound, and gave 900 mL of normal saline. Primary survey shows BP 86/58 and a Pediatric Glasgow Coma Scale score of 13. Based on the PALS definition of hypotension and his Pediatric GCS, how is his condition best characterized?",
    options: ["Hypotensive with mild brain injury", "Hypotensive with moderate brain injury", "Not hypotensive with normal mental status", "Not hypotensive with mild brain injury"], correctIndex: 0,
    rationale: "PALS defines hypotension in children 10 years and older as SBP below 90 mm Hg, and his SBP is 86. A Pediatric GCS of 13 or above indicates MILD brain injury (9-12 is moderate, and 15 is normal mental status). Both halves must be correct, so he is hypotensive with mild brain injury." },

  { id: "pe24-012", domain: "trauma", difficulty: 3, tags: ["Penetrating Trauma", "Pediatrics", "Transfusion"],
    stem: "LJ, the 45-kg 12-year-old with a 3-cm left lower quadrant laceration, has received one 20-mL/kg (900 mL) IV fluid bolus. Repeat testing shows ionized calcium 1.3 mmol/L, venous pH 7.3, bicarbonate 28 mmol/L, hemoglobin 6.6 g/dL, hematocrit 17%, BP 76/52, and HR 138. The team leader suggests a second 20-mL/kg fluid bolus. Which IV intervention should be recommended instead?",
    options: ["Blood products", "IV calcium", "Recombinant factor VIIa infusion", "Epinephrine continuous infusion"], correctIndex: 0,
    rationale: "He is in uncompensated traumatic hemorrhagic shock with hemoglobin below 7 g/dL and is only minimally fluid responsive, so blood products rather than more crystalloid are indicated. Excessive crystalloid worsens mortality, dilutional coagulopathy, and abdominal compartment syndrome. His ionized calcium is normal and he has had no blood products yet, so calcium is premature. rFVIIa is not recommended in traumatic hemorrhagic shock, and vasopressors should be avoided before adequate volume resuscitation." },

  { id: "pe24-013", domain: "trauma", difficulty: 3, tags: ["Penetrating Trauma", "Antibiotic Prophylaxis", "Pediatrics"],
    stem: "MB is a 65-kg 14-year-old boy with no known drug allergies brought in for a gunshot wound to the right arm. Portable X-ray shows a proximal humerus shaft fracture, diagnosed by the trauma surgeon as a Gustilo-Anderson Type II open fracture. Based on EAST guidelines for prophylactic antibiotics in open fractures, what is most appropriate?",
    options: ["Cefazolin IV monotherapy", "Penicillin IV monotherapy", "Cefazolin IV plus gentamicin IV", "Open fractures caused by gunshot wounds do not require antibiotic prophylaxis"], correctIndex: 0,
    rationale: "EAST recommends gram-positive coverage for Gustilo-Anderson Type I and II open fractures, which cefazolin provides. Penicillin lacks adequate staphylococcal coverage and is added only when fecal or clostridial contamination is suspected. Gram-negative coverage such as gentamicin is reserved for Type III fractures. Gunshot fractures are open fractures and do require prophylaxis." },

  { id: "pe24-014", domain: "trauma", difficulty: 3, tags: ["Penetrating Trauma", "Tetanus", "Pediatrics"],
    stem: "MM is an 8-year-old boy flown in after a tractor rollover with a crush injury on an animal farm; he was pinned in soil for 10 minutes. Secondary survey shows an obvious right lower extremity deformity with a visibly dirty wound. X-ray reveals a right tibia-fibula fracture, classified as a Gustilo-Anderson Type IIIA open fracture. His immunization record shows he has received two doses of tetanus toxoid-containing vaccine. Based on CDC recommendations for tetanus prophylaxis in wounds, what is most appropriate?",
    options: ["Tdap vaccination plus tetanus immune globulin (TIG)", "DTaP vaccination plus tetanus immune globulin (TIG)", "Tetanus immune globulin (TIG) only", "Td vaccination only"], correctIndex: 0,
    rationale: "Two conditions must both be met. He needs vaccine because he has not completed the three-dose series, and at 7 years or older the correct product is Tdap (DTaP is for children under 7; Td is a booster for those already fully immunized). He also needs TIG because a soil- and possibly manure-contaminated crush wound is high risk and he is not fully immunized." },

  { id: "pe24-015", domain: "pain", difficulty: 3, tags: ["Procedural Sedation", "Pediatrics"],
    stem: "MM, the 8-year-old with a Gustilo-Anderson Type IIIA open tibia-fibula fracture, needs procedural sedation for bedside reduction before surgery. The surgeon expects the procedure to take 30 minutes. Vitals: HR 100, BP 88/56, RR 18, SpO2 99% on room air. His pain score is 8/10. Which IV monotherapy do you recommend?",
    options: ["Ketamine", "Etomidate", "Midazolam", "Propofol"], correctIndex: 0,
    rationale: "Ketamine is the only option here that provides ANALGESIA as well as sedation, which a bone reduction requires, and its duration suits a 30-minute procedure without repeat dosing. It carries an ACEP Level A recommendation for pediatric procedural sedation. Etomidate, midazolam, and propofol are all sedative-only and would need an adjunctive analgesic; etomidate is also too short-acting, and propofol risks hypotension in a boy already borderline by the PALS formula (70 + 2 x 8 = 86 mm Hg)." },

  { id: "pe24-016", domain: "pain", difficulty: 2, tags: ["Procedural Sedation", "Pediatrics", "Intranasal"],
    stem: "Which intranasal medication should NOT be used in hemodynamically stable pediatric patients without vascular access who require procedural sedation for minor procedures?",
    options: ["Morphine", "Ketamine", "Dexmedetomidine", "Midazolam"], correctIndex: 0,
    rationale: "Intranasal morphine has poor bioavailability and is not recommended in adults or children for procedural sedation or moderate-to-severe pain. Intranasal ketamine, dexmedetomidine, and midazolam all have demonstrated efficacy for pediatric procedural sedation and are reasonable when IV access is unavailable." },

  { id: "pe24-017", domain: "tox", difficulty: 3, tags: ["Cyanide", "Inhalation Injury"],
    stem: "Which finding is NOT useful when evaluating a patient with inhalation injury and suspected cyanide toxicity to decide whether hydroxocobalamin is appropriate?",
    options: ["Elevated serum cyanide level", "Elevated serum lactate level", "Soot around the nares or oral cavity", "Altered mental status"], correctIndex: 0,
    rationale: "There is no standard, rapidly available assay for serum cyanide, so the decision to give hydroxocobalamin is never based on a cyanide level — it must be made empirically. A lactate above 8 mmol/L supports the diagnosis, and soot around the nares or mouth plus altered mental status are part of the recommended bedside assessment for inhalation injury." },

  { id: "pe24-018", domain: "id", difficulty: 3, tags: ["Meningitis", "Neonates"],
    stem: "TL is a 19-day-old boy presenting with poor feeding, lethargy, and fever. Lumbar puncture shows cloudy CSF, WBC 1300 cells/mm3 (84% segs, 6% bands, 10% lymphs), glucose 24 mg/dL, and protein 160 mg/dL. Empiric ampicillin plus gentamicin is started. While awaiting admission, CSF Gram stain shows gram-negative rods. What change to his antibiotics is most appropriate?",
    options: ["Continue ampicillin and replace gentamicin with ceftazidime", "Continue ampicillin and gentamicin", "Discontinue ampicillin and continue gentamicin as monotherapy", "Discontinue ampicillin and replace gentamicin with ceftazidime as monotherapy"], correctIndex: 0,
    rationale: "Two principles combine. Gentamicin has poor CNS penetration and should be replaced with ceftazidime given the gram-negative rods (likely E. coli or another Enterobacteriaceae) and clear evidence of bacterial meningitis (cefepime is an alternative; cefotaxime is often unavailable in the US, and ceftriaxone is avoided in neonates). But therapy is never NARROWED on a Gram stain, which is interpreter-dependent and error-prone — so ampicillin continues until culture and susceptibility results return",
    source: "AAP Red Book; review of cefotaxime alternatives in neonates (Expert Rev Anti Infect Ther 2022)", updated: "2026-11" },

  { id: "pe24-019", domain: "id", difficulty: 3, tags: ["Meningitis", "Neonates", "Dexamethasone"],
    stem: "SD is an 8-day-old boy (3.5 kg) presenting with poor feeding, lethargy, and fever. Lumbar puncture shows cloudy CSF, WBC 1400 cells/mm3 (93% segs, 4% bands, 3% lymphs), glucose 25 mg/dL, and protein 145 mg/dL. Gram stain is pending. Which statement about IV dexamethasone is correct per IDSA bacterial meningitis guidelines?",
    options: ["Dexamethasone should not be administered, because data are insufficient to recommend it in neonates with bacterial meningitis", "Dexamethasone 0.5 mg should be given 15 minutes before antibiotics", "Dexamethasone 5 mg should be given 30 minutes before antibiotics", "Dexamethasone 0.5 mg every 6 hours should start 24 hours after antibiotics"], correctIndex: 0,
    rationale: "IDSA does not recommend adjunctive dexamethasone in NEONATES; the single published trial found no difference in mortality or neurologic sequelae. Where dexamethasone IS supported (H. influenzae in children, S. pneumoniae in adults) the dose is 0.15 mg/kg and it must be given 10-15 minutes before or with the first antibiotic dose — never started a day later, and never after antibiotics have already been given." },

  { id: "pe24-020", domain: "id", difficulty: 3, tags: ["Encephalitis", "Pediatrics", "Dosing"],
    stem: "AJ is a 9-year-old boy (30 kg) presenting with hallucinations, lethargy, fever, and seizures. Lumbar puncture shows cloudy CSF, WBC 250 cells/mm3 (93% lymphs, 1% bands, 3% segs), glucose 55 mg/dL, and protein 60 mg/dL. Gram stain is pending. Which IV antimicrobial regimen is most appropriate now?",
    options: ["Acyclovir 450 mg every 8 hours", "Acyclovir 600 mg every 8 hours", "Ampicillin 2000 mg every 6 hours, ceftriaxone 2000 mg every 12 hours, and vancomycin 450 mg every 6 hours", "Ceftriaxone 2000 mg every 12 hours"], correctIndex: 0,
    rationale: "Lymphocytic predominance with normal glucose and near-normal protein points to a viral rather than bacterial process, so empiric antibacterial regimens are not indicated. Acyclovir at 10-15 mg/kg every 8 hours gives 450 mg for a 30-kg child. The 20 mg/kg dosing (600 mg) is reserved for NEONATES; using it in an older child raises neurotoxicity and nephrotoxicity risk without added benefit." },

  { id: "pe24-021", domain: "id", difficulty: 3, tags: ["Encephalitis", "Neonates", "Administration"],
    stem: "JT is a 17-day-old girl presenting with recent seizure-like activity, fever, and a vesicular rash. Ampicillin, gentamicin, and acyclovir 20 mg/kg are all ordered IV STAT. She has only one peripheral IV and a second is being attempted. The nurse asks which agent to give first and how. What is the most appropriate response?",
    options: ["Acyclovir as an IV infusion over 60 minutes, because her presentation is consistent with HSV encephalitis", "Acyclovir IV push over 5 minutes, because her presentation is consistent with HSV meningitis", "Gentamicin IV push over 5 minutes, because her presentation is consistent with bacterial infection", "Ampicillin as an IV infusion over 10 minutes, because her presentation is consistent with bacterial infection"], correctIndex: 0,
    rationale: "When several agents are ordered and access is limited, give the one covering the most likely pathogen first — here the vesicular rash with seizures in a neonate makes HSV the leading concern, so acyclovir goes first. Acyclovir must NEVER be given IV push; it is infused over 60 minutes to avoid crystalluria and renal tubular injury. Gentamicin also requires an infusion of at least 30 minutes, while ampicillin can be pushed over 5 minutes." },

  { id: "pe24-022", domain: "id", difficulty: 3, tags: ["Meningitis", "Neonates"],
    stem: "LL is a 19-day-old boy presenting with poor feeding, lethargy, and fever. CSF is cloudy with WBC 1500 cells/mm3 (84% segs, 6% bands, 10% lymphs), glucose 24 mg/dL, and protein 160 mg/dL. Empiric IV ampicillin and gentamicin are started. CSF Gram stain then shows gram-positive diplococci. What change is most appropriate?",
    options: ["Continue ampicillin, replace gentamicin with cefepime, and add vancomycin", "Continue ampicillin and gentamicin", "Continue ampicillin and discontinue gentamicin", "Discontinue ampicillin and gentamicin and start vancomycin"], correctIndex: 0,
    rationale: "Gram-positive diplococci suggest S. pneumoniae, so vancomycin is added for penicillin-resistant strains, together with a cephalosporin active against pneumococcus. In a neonate that means cefepime: cefotaxime is often unavailable in the US, ceftriaxone is avoided in neonates, and ceftazidime is weak against gram-positive organisms. Gentamicin goes because of its poor CNS penetration in confirmed bacterial meningitis. Ampicillin continues because Gram stains are interpreter-dependent (group B strep can also look like cocci in pairs) — coverage is narrowed only on culture and susceptibility results, which is why the options that drop agents are wrong",
    source: "IDSA bacterial meningitis guideline (2004); AAP Red Book; review of cefotaxime alternatives in neonates (Expert Rev Anti Infect Ther 2022)", updated: "2026-11" },

  { id: "pe24-023", domain: "cv", difficulty: 3, tags: ["Dysrhythmia", "PALS", "Pediatrics"],
    stem: "YU is a 9-year-old boy (30 kg) presenting with vomiting. Vitals: HR 154, BP 80/45, RR 45, SpO2 97% on room air. Exam shows adequate central pulses but weak peripheral pulses, capillary refill 4 seconds with cool mottled extremities, and he is lethargic. ECG shows monomorphic wide QRS complexes (greater than 0.09 seconds) with absent P waves. Based on the 2025 AHA PALS guidelines, what is the most appropriate intervention?",
    options: ["Perform synchronized cardioversion with 15 J", "Administer amiodarone 150 mg IV over 20 minutes", "Start epinephrine continuous IV infusion at 0.05 mcg/kg/min", "Defibrillate with 60 J"], correctIndex: 0,
    rationale: "This is ventricular tachycardia WITH a pulse, and lethargy plus hypotension and poor perfusion make it UNSTABLE — so electricity beats pharmacology. Synchronized cardioversion starts at 0.5–1 J/kg (15 J for 30 kg) and rises to 2 J/kg if it fails. Amiodarone is for stable or shock-refractory VT, and cardioversion has not yet been tried. Epinephrine does not treat VT. Defibrillation delivers an UNSYNCHRONIZED shock, which can land on the T wave and precipitate ventricular fibrillation in a patient who still has a pulse",
    source: "2025 AHA/AAP Pediatric Advanced Life Support guidelines (doses unchanged from 2020)", updated: "2026-11" },

  { id: "pe24-024", domain: "resus", difficulty: 3, tags: ["Septic Shock", "Pediatrics", "Vasopressors"],
    stem: "LO is a 6-year-old girl presenting with fever and lethargy. Initial vitals: HR 160, BP 80/45, RR 68, SpO2 97%, temp 38.7°C, with weak peripheral pulses, capillary refill 4 seconds, and cool mottled extremities. After 60 mL/kg of normal saline (three 20-mL/kg boluses), acetaminophen, and ceftriaxone, she is HR 150, BP 81/45, RR 30, temp 37.9°C, with capillary refill still 4 seconds. Based on the Surviving Sepsis Campaign pediatric guidelines and 2025 PALS, what is the most appropriate next intervention?",
    options: ["Initiate epinephrine 0.05 mcg/kg/min IV", "Initiate norepinephrine 0.05 mcg/kg/min IV", "Initiate maintenance IV fluids and reassess in 15 minutes", "Initiate vancomycin 300 mg as an IV infusion over 60 minutes"], correctIndex: 0,
    rationale: "She has had 60 mL/kg — the top of the recommended range — and remains hypotensive with delayed capillary refill, so this is fluid-refractory ('cold') shock needing vasoactive support now. Both the Surviving Sepsis Campaign (2020) and 2025 PALS accept EITHER epinephrine or norepinephrine as the first infusion (not dopamine); cold-shock physiology, with low cardiac output and HIGH systemic vascular resistance, favors epinephrine's inotropy, while norepinephrine mainly raises SVR further. More fluid risks overload, and broadening antibiotics does not address the immediate hemodynamic threat",
    source: "Surviving Sepsis Campaign pediatric guidelines (2020); 2025 AHA/AAP PALS", updated: "2026-11" },

  { id: "pe24-025", domain: "cv", difficulty: 3, tags: ["Dysrhythmia", "PALS", "Pediatrics"],
    stem: "SW is a 4-year-old boy (17 kg) presenting with vomiting. Vitals: HR 204, BP 95/51, RR 20, SpO2 97%. He has adequate central and peripheral pulses, capillary refill 2 seconds with warm well-perfused extremities, and age-appropriate mental status. ECG shows narrow QRS complexes (less than 0.09 seconds) with absent P waves. Based on the 2025 AHA PALS guidelines, what is most appropriate?",
    options: ["Administer adenosine 1.7 mg as an IV push", "Administer adenosine 0.34 mg as an IV push", "Administer amiodarone 85 mg IV over 20 minutes", "Perform synchronized cardioversion with 8.5 J"], correctIndex: 0,
    rationale: "Rate above 180 with a narrow QRS and absent P waves is SVT, and he is STABLE — normal mental status, warm and well perfused, not hypotensive. The first adenosine dose is 0.1 mg/kg (max 6 mg), which is 1.7 mg for 17 kg; a second dose is 0.2 mg/kg (max 12 mg). Cardioversion is reserved for unstable SVT, and amiodarone is not first line for stable SVT",
    source: "2025 AHA/AAP Pediatric Advanced Life Support guidelines", updated: "2026-11" },

  { id: "pe24-026", domain: "cv", difficulty: 3, tags: ["Dysrhythmia", "PALS", "Pediatrics"],
    stem: "SW, the 4-year-old (17 kg) with SVT, received adenosine. Repeat vitals: HR 210, BP 74/42, RR 20, SpO2 97%, capillary refill 2 seconds, age-appropriate mental status. ECG still shows narrow QRS complexes (less than 0.09 seconds) with absent P waves. Based on the 2025 AHA PALS guidelines, what is most appropriate now?",
    options: ["Perform synchronized cardioversion with 8.5 J", "Administer adenosine 3.4 mg as an IV push", "Administer adenosine 0.34 mg as an IV push", "Administer amiodarone 85 mg IV over 20 minutes"], correctIndex: 0,
    rationale: "The key change is that he is now HYPOTENSIVE, which reclassifies him as unstable, so synchronized cardioversion at 0.5 J/kg (8.5 J) takes priority over further drug therapy. The escalated adenosine dose of 0.2 mg/kg (3.4 mg) would have been correct only if he had remained stable after the first dose. Amiodarone is not first line for unstable SVT. If vagal maneuvers, adenosine, and cardioversion all fail, an antiarrhythmic such as procainamide or amiodarone is chosen with expert consultation, and 2025 PALS adds IV sotalol as an option when expert consultation is not available",
    source: "2025 AHA/AAP Pediatric Advanced Life Support guidelines", updated: "2026-11" },

  { id: "pe24-027", domain: "resus", difficulty: 2, tags: ["CPR", "PALS", "Pediatrics"],
    stem: "Based on the 2025 AHA pediatric resuscitation guidelines, which of the following is true?",
    options: ["The compression-to-ventilation ratio for 1-rescuer infant CPR is 30 compressions to 2 breaths", "The compression-to-ventilation ratio for 1-rescuer infant CPR is 15 compressions to 2 breaths", "Pulse assessment at each rhythm check should take no more than 5 seconds in children before resuming CPR", "With an advanced airway in place, 1 breath should be delivered every 6 seconds for infants and children"], correctIndex: 0,
    rationale: "Single-rescuer infant CPR uses 30:2, the same as adults; the ratio changes to 15:2 only with TWO rescuers, which is the pediatric-specific twist. Pulse checks should not exceed 10 seconds, not 5. With an advanced airway, infants and children get 1 breath every 2–3 seconds (20–30 breaths/min) — the every-6-seconds rate is the ADULT number",
    source: "2025 AHA/AAP Pediatric Basic and Advanced Life Support guidelines", updated: "2026-11" },

  { id: "pe24-028", domain: "pmr", difficulty: 2, tags: ["Biostatistics", "Descriptive Statistics"],
    stem: "Researchers studying a new anticoagulant for stroke prevention in non-valvular atrial fibrillation designed a noninferiority trial against warfarin and apixaban. Table 1 reports baseline demographics including the CHA2DS2-VASc score. Which measure best describes this data?",
    options: ["Median", "Mean", "Standard deviation", "Standard error of the mean"], correctIndex: 0,
    rationale: "CHA2DS2-VASc is ORDINAL — the ranks are ordered but the interval between them is not uniform — so the median (or mode) is the appropriate measure of central tendency. The mean and standard deviation belong to continuous, normally distributed interval or ratio data. Standard error of the mean is inferential rather than descriptive and is frequently confused with standard deviation." },

  { id: "pe24-029", domain: "pmr", difficulty: 2, tags: ["Biostatistics", "Study Design"],
    stem: "The Women's Health Initiative enrolled 161,808 postmenopausal women recruited 1993-1998 to determine whether statin use is associated with subsequent type 2 diabetes. Of 153,840 women analyzed, 10,834 were taking a statin at baseline and 143,006 were not. Participants self-reported whether they developed T2DM over follow-up. Which study design does this best describe?",
    options: ["Cohort", "Case-control", "Cross-sectional", "Experimental"], correctIndex: 0,
    rationale: "The hallmarks of a cohort study are all present: no intervention (observational), patients with the outcome excluded at baseline, groups defined by EXPOSURE (statin use), then followed forward for the outcome. A case-control study would have grouped by outcome and looked backward for exposure. Cross-sectional captures exposure and outcome at one point in time. Experimental requires randomized assignment." },

  { id: "pe24-030", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Bias"],
    stem: "In the Women's Health Initiative statin/T2DM analysis, participants self-reported whether they developed diabetes. The researchers had previously validated this method by comparing self-reported diagnoses against medication lists and laboratory data. By validating self-report, they most likely minimized which type of bias?",
    options: ["Misclassification", "Attrition", "Compliance", "Allocation"], correctIndex: 0,
    rationale: "Validating self-reported diagnoses against objective records improves the accuracy with which participants are labeled as having or not having the outcome, which is precisely what misclassification bias concerns. Attrition bias is about loss to follow-up, compliance bias about whether patients actually take the assigned drug, and allocation bias about how patients are assigned to groups in an experimental study — none are addressed by validating a diagnosis." },

  { id: "pe24-031", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Relative Risk"],
    stem: "In the Women's Health Initiative analysis, T2DM was self-reported by 1076 (9.93%) women taking statins and 9166 (6.41%) women not taking statins. Based on these data, the relative risk that postmenopausal women develop T2DM from statin use is closest to which value?",
    options: ["1.6", "0.6", "1.8", "3.5"], correctIndex: 0,
    rationale: "RR = 9.93% / 6.41% = 1.55, closest to 1.6. By convention the exposure or active drug goes in the numerator and the comparator in the denominator — inverting them gives the 0.6 distractor. The 1.8 value is near the upper bound of the hazard ratio confidence interval, and 3.5 is the absolute risk difference (9.93 − 6.41), not a ratio." },

  { id: "pe24-032", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Absolute Risk"],
    stem: "In the Women's Health Initiative analysis, T2DM was self-reported by 9.93% of statin users and 6.41% of nonusers. What is the absolute risk difference in self-reported T2DM between statin nonuse and statin use in the initial analysis?",
    options: ["3.5%", "1.6%", "1.7%", "28%"], correctIndex: 0,
    rationale: "The absolute difference is 9.93% − 6.41% = 3.52%, reported as an absolute value. The 1.6% distractor is the relative risk, 1.7 is the point estimate of the hazard ratio, and 28 is the number needed to harm (the reciprocal of the absolute risk increase). Recognizing which arithmetic each distractor came from is the skill being tested." },

  { id: "pe24-033", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "NNH"],
    stem: "In the Women's Health Initiative analysis, T2DM was self-reported by 9.93% of statin users and 6.41% of nonusers. Which value represents the number needed to harm for postmenopausal women taking statins?",
    options: ["28", "0.28", "4", "30"], correctIndex: 0,
    rationale: "First get the absolute risk increase: 9.93% − 6.41% = 3.52%. Then take the reciprocal as a DECIMAL: 1 / 0.0352 = 28.4. Per this source's convention, NNH is rounded DOWN (to 28) to avoid understating harm, whereas NNT is rounded UP to avoid overstating benefit. Forgetting to convert the percentage to a decimal produces the 0.28 distractor." },

  { id: "pe24-034", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Hypothesis Testing"],
    stem: "In the Women's Health Initiative statin/T2DM analysis, statin users had a mean age of 65.66 years versus 62.98 years for nonusers, and the authors concluded there was a statistically significant difference in age between the groups (p<0.001). Which error type is most likely to be present?",
    options: ["Type I only", "Type II only", "Type I and type II", "Neither type I nor type II"], correctIndex: 0,
    rationale: "The conclusion drawn is that a difference EXISTS, so the only error that could have been made is a false positive — type I. A type II error is only possible when the conclusion is that no difference exists. A single conclusion cannot be exposed to both error types at once, which eliminates the remaining options." },

  { id: "pe24-035", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Test Selection"],
    stem: "In the Women's Health Initiative statin/T2DM analysis, suppose time were not considered and investigators simply wanted to compare the proportion of statin users who developed T2DM with the proportion of nonusers who developed T2DM. What is the most appropriate statistical test?",
    options: ["Chi-square", "ANOVA", "Kruskal-Wallis", "Wilcoxon rank-sum"], correctIndex: 0,
    rationale: "Developing T2DM is a yes/no NOMINAL outcome compared across two unrelated groups, which is exactly what chi-square is for. ANOVA requires continuous data and three or more groups. Kruskal-Wallis requires ordinal data with three or more groups. Wilcoxon rank-sum (Mann-Whitney) handles ordinal data in two unrelated groups — right group structure, wrong data type." },

  { id: "pe24-036", domain: "pmr", difficulty: 2, tags: ["Biostatistics", "Confidence Intervals"],
    stem: "The confidence intervals reported in the Women's Health Initiative statin/T2DM analysis have a relatively narrow range. Which factor contributes most to this observation?",
    options: ["Large sample size", "Low hazard ratio", "Low standard variation", "Long study duration"], correctIndex: 0,
    rationale: "Interval width is driven by precision, and with more than 150,000 participants the standard error becomes very small, producing a narrow CI. The magnitude of the hazard ratio and the duration of the study do not determine CI width. 'Standard variation' is not a real statistical term — it is a distractor blending standard deviation and coefficient of variation." },

  { id: "pe24-037", domain: "pmr", difficulty: 2, tags: ["Biostatistics", "Confidence Intervals"],
    stem: "The confidence intervals for the development of T2DM in postmenopausal women using statins versus not using statins do not include 1. Which best explains the implication?",
    options: ["The difference between the two groups is statistically significant", "The difference between the two groups is not statistically significant", "As long as the hazard ratio is within the CI, the difference is statistically significant", "The difference is statistically significant only if the CI also includes zero"], correctIndex: 0,
    rationale: "For a RATIO measure such as a hazard ratio, 1 is the value meaning no difference. An interval excluding 1 therefore indicates statistical significance. The point estimate always falls inside its own confidence interval, so that fact carries no information. Zero is the null value for DIFFERENCE measures such as a percent change, not for ratios." },

  { id: "pe24-038", domain: "pmr", difficulty: 2, tags: ["Biostatistics", "Confounding"],
    stem: "In the Women's Health Initiative statin/T2DM analysis, the investigators performed multivariate analyses adjusting for age, race/ethnicity, BMI, and other cardiovascular risk factors. What best explains the rationale for doing so?",
    options: ["Reduce confounding bias", "Prevent classification bias", "Improve subgroup analyses", "Minimize observer bias"], correctIndex: 0,
    rationale: "Multivariate adjustment is the analytic tool for confounding — a third variable that distorts the relationship between exposure and outcome. Misclassification and observer bias are baked in by study conduct and cannot be fixed by any amount of later analysis, which is the key principle being tested. Adjustment also does not improve the quality of subgroup analyses." },

  { id: "pe24-039", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Noninferiority"],
    stem: "A noninferiority trial compared rivaroxaban with enoxaparin plus a vitamin K antagonist for treating pulmonary embolism. The prespecified noninferiority margin was 2 for the primary outcome of recurrent symptomatic VTE. The hazard ratio for rivaroxaban versus enoxaparin/VKA was 1.12 (95% CI 0.75-1.68). What is the best interpretation?",
    options: ["Rivaroxaban is noninferior in efficacy to enoxaparin/VKA", "Rivaroxaban is equivalent in efficacy to enoxaparin/VKA", "Rivaroxaban is inferior in efficacy to enoxaparin/VKA", "Rivaroxaban is not noninferior in efficacy to enoxaparin/VKA"], correctIndex: 0,
    rationale: "The entire interval (0.75-1.68) lies below the margin of 2, which is what licenses a noninferiority conclusion. EQUIVALENCE cannot be claimed from a noninferiority design — that requires a two-sided equivalence trial. Declaring inferiority would require the CI to sit beyond the margin at every point." },

  { id: "pe24-040", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Noninferiority"],
    stem: "A noninferiority trial compared semaglutide with insulin lispro for type 2 diabetes; the primary outcome was change from baseline in A1c at week 26 and the prespecified noninferiority margin was 0.4%. The investigators concluded semaglutide was noninferior. Which point estimate and 95% CI best supports that conclusion?",
    options: ["−0.16 (−0.32 to 0)", "−0.16 (−0.2 to 0.41)", "0.16 (0 to 0.42)", "0.4 (0.32 to 0.5)"], correctIndex: 0,
    rationale: "Noninferiority requires the ENTIRE confidence interval to fall below the margin of 0.4%. Only −0.32 to 0 does. The interval −0.2 to 0.41 crosses the margin, 0 to 0.42 crosses it, and in the last option the point estimate itself sits right at the margin. Reading the bound rather than the point estimate is the whole skill here." },

  { id: "pe24-041", domain: "pmr", difficulty: 3, tags: ["Biostatistics", "Noninferiority"],
    stem: "Which of the following describes the null hypothesis for a noninferiority trial?",
    options: ["The new treatment is not noninferior to the active control", "The new treatment is noninferior to the active control", "The new treatment is equivalent to the active control", "The new treatment is not different from the active control"], correctIndex: 0,
    rationale: "Investigators want to REJECT the null, and what they hope to show is noninferiority — so the null must be its opposite, that the new treatment is not noninferior. Noninferiority testing is one-sided. 'Equivalent to the active control' is the null of an equivalence trial, and 'not different from the active control' is the null of a superiority trial." },

  { id: "pe24-042", domain: "pmr", difficulty: 2, tags: ["Biostatistics", "Meta-analysis", "Bias"],
    stem: "A meta-analysis compared clinically relevant major bleeding between rivaroxaban and vitamin K antagonists. Investigators searched MEDLINE, Embase, CINAHL, Cochrane, and Science Citation Index Expanded from inception until 6 months ago for randomized trials, with no language restrictions; Embase and MEDLINE searches were limited to RCTs and human subjects. Which bias is most likely based on this search strategy?",
    options: ["Publication bias", "Language bias", "Selection bias", "Selective reporting"], correctIndex: 0,
    rationale: "The search covered only published databases and made no attempt to find unpublished or grey literature, which is precisely how publication bias enters a meta-analysis. Language bias is explicitly excluded because no language restriction was applied. Nothing in the description tells us how individual trials or subjects were selected, or how outcomes were reported, so the other two cannot be judged." },

  { id: "pe24-043", domain: "pmr", difficulty: 3, tags: ["Pharmacoeconomics"],
    stem: "You are reviewing a new antidiabetic drug for formulary addition at a large third-party payer. It costs more than established formulary agents but trials show superior A1c lowering and prevention of disease complications. From the managed care organization's perspective, which pharmacoeconomic analysis is most appropriate?",
    options: ["Cost-effectiveness analysis", "Cost-minimization analysis", "Cost-utility analysis", "Cost-benefit analysis"], correctIndex: 0,
    rationale: "Cost-effectiveness analysis compares agents whose outcomes differ in magnitude but are measured in the SAME natural units — here A1c lowering and complication rates. Cost-minimization applies only when the consequences are equivalent and you are choosing on price alone. Cost-utility is used when quality of life must be weighed, typically for life-extending therapy with serious trade-offs. Cost-benefit converts outcomes to monetary terms and suits comparing programs with different objectives." },

  { id: "pe24-044", domain: "neuro", difficulty: 3, tags: ["Status Epilepticus", "Benzodiazepines"],
    stem: "JM is a 42-year-old man (about 90 kg) brought in by his wife after witnessed body-jerking movements. In the resuscitation room, before any workup, he has a tonic-clonic seizure lasting approximately 5 minutes. He has no medical history and takes no medications. Vitals: HR 114, BP 132/88, RR 14, SpO2 99%, point-of-care glucose 114 mg/dL. He has no IV access. Which medication is most appropriate now?",
    options: ["Midazolam 10 mg IM", "Lorazepam 4 mg IV", "Diazepam 10 mg IV", "Lorazepam 2 mg IM"], correctIndex: 0,
    rationale: "A seizure of 5 minutes meets the definition of status epilepticus, and the decisive detail is that he has NO IV access — so any IV option would delay treatment while access is attempted. RAMPART showed IM midazolam superior to IV lorazepam for prehospital status epilepticus (73.4% vs 63.4% seizure-free on arrival). Lorazepam 2 mg IM is also underdosed; 0.1 mg/kg up to 4 mg would be 4 mg for this patient." },

  { id: "pe24-045", domain: "neuro", difficulty: 3, tags: ["Status Epilepticus", "Dosing"],
    stem: "PL is a 54-year-old woman (50 kg) in status epilepticus. She has epilepsy treated with topiramate but has not taken it for 2 months due to cost. She has IV access and received lorazepam 4 mg IV without response. Which is the most appropriate urgent (second-line) therapy?",
    options: ["Levetiracetam 3000 mg IV over 10 minutes", "Phenytoin 1500 mg IV over 20 minutes", "Valproic acid 500 mg IV over 5 minutes", "Lacosamide 400 mg IV over 10 minutes"], correctIndex: 0,
    rationale: "ESETT showed levetiracetam 60 mg/kg, fosphenytoin 20 mg PE/kg, and valproate 40 mg/kg to be essentially equivalent for benzodiazepine-refractory status epilepticus (47%, 45%, 46%). Levetiracetam 60 mg/kg is 3000 mg for 50 kg — correct drug and correct dose. Phenytoin should be 20 mg/kg (1000 mg) here, and 1500 mg would need 30 minutes rather than 20. Valproate 500 mg is far below the 20-40 mg/kg range. Lacosamide is reserved for REFRACTORY status, not urgent second-line therapy." },

  { id: "pe24-046", domain: "neuro", difficulty: 3, tags: ["Status Epilepticus", "Refractory"],
    stem: "NS is a 32-year-old woman (60 kg) with no medical history being treated for status epilepticus. She has received two 4-mg IV doses of lorazepam and a single 1200-mg IV dose of fosphenytoin (phenytoin equivalents). She seizes again and needs a second antiepileptic agent. Which is most appropriate now?",
    options: ["Lacosamide 400 mg IV", "Phenobarbital 500 mg IV", "Levetiracetam 1000 mg IV", "Phenytoin 1200 mg IV"], correctIndex: 0,
    rationale: "She now has REFRACTORY status epilepticus, where lacosamide 200-400 mg IV is appropriate. The other options fail on dose or logic: phenobarbital should be 15-20 mg/kg (900-1200 mg), not 500 mg; levetiracetam should be 60 mg/kg (3600 mg), not 1000 mg; and she has already had an adequate 20 mg/kg fosphenytoin load, so repeating phenytoin adds nothing — a different mechanism is needed." },

  { id: "pe24-047", domain: "neuro", difficulty: 2, tags: ["Status Epilepticus", "Administration", "Pediatrics"],
    stem: "LM is a 6-year-old boy (30 kg) being treated for status epilepticus. The physician orders fosphenytoin 600 mg PE IV and asks you to assist with preparation and administration. What is the shortest time over which this dose should be given?",
    options: ["10 minutes", "4 minutes", "2 minutes", "60 minutes"], correctIndex: 0,
    rationale: "In children the fosphenytoin rate limit is 2 mg PE/kg/min or 150 mg PE/min, whichever is SLOWER. For 30 kg that is 60 mg PE/min, so 600 mg PE needs at least 10 minutes. Four minutes applies the ADULT limit of 150 mg PE/min and would run it 2.5 times too fast, risking hypotension and arrhythmia. Fosphenytoin is still faster than phenytoin, whose limit is 50 mg/min in adults and 1–3 mg/kg/min (max 50 mg/min) in children",
    source: "Fosphenytoin (Cerebyx) prescribing information", updated: "2026-11" },

  { id: "pe24-048", domain: "neuro", difficulty: 3, tags: ["Myasthenia Gravis", "RSI"],
    stem: "PM is a 57-year-old man being managed for a myasthenia gravis exacerbation. Labs: Na 149, K 4.1, Cl 101, CO2 22, SCr 1.1 mg/dL (baseline 1.0), BUN 15, glucose 126. He is 5'8\" and weighs 150 lb (about 68 kg). Which neuromuscular blocker dose is most appropriate for rapid sequence intubation?",
    options: ["Rocuronium 40 mg IV", "Rocuronium 80 mg IV", "Succinylcholine 60 mg IV", "Succinylcholine 120 mg IV"], correctIndex: 0,
    rationale: "Myasthenic patients are unusually SENSITIVE to nondepolarizing blockers, so rocuronium is reduced to 0.3-0.6 mg/kg — about 40 mg for 68 kg, versus the usual 1.2 mg/kg (80 mg) which would be excessive. Succinylcholine is avoided altogether in myasthenia gravis because the response is unpredictable (patients are relatively resistant), so both succinylcholine options are wrong regardless of dose." },

  { id: "pe24-049", domain: "pmr", difficulty: 3, tags: ["Research Ethics", "Informed Consent"],
    stem: "Your ED is running a study comparing levetiracetam with lacosamide as initial antiepileptic treatment for status epilepticus. A key inclusion criterion is receipt of a benzodiazepine for seizure within the past 30 minutes. Exclusion criteria include use of an antiepileptic medication at home and ineligibility for a waiver of informed consent for emergency research. Which patient could be enrolled?",
    options: ["LO, a 32-year-old healthy man who received lorazepam 15 minutes ago and takes no home antiepileptics", "KM, a 26-year-old pregnant woman who received lorazepam 10 minutes ago and takes no home antiepileptics", "AL, a 48-year-old male prisoner who received midazolam 45 minutes ago and takes lisinopril", "RE, a 66-year-old woman who received midazolam 20 minutes ago and takes amlodipine and valproic acid at home"], correctIndex: 0,
    rationale: "LO is inside the 30-minute benzodiazepine window and has no exclusions. Pregnant women and prisoners are protected populations ineligible for a waiver of informed consent in emergency research, which excludes KM and AL — and AL also falls outside the 30-minute window. RE takes valproic acid, an antiepileptic, at home." },

  { id: "pe24-050", domain: "neuro", difficulty: 2, tags: ["Seizures", "Workup"],
    stem: "JM is a 42-year-old man brought in by EMS after a witnessed seizure. He has no seizure history but has hypertension and insulin-treated diabetes. A coworker reported the seizure lasted about 60 seconds with no trauma. EMS reported normal blood pressure and heart rate but had no time for further assessment during the short transport. He now seizes again in the ED. Which lab test is most appropriate to perform immediately to identify the cause?",
    options: ["Blood glucose", "Serum potassium", "White blood cell count", "Serum lactate"], correctIndex: 0,
    rationale: "He takes insulin and EMS never checked a glucose, making hypoglycemia an immediately reversible and highly likely cause. Potassium abnormalities are not a typical seizure trigger. A white count might matter if infection is suspected but is lower priority. Lactate is almost always elevated AFTER a seizure, so it reflects the seizure rather than explaining it." },

  { id: "pe24-051", domain: "neuro", difficulty: 3, tags: ["Stroke", "ICH", "Fibrinolytic Reversal"],
    stem: "LT is a 55-year-old man (100 kg) who received alteplase for acute ischemic stroke about 4 hours ago. The nurse notes mental status changes; his NIHSS has risen from 8 to 15. CT now shows a large intracerebral hemorrhage requiring reversal. His chart documents that he refuses blood products. What is the most appropriate treatment?",
    options: ["Tranexamic acid 1000 mg as an IV infusion over 10 minutes", "Cryoprecipitate 10 units as an IV infusion over 10 minutes", "Fresh frozen plasma 2 units as an IV infusion over 2 hours", "Aminocaproic acid 1000 mg as an IV infusion over 1 hour"], correctIndex: 0,
    rationale: "Cryoprecipitate is first line for post-alteplase ICH but is a plasma-derived BLOOD PRODUCT, which he refuses — so the second-line antifibrinolytic, tranexamic acid 1000 mg over 10 minutes, becomes the answer. FFP is both a blood product and not recommended for this indication. Aminocaproic acid is an option in principle but the dose is 4-5 g, not 1 g." },

  { id: "pe24-052", domain: "neuro", difficulty: 3, tags: ["Stroke", "Fibrinolysis", "Anticoagulation"],
    stem: "MB is a 68-year-old woman presenting with left-sided weakness that began 90 minutes ago. Her home medication list includes warfarin for atrial fibrillation. Her last INR, 14 days ago, was 2.7. Head CT is negative for hemorrhage and the neurologist considers her a fibrinolytic candidate by deficit. Per AHA/ASA guidelines and alteplase labeling, which statement is correct?",
    options: ["Fibrinolysis might be considered after measuring a prothrombin time or INR", "Fibrinolysis should not be used because she has been taking an oral anticoagulant", "Fibrinolysis might be considered after measuring an anti-factor Xa level", "Fibrinolysis should not be used because her last INR was therapeutic"], correctIndex: 0,
    rationale: "Warfarin use contraindicates fibrinolysis only if the CURRENT INR exceeds 1.7 or PT exceeds 15 seconds — and a 14-day-old value tells you nothing about today, especially since a subtherapeutic INR is the likely reason she stroked. Anti-Xa levels monitor factor Xa inhibitors, not warfarin. Because she takes warfarin, wait for the INR before treating; patients with no anticoagulant use or suspected coagulopathy can be treated before coagulation results return",
    source: "AHA/ASA acute ischemic stroke guidelines (2019, 2026); alteplase prescribing information", updated: "2026-11" },

  { id: "pe24-053", domain: "neuro", difficulty: 3, tags: ["Stroke", "Thrombolytics", "Dosing"],
    stem: "DK is a 45-year-old woman (55 kg) with acute ischemic stroke, NIHSS 12, symptoms starting 4 hours before arrival. CT angiography shows a large vessel occlusion and she will undergo mechanical thrombectomy. She has no contraindications to fibrinolysis and is nearing the end of the treatment window. Per AHA/ASA guidelines, which fibrinolytic regimen is most appropriate?",
    options: ["Tenecteplase 13.75 mg as an IV bolus", "Alteplase 50 mg as an IV bolus", "Tenecteplase 22 mg as an IV bolus", "Alteplase 5.8 mg IV bolus over 1 minute followed by 52.7 mg IV over 60 minutes"], correctIndex: 0,
    rationale: "The 2026 AHA/ASA guideline recommends either tenecteplase 0.25 mg/kg (max 25 mg) as a single bolus or alteplase 0.9 mg/kg for eligible patients within 4.5 hours, whether or not thrombectomy follows (class 1): 0.25 x 55 = 13.75 mg. Tenecteplase 0.4 mg/kg (22 mg) is not recommended, because it does not improve outcomes and may cause harm. Alteplase would be 0.9 mg/kg = 49.5 mg total, given as a 5-mg bolus then 44.5 mg over an hour — never as a single 50-mg bolus",
    source: "2026 AHA/ASA Guideline for the Early Management of Patients With Acute Ischemic Stroke", updated: "2026-11" },

  { id: "pe24-054", domain: "neuro", difficulty: 3, tags: ["Stroke", "Angioedema"],
    stem: "MM is a 70-year-old man receiving IV alteplase for acute ischemic stroke. Fifteen minutes into the infusion he reports tongue swelling. He is maintaining his own airway and has IV access. Per AHA/ASA guidelines, what is the most appropriate treatment?",
    options: ["Stop the alteplase infusion and give methylprednisolone 125 mg IV and diphenhydramine 50 mg IV", "Stop the alteplase infusion and give epinephrine 0.3 mg IM", "Slow the alteplase infusion and give epinephrine 0.3 mg IM", "Slow the alteplase infusion and give methylprednisolone 125 mg IV and diphenhydramine 50 mg IV"], correctIndex: 0,
    rationale: "This is orolingual angioedema, and the guideline says STOP the infusion — not slow it — then give a corticosteroid, an H1 blocker, and an H2 blocker. Epinephrine is held in reserve for when those first-line agents fail or symptoms progress, and it is given subcutaneously or by nebulization in this setting rather than routinely up front." },

  { id: "pe24-055", domain: "neuro", difficulty: 3, tags: ["Stroke", "Wake-up Stroke"],
    stem: "KP is a 60-year-old man who woke at 8 am with facial droop and speech difficulty. It is now 9 am. His last known normal was before bedtime at 11 pm the previous night. His NIHSS is 8. Per AHA/ASA guidelines, which statement about his eligibility for IV fibrinolysis is correct?",
    options: ["Fibrinolysis might be considered if he has a DW-MRI lesion smaller than one-third of the MCA territory and no visible signal change on FLAIR", "Fibrinolysis should not be used because his last known normal was more than 4.5 hours ago", "Fibrinolysis should not be used because his last known normal was more than 3 hours ago", "Fibrinolysis might be considered if he has a DW-MRI lesion greater than one-third of the MCA territory and no visible signal change on FLAIR"], correctIndex: 0,
    rationale: "Wake-up stroke is not an automatic exclusion. Based on WAKE-UP, alteplase within 4.5 hours of symptom RECOGNITION can benefit patients with unclear onset when MRI shows a DWI lesion smaller than one-third of the MCA territory with no matching FLAIR change — the mismatch implying the infarct is still young. A lesion LARGER than one-third of the territory is the opposite of the criterion." },

  { id: "pe24-056", domain: "pmr", difficulty: 2, tags: ["Pharmacist Role", "Stroke", "Quality"],
    stem: "Your comprehensive stroke center targets a door-to-needle time of 60 minutes per AHA/ASA and Joint Commission recommendations, and you have a single EM pharmacist. Which EM pharmacist role has been shown to decrease door-to-needle time in acute ischemic stroke?",
    options: ["Bedside participation in patient assessment and treatment", "Involvement in performance improvement committee activities", "Preparation of treatment guidelines", "Patient discharge counseling"], correctIndex: 0,
    rationale: "Published data, including Barbour et al. (2022), tie measurable reductions in door-to-needle time specifically to the pharmacist being AT THE BEDSIDE for assessment, medication preparation, and administration. The other activities are all professionally valuable and guideline-endorsed, but none has demonstrated an effect on this particular time metric." },

  { id: "pe24-057", domain: "neuro", difficulty: 3, tags: ["Stroke", "Blood Pressure"],
    stem: "PC is a 45-year-old woman presenting with acute ischemic stroke and no known medical history. She is not eligible for fibrinolytic therapy or mechanical thrombectomy. Blood pressure is 190/85 mm Hg, heart rate 75. Per AHA/ASA guidelines, what is the most appropriate blood pressure recommendation for the next few hours?",
    options: ["No antihypertensive treatment is warranted, because permissive hypertension is appropriate", "Nicardipine 5 mg/hr IV, with a goal below 180/105 mm Hg", "Clevidipine 2 mg/hr IV, with a goal below 185/110 mm Hg", "Nicardipine 5 mg/hr IV, with a goal reduction in MAP of 15%"], correctIndex: 0,
    rationale: "In patients NOT receiving reperfusion therapy, lowering blood pressure risks reducing perfusion to the ischemic penumbra, so permissive hypertension is the rule. The specific targets in the distractors each belong to a different scenario: below 185/110 BEFORE fibrinolysis or thrombectomy, below 180/105 AFTER it, and a 15% MAP reduction only when the pressure exceeds roughly 220/120." },

  { id: "pe24-058", domain: "safety", difficulty: 2, tags: ["ISMP", "High-Alert Medications", "Storage"],
    stem: "At your institution, bags of NaCl 3% and vials of NaCl 23.4% are stored in the main pharmacy. An incident report shows it took 1.5 hours to deliver a bag of NaCl 3% to a patient with intracerebral hemorrhage, midline shift, and concern for raised intracranial pressure. The ED team asks whether both can be stocked in the ED automated dispensing cabinet. Per ISMP recommendations, what is the most appropriate response?",
    options: ["Only NaCl 3% bags may be stocked in limited quantities with appropriate labeling", "Only NaCl 23.4% vials may be stocked in limited quantities with appropriate labeling", "Both NaCl 3% bags and NaCl 23.4% vials may be stocked in limited quantities with appropriate labeling", "Neither should be stocked in the ED cabinet regardless of labeling"], correctIndex: 0,
    rationale: "ISMP permits appropriately labeled and sequestered 3% sodium chloride bags in limited quantities in critical care and emergency areas. The 23.4% concentrate is different: pharmacy should prepare, label, and hand-deliver those doses, because an inadvertent bolus of undiluted 23.4% can be fatal. Stocking neither would perpetuate the delay this incident report identified." },

  { id: "pe24-059", domain: "cv", difficulty: 3, tags: ["ACS", "NSTEMI", "Antiplatelets"],
    stem: "JB is a 77-year-old woman presenting with a 12-hour history of left jaw and shoulder pain. Initial troponin is elevated and she is diagnosed with NSTEMI. She is hemodynamically stable and will be admitted overnight with coronary angiography planned in the morning. Which oral antiplatelet recommendation is most appropriate now?",
    options: ["Aspirin 324 mg now; choose and load the P2Y12 inhibitor once coronary anatomy is known", "Aspirin 324 mg with ticagrelor 180 mg now", "Aspirin 162 mg with clopidogrel 600 mg now", "Aspirin 162 mg with ticagrelor 90 mg now, repeated before angiography"], correctIndex: 0,
    rationale: "Aspirin 162–325 mg goes in now. The 2025 ACC/AHA ACS guideline only suggests upstream P2Y12 loading (clopidogrel or ticagrelor) when angiography will be delayed MORE than 24 hours. With angiography planned for the morning, the P2Y12 inhibitor is chosen once the anatomy is known, which avoids loading a patient who turns out to need CABG; for PCI, ticagrelor is preferred over clopidogrel (prasugrel is generally avoided at age 75 or older). Ticagrelor 90 mg is a maintenance dose, not a load. Older guidance (2014) favored loading as early as possible, which is why the load-now answer is a common trap",
    source: "2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Acute Coronary Syndromes", updated: "2026-11" },

  { id: "pe24-060", domain: "cv", difficulty: 3, tags: ["ACS", "STEMI"],
    stem: "DA is a 57-year-old man presenting with severe shortness of breath and chest pain radiating to the shoulder. ECG shows ST elevation in V3 and V4. Vitals: BP 148/112, HR 88, RR 28, SpO2 86%, pain 7/10. Chest X-ray shows pulmonary vascular congestion. He received nitroglycerin 0.4 mg sublingually in the ambulance. Which medication recommendation is most appropriate now?",
    options: ["Nitroglycerin 10 mcg/min intravenously", "Metoprolol 5 mg intravenously", "Morphine 2 mg intravenously", "Nitroglycerin 0.4 mg sublingually"], correctIndex: 0,
    rationale: "He has ongoing ischemic pain PLUS signs of acute heart failure (hypoxia, dyspnea, pulmonary congestion) and hypertension — nitroglycerin addresses all three, and an IV infusion is titratable in a way repeat sublingual dosing is not. Metoprolol is dangerous here because beta-blockade in acute decompensated heart failure raises the risk of cardiogenic shock. Morphine has a role in STEMI with pulmonary edema but is second to nitroglycerin in this presentation." },

  { id: "pe24-061", domain: "cv", difficulty: 3, tags: ["STEMI", "Fibrinolytics"],
    stem: "You are performing a class review of fibrinolytic agents for use in ambulances serving rural areas more than 120 minutes from a PCI laboratory. Which statement about fibrinolytics in STEMI is correct?",
    options: ["Tenecteplase is administered as a single IV bolus dose, which eases administration", "Alteplase dosing for STEMI is similar to that for acute ischemic stroke, reducing dose-confusion errors", "Reteplase is the most fibrin-specific agent, associated with higher rates of TIMI Grade 3 flow", "Streptokinase has the lowest antigenicity and therefore the lowest risk of allergic reactions"], correctIndex: 0,
    rationale: "Tenecteplase's single weight-based bolus is a genuine advantage in the prehospital setting, versus alteplase's bolus-plus-two-stage-infusion. Alteplase dosing for STEMI (15 mg bolus, then 0.75 mg/kg, then 0.5 mg/kg) is quite DIFFERENT from stroke dosing (0.9 mg/kg), which is a well-known source of error. Tenecteplase, not reteplase, is the most fibrin-specific. Streptokinase has the HIGHEST antigenicity." },

  { id: "pe24-062", domain: "cv", difficulty: 3, tags: ["STEMI", "Anticoagulation", "Renal Dosing"],
    stem: "BR is a 78-year-old man (79 kg) with STEMI being transferred from a non-PCI-capable facility; ground transport will take 180 minutes, so he will receive tenecteplase before transfer. Labs: troponin 0.14 ng/mL, serum creatinine 2.4 mg/dL, CBC normal (estimated creatinine clearance about 28 mL/min). Which initial anticoagulant recommendation is most appropriate?",
    options: ["Enoxaparin 80 mg subcutaneously, no IV bolus", "Enoxaparin 30 mg intravenously", "Fondaparinux 2.5 mg intravenously", "Anticoagulants are contraindicated with fibrinolytic agents"], correctIndex: 0,
    rationale: "Two adjustments stack here: age 75 or older (no IV bolus) and creatinine clearance below 30 mL/min (once-daily dosing). With CrCl below 30, the regimen at any age is 1 mg/kg SC every 24 hours with no bolus, so 79 kg rounds to 80 mg. The 0.75 mg/kg every-12-hour dose capped at 75 mg is for patients 75 or older with preserved renal function, and the 30-mg IV bolus is only for patients under 75. Fondaparinux is contraindicated below 30 mL/min. Anticoagulation is required alongside fibrinolysis to prevent reocclusion",
    source: "Enoxaparin prescribing information (STEMI dosing); ExTRACT-TIMI 25 regimen", updated: "2026-11" },

  { id: "pe24-063", domain: "cv", difficulty: 3, tags: ["STEMI", "Beta-blockers"],
    stem: "HM is a 74-year-old woman diagnosed with STEMI awaiting transport for primary PCI. While in the ED her heart rate rises to 146 bpm and she reports increased shortness of breath. The provider orders metoprolol 5 mg IV every 5 minutes for up to three doses. Based on published evidence for beta-blockers in STEMI, which statement is correct?",
    options: ["Metoprolol should not be given because it will increase her risk of cardiogenic shock", "Metoprolol should be given immediately because it will decrease ventricular remodeling", "Metoprolol should be given immediately because it will decrease her risk of ventricular arrhythmias", "Metoprolol should not be given because it will increase her myocardial oxygen demand"], correctIndex: 0,
    rationale: "Beta-blockers do reduce remodeling, arrhythmias, and oxygen demand — so the two 'give it' rationales and the 'increases oxygen demand' claim are all wrong on the pharmacology. The issue is timing and risk: within the first 24 hours the major hazard is cardiogenic shock, and risk factors include age over 70, SBP below 120, heart rate below 60 or above 110, and delayed presentation. She has at least two, so metoprolol should be withheld." },

  { id: "pe24-064", domain: "cv", difficulty: 3, tags: ["STEMI", "Fibrinolysis", "Antiplatelets"],
    stem: "ST is a 78-year-old woman who presented 30 minutes after onset of chest pain with diaphoresis and nausea, diagnosed with STEMI. After discussing risks and benefits she refuses PCI and prefers fibrinolytic therapy. Which oral antiplatelet recommendation is most appropriate?",
    options: ["Aspirin 324 mg and clopidogrel 75 mg", "Aspirin 324 mg and prasugrel 60 mg", "Aspirin 324 mg and clopidogrel 300 mg", "Antiplatelet therapy should not be given with fibrinolytic therapy because of bleeding risk"], correctIndex: 0,
    rationale: "Dual antiplatelet therapy IS given with fibrinolysis, but the P2Y12 choice narrows: clopidogrel is used because ticagrelor and prasugrel carry excess bleeding risk in this combination. The clopidogrel load is then age-dependent — 300 mg for patients 75 or younger, but only 75 mg for those over 75, which applies to this 78-year-old." },

  { id: "pe24-065", domain: "cv", difficulty: 2, tags: ["ACS", "Diagnosis"],
    stem: "TJ is a 62-year-old man presenting with substernal chest pain that began after yard work. A 12-lead ECG on arrival shows ST-segment DEPRESSION in leads II, III, and aVF, and troponin is 7.62 ng/mL. What is the most appropriate classification of acute coronary syndrome?",
    options: ["Non-ST-elevation myocardial infarction", "ST-elevation myocardial infarction, inferior", "ST-elevation myocardial infarction, anterior", "Unstable angina"], correctIndex: 0,
    rationale: "Classification turns on two inputs: the ECG and the troponin. There is no ST ELEVATION, so neither STEMI option applies despite the inferior lead distribution. Troponin is clearly elevated, which excludes unstable angina (cardiac symptoms with a normal troponin). Depression plus positive biomarker equals NSTEMI." },

  { id: "pe24-066", domain: "cv", difficulty: 3, tags: ["Cardiogenic Shock", "Inotropes"],
    stem: "A 79-year-old man presents with blood pressure 88/62 mm Hg (MAP 71) and heart rate 72 bpm. He is pale with cold extremities and was treated at your facility for a myocardial infarction 10 days ago. A 1000-mL IV bolus of 0.9% sodium chloride is given emergently with no effect. Which is the most appropriate initial agent for his acute condition?",
    options: ["Dobutamine by continuous IV infusion", "Bumetanide 1 mg as a one-time IV bolus", "Nitroglycerin 2000 mcg as a one-time IV bolus", "Epinephrine by continuous IV infusion"], correctIndex: 0,
    rationale: "Cold extremities with low blood pressure after a recent MI is cardiogenic shock — a low cardiac output problem. With MAP still above 65, an inotrope such as dobutamine is the first agent and can bridge to mechanical circulatory support; if MAP falls below 65, start norepinephrine first, because dobutamine's vasodilation can drop the pressure further. A diuretic or a nitrate would each lower his pressure. Epinephrine is not first line: in a randomized trial of post-MI cardiogenic shock (OptimaCC) it caused more refractory shock than norepinephrine",
    source: "2025 ACC/AHA ACS guideline (cardiogenic shock); AHA scientific statement on cardiogenic shock (2017); OptimaCC trial (2018)", updated: "2026-11" },

  { id: "pe24-067", domain: "cv", difficulty: 2, tags: ["Heart Failure", "Diuretics"],
    stem: "A 66-year-old woman with coronary artery disease presents with a week of increasing weight and peripheral edema. Blood pressure 126/85, heart rate 65. Home medications are metoprolol tartrate 50 mg twice daily, lisinopril 5 mg daily, and aspirin 81 mg daily — she is on no diuretic. Which initial IV diuretic and dose is most appropriate?",
    options: ["Bumetanide 1 mg", "Metolazone 5 mg", "Torsemide 20 mg", "Furosemide 80 mg"], correctIndex: 0,
    rationale: "In a diuretic-naive patient, bumetanide 1 mg IV is an appropriate first dose. Furosemide is equally reasonable as a drug choice but the starting dose would be 20-40 mg, not 80 mg. The other two fail on formulation rather than dose: metolazone has no IV form, and IV torsemide is no longer available." },

  { id: "pe24-068", domain: "cv", difficulty: 3, tags: ["Heart Failure", "Pulmonary Edema"],
    stem: "A 62-year-old man with end-stage renal failure and hemodialysis nonadherence presents with acute heart failure and pulmonary edema. Blood pressure 185/110, heart rate 85. He is started emergently on noninvasive positive pressure ventilation and you are consulted about pharmacotherapy. Which therapy is most appropriate now?",
    options: ["Nitroglycerin 125 mcg/min by continuous IV infusion", "Nitroprusside 0.3 mcg/kg/min by continuous IV infusion", "Captopril 25 mg orally x 1 dose", "Furosemide 80 mg IV x 1 dose"], correctIndex: 0,
    rationale: "Hypertensive acute heart failure with flash pulmonary edema is primarily an afterload problem, and high-dose IV nitroglycerin providing venous and arterial vasodilation is the fastest way to prevent intubation. Nitroprusside is avoided in severe renal disease because cyanide and thiocyanate accumulate. Oral captopril is impractical on noninvasive ventilation. Diuresis is of limited value in an anuric dialysis patient and is less effective than nitrates at averting intubation." },

  { id: "pe24-069", domain: "cv", difficulty: 3, tags: ["Heart Failure", "High-Output", "Vasopressors"],
    stem: "A 68-year-old man with high-output heart failure presents with blood pressure 72/35 mm Hg and heart rate 101 bpm. He is short of breath, has WARM extremities, and has not urinated in 48 hours. Which is the most appropriate initial agent for his acute condition?",
    options: ["Norepinephrine", "Nitroglycerin", "Furosemide", "Dobutamine"], correctIndex: 0,
    rationale: "Warm extremities with hypotension signal inappropriate peripheral VASODILATION, not pump failure — the opposite of cardiogenic shock. A vasoconstrictor such as norepinephrine is the short-term answer while the underlying cause is found. Nitroglycerin would worsen the vasodilation, diuresis does not address a non-fluid-overload problem, and dobutamine would aggravate an already high-output state." },

  { id: "pe24-070", domain: "cv", difficulty: 3, tags: ["Atrial Fibrillation", "Cardioversion"],
    stem: "A 64-year-old man presents with worsening shortness of breath and atrial fibrillation with rapid ventricular response. Blood pressure 82/61, heart rate 126. His history is notable only for heart failure with an ejection fraction of 30%. Point-of-care ultrasound shows pulmonary edema. Which therapy is most appropriate now?",
    options: ["Synchronized electrical cardioversion", "Transcutaneous pacing", "Metoprolol tartrate 5 mg IV bolus", "Diltiazem 0.25 mg/kg IV bolus"], correctIndex: 0,
    rationale: "Hypotension plus pulmonary edema attributable to the arrhythmia makes him unstable, so immediate synchronized cardioversion is indicated. Both rate-control drugs are negative inotropes that would deepen the hypotension and worsen the failing ventricle. Pacing treats bradycardia, and he is tachycardic." },

  { id: "pe24-071", domain: "endo", difficulty: 3, tags: ["Hyperkalemia", "Insulin"],
    stem: "A 58-year-old man presents with difficulty urinating. He has heart failure and his lisinopril dose was recently increased. Labs: serum creatinine 3.2 mg/dL, potassium 6.2 mEq/L, glucose 104 mg/dL. ECG shows peaked T waves and sinus bradycardia. Which insulin regimen do you recommend for his hyperkalemia?",
    options: ["Regular insulin 5 units intravenously", "Regular insulin 10 units intravenously", "Insulin aspart 5 units subcutaneously", "Insulin aspart 10 units subcutaneously"], correctIndex: 0,
    rationale: "ECG changes mean he needs a rapid onset, so the IV route is required and both subcutaneous options are out. The dose is then reduced to 5 units because he is euglycemic (104 mg/dL) with impaired renal clearance — the combination that drives post-treatment hypoglycemia with the traditional 10 units. Dextrose should accompany the insulin." },

  { id: "pe24-072", domain: "cv", difficulty: 3, tags: ["Heart Failure", "Diuretics", "Dose Conversion"],
    stem: "A 56-year-old man with heart failure presents with shortness of breath and edema of the feet, ankles, and lower legs, with progressive weight gain over recent weeks. Blood pressure 120/80, heart rate 66. Home medications include lisinopril 20 mg daily, metoprolol succinate 50 mg daily, and furosemide 40 mg ORALLY daily. He is admitted and home medications are stopped. Which initial IV diuretic is most appropriate?",
    options: ["Furosemide 40 mg", "Bumetanide 0.25 mg", "Bumetanide 0.5 mg", "Furosemide 20 mg"], correctIndex: 0,
    rationale: "The initial IV loop dose should equal or exceed the total daily ORAL dose — 1 to 2.5 times it, milligram for milligram, as in the DOSE trial. His home dose is furosemide 40 mg orally, so 40 mg IV (1x) is the lowest appropriate dose, with up to 100 mg IV reasonable. On any common conversion, bumetanide 0.25 mg and 0.5 mg equal no more than about 20 mg of furosemide, and furosemide 20 mg is half his home dose; each would under-diurese him",
    source: "2022 AHA/ACC/HFSA Heart Failure Guideline; DOSE trial (NEJM 2011)", updated: "2026-11" },

  { id: "pe24-073", domain: "cv", difficulty: 2, tags: ["Dysrhythmia", "ECG"],
    stem: "An 83-year-old man self-presents with palpitations that started this morning. He is awake, alert, and communicating. Heart rate 173, blood pressure 122/76 (MAP 91), respiratory rate 16, SpO2 97%. A 12-lead ECG shows a tachycardic rhythm with a wide QRS of 132 ms; the complexes are regular in rhythm and uniform in appearance. What is the most likely arrhythmia?",
    options: ["Monomorphic ventricular tachycardia", "Polymorphic ventricular tachycardia", "Atrial fibrillation with rapid ventricular rate", "Ventricular fibrillation"], correctIndex: 0,
    rationale: "Three features settle it: QRS above 120 ms (wide), regular rhythm, and uniform complex morphology — the definition of monomorphic VT. Polymorphic VT shows continuously varying QRS amplitude. Atrial fibrillation is characteristically IRREGULAR. Ventricular fibrillation is chaotic and would not leave a patient awake and conversant." },

  { id: "pe24-074", domain: "cv", difficulty: 3, tags: ["Dysrhythmia", "Procainamide", "Monitoring"],
    stem: "A 62-year-old patient with atrial fibrillation and rapid ventricular rate is receiving a procainamide infusion for chemical cardioversion. At initiation: heart rate 164, blood pressure 144/90 (MAP 108), respiratory rate 14, SpO2 98%. The 12-lead ECG showed a narrow complex irregular tachycardia with QRS 82 ms and QTc measured at 408 ms. Absent other symptoms, which change would indicate stopping the infusion?",
    options: ["A repeat ECG revealing a QRS duration of 126 ms", "A repeat blood pressure of 110/78 mm Hg (MAP 89)", "A repeat ECG revealing a QTc duration of 448 ms", "A reduction in oxygen saturation to 94%"], correctIndex: 0,
    rationale: "Procainamide is a sodium channel blocker, and QRS widening of 50% or more without resolution of the arrhythmia is a defined stopping point: 82 ms to 126 ms is a 54% increase. The blood pressure drop is modest, asymptomatic, and could equally reflect the arrhythmia. The QTc change is small and unreliable anyway because QTc calculation depends on R-R intervals, which are irregular in atrial fibrillation. Procainamide does not meaningfully affect oxygenation." },

  { id: "pe24-075", domain: "cv", difficulty: 3, tags: ["Dysrhythmia", "Cardioversion"],
    stem: "A 78-year-old patient is brought in by ambulance with chest pain. A 12-lead ECG reveals a wide complex tachycardia with regular rhythm identified as ventricular tachycardia. Blood pressure is 64/42 mm Hg (MAP 39). Which therapy is most appropriate now?",
    options: ["Synchronized cardioversion using 100 J", "Procainamide 10 mg/kg as an IV infusion over 30 minutes", "Amiodarone 150 mg as an IV infusion over 15 minutes", "Electrical defibrillation using 200 J"], correctIndex: 0,
    rationale: "A MAP of 39 with chest pain is unstable VT WITH a pulse, so electricity is needed faster than any infusion can work — ruling out both procainamide and amiodarone, which are for stable VT. Because a pulse is present the shock must be SYNCHRONIZED to the R wave; an unsynchronized defibrillation could land in the repolarization phase and induce ventricular fibrillation." },

  { id: "pe24-076", domain: "resus", difficulty: 3, tags: ["Cardiac Arrest", "Antiarrhythmics"],
    stem: "A 48-year-old patient had a bystander-witnessed cardiac arrest with bystander CPR. Paramedics report ventricular fibrillation and one defibrillation attempt in the field before ED arrival. In addition to high-quality chest compressions, which intervention may improve the chance of survival to hospital discharge?",
    options: ["Lidocaine 100 mg as an IV bolus over 1 minute", "Endotracheal intubation", "Alteplase 50 mg as an IV bolus over 2 minutes", "Amiodarone 150 mg as an IV bolus over 10-15 minutes"], correctIndex: 0,
    rationale: "The ALPS trial showed lidocaine or amiodarone improved survival to hospital discharge in witnessed out-of-hospital arrest. Lidocaine 1-1.5 mg/kg rounds to 100 mg with available vial sizes, so this option is correctly dosed. The amiodarone option is the right drug at the WRONG dose — arrest dosing is 300 mg push, not 150 mg. Intubation has not been shown to improve survival to discharge, and alteplase applies only when pulmonary embolism is suspected." },

  { id: "pe24-077", domain: "cv", difficulty: 3, tags: ["Pulmonary Embolism", "Thrombolysis"],
    stem: "A 32-year-old patient presents with dyspnea, pleuritic chest pain, and hemoptysis. History includes diabetes and opioid use disorder with injection drug use. Vitals: HR 128, BP 82/50 (MAP 61) persisting after a fluid bolus, RR 26, SpO2 88% on room air improving to 93% on a non-rebreather. CT pulmonary angiography shows a large saddle embolus extending into both main pulmonary arteries, and bedside ultrasound shows septal bowing indicating right heart strain. The team chooses systemic thrombolysis. Which regimen is most appropriate?",
    options: ["Alteplase 100 mg IV administered over 2 hours", "Alteplase 50 mg as an IV bolus over 2 minutes", "Alteplase 50 mg IV administered over 1 hour", "Apixaban 10 mg orally twice daily for 7 days then 5 mg twice daily"], correctIndex: 0,
    rationale: "Persistent hypotension with right heart strain is AHA/ACC PE category E (cardiopulmonary failure), where the guideline calls advanced reperfusion reasonable: systemic thrombolysis, catheter-directed therapy, or mechanical thrombectomy. For systemic lysis the FDA-labeled regimen is alteplase 100 mg over 2 hours. The 50-mg bolus is reserved for cardiac arrest, and half-dose regimens have been studied mainly in normotensive patients. Apixaban is an anticoagulant, not a thrombolytic. Had he stayed normotensive with RV strain (category C), anticoagulation would be the default: the guideline rates systemic thrombolysis as harmful in categories A to C2 and of unclear benefit in C3",
    source: "2026 AHA/ACC Guideline for the Evaluation and Management of Acute Pulmonary Embolism; alteplase prescribing information", updated: "2026-11" },

  { id: "pe24-078", domain: "resus", difficulty: 3, tags: ["Cardiac Arrest", "Pulmonary Embolism", "IO Access"],
    stem: "The same 32-year-old with a saddle pulmonary embolus is being prepared for thrombolysis when the nurse finds the only IV site has infiltrated. While new access is attempted the patient loses consciousness with no palpable femoral pulse. Chest compressions begin and an intraosseous catheter is placed in the proximal tibia. Which alteplase regimen is most appropriate now?",
    options: ["Alteplase 50 mg as a bolus administered IO over 2 minutes", "Alteplase 50 mg as a bolus IV over 2 minutes after establishing IV access", "Alteplase 100 mg as an infusion IV over 2 hours after establishing IV access", "Alteplase is contraindicated with active chest compressions"], correctIndex: 0,
    rationale: "Cardiac arrest changes the regimen to a 50-mg bolus, and the access question answers itself: IV is preferred in principle, but waiting for it while the patient is in PE-associated arrest costs more than the IO route does. A 2-hour infusion is meaningless during arrest. Compressions are not a contraindication — mortality exceeds 90% without thrombolysis, which outweighs the added bleeding risk." },

  { id: "pe24-079", domain: "resus", difficulty: 3, tags: ["Cardiac Arrest", "Pulmonary Embolism"],
    stem: "The 32-year-old with a saddle pulmonary embolus is in cardiac arrest and has received alteplase. Fifteen minutes later there is still no return of spontaneous circulation. What should be done next, and how long should resuscitation continue?",
    options: ["Give an additional 50-mg bolus IV/IO, then continue resuscitation for at least 15 minutes and as long as 60-90 minutes", "Continue resuscitation for at least 15 minutes and up to 60-90 minutes without additional alteplase", "Continue resuscitation for at least 10 minutes and up to 30-60 minutes without additional alteplase", "Give unfractionated heparin IV/IO as an infusion and continue resuscitation for 60-90 minutes"], correctIndex: 0,
    rationale: "No ROSC 15 minutes after the first alteplase bolus is commonly treated with a SECOND 50-mg bolus, then continued CPR for at least 15 and up to 60–90 minutes to let the drug circulate and lyse clot. Note the evidence base: this is protocol practice drawn from case series, and no guideline sets a dose. Full anticoagulation follows if ROSC is achieved, but heparin during arrest is unlikely to help and should not displace further thrombolytic dosing",
    source: "Alteplase dosing references (e.g., Lexicomp); case series of thrombolysis in PE-related cardiac arrest", updated: "2026-11" },

  { id: "pe24-080", domain: "resus", difficulty: 3, tags: ["Cardiac Arrest", "PEA"],
    stem: "A 72-year-old man in cardiac arrest arrives by ambulance after arresting en route with chest pain. Initial rhythm was pulseless ventricular tachycardia; prehospital care included lidocaine 100 mg IV, epinephrine 1 mg IV x 2 (last dose 5 minutes before arrival), and two defibrillation attempts. On the next rhythm check the monitor shows a narrow QRS complex at 76 bpm consistent with sinus rhythm, but there is no pulse. What medication should be administered next?",
    options: ["Epinephrine 1 mg IV bolus", "Amiodarone 300 mg IV bolus", "Lidocaine 100 mg IV bolus", "Atropine 1 mg IV bolus"], correctIndex: 0,
    rationale: "An organized rhythm without a pulse is pulseless electrical activity, where epinephrine every 3-5 minutes plus high-quality CPR is the treatment — and his last dose was 5 minutes ago, so another is due. Antiarrhythmics such as amiodarone and lidocaine apply only to VF or pulseless VT, which this no longer is. Atropine is for symptomatic bradycardia with a pulse and has no role in PEA." },

  { id: "pe24-081", domain: "cv", difficulty: 3, tags: ["Bradycardia", "ACLS"],
    stem: "A 70-year-old woman is brought in with altered mental status after a syncopal event. Vitals: HR 36, BP 82/30 (MAP 47), RR 16, SpO2 93%, GCS 11. History includes hypertension, hypercholesterolemia, and COPD; medications include atorvastatin, diltiazem, hydrochlorothiazide, and metformin. In addition to placing transcutaneous pacing pads, which medication should be given first?",
    options: ["Atropine 1 mg IV x 1", "Glucagon 5 mg IV x 1", "Midazolam 2 mg IV and fentanyl 50 mcg IV", "Phenylephrine infusion at 25 mcg/min titrated to MAP above 65"], correctIndex: 0,
    rationale: "Atropine is the first-line drug for symptomatic bradycardia and is given while preparing pacing or a chronotropic infusion. Glucagon targets beta-blocker toxicity and is unreliable for non-dihydropyridine calcium channel blockers. Sedation is desirable before pacing but she is too unstable to receive it first. Phenylephrine is a pure alpha agonist — it raises vascular tone without any chronotropic effect, so epinephrine or dopamine would be the appropriate infusion choice." },

  { id: "pe24-082", domain: "cv", difficulty: 3, tags: ["Atrial Fibrillation", "Cardioversion"],
    stem: "A 48-year-old man presents after his smartwatch alerted him to an irregular heartbeat. He feels his heart 'fluttering' but is otherwise asymptomatic. Heart rate varies 170-190, blood pressure 112/64 (MAP 80). ECG shows atrial fibrillation with rapid ventricular rate. He has no medical history and is confident symptoms began about 6 hours ago. Which strategy is most appropriate to resolve his symptoms urgently?",
    options: ["Direct current synchronized cardioversion at 200 J", "Amiodarone 150 mg IV over 15 minutes", "Procainamide 1000 mg IV over 30 minutes", "Flecainide 300 mg orally"], correctIndex: 0,
    rationale: "Onset is reliably under 48 hours and he is healthy with no contraindication to sedation, so an electrical-cardioversion-first strategy restores rhythm fastest. The 2025 AHA guidelines advise starting at 200 J or more with a biphasic device, because lower first shocks succeed less often. Procainamide works but takes 30–60 minutes, amiodarone is slower still (8–12 hours) and less effective acutely, and 'pill in the pocket' flecainide takes 3–8 hours and should be reserved for patients previously cardioverted under supervision",
    source: "2025 AHA Adult Advanced Life Support guidelines; 2023 ACC/AHA/ACCP/HRS Atrial Fibrillation Guideline", updated: "2026-11" },

  { id: "pe24-083", domain: "special", difficulty: 3, tags: ["Pregnancy", "Nausea and Vomiting"],
    stem: "An 8-weeks-pregnant patient presents with severe nausea and vomiting, unable to keep food or water down for more than 72 hours, feeling weak and dizzy. She has already tried smaller meals, adjusted mealtimes, ginger, and vitamin B6 without relief. In addition to IV fluids, which intervention is most appropriate per ACOG recommendations?",
    options: ["Metoclopramide 10 mg intravenously", "Ondansetron 8 mg intravenously", "Doxylamine 12.5 mg orally", "Ondansetron 4 mg intravenously"], correctIndex: 0,
    rationale: "Because of a possible small increase in cardiac defects and oral clefts, ACOG says ondansetron use before 10 weeks of gestation should be individualized, so at 8 weeks it is not the best first choice — the issue is timing, not dose. IV metoclopramide is one of ACOG's options for a patient needing IV fluids, with comparable efficacy in hyperemesis. Doxylamine-pyridoxine is safe and effective, but oral therapy is impractical in someone vomiting everything for 72 hours",
    source: "ACOG Practice Bulletin 189: Nausea and Vomiting of Pregnancy (2018)", updated: "2026-11" },

  { id: "pe24-084", domain: "special", difficulty: 3, tags: ["Pregnancy", "Severe Hypertension"],
    stem: "SD is a 37-year-old woman at 18 weeks 3/7 days gestation with systemic lupus erythematosus, presenting with fatigue and lower extremity swelling. She is on a cardiac monitor with IV access established. Blood pressure is 220/101 with HR 89; repeat 15 minutes later is 223/117 with HR 91. Per ACOG guidelines, which antihypertensive is most appropriate?",
    options: ["IV labetalol", "IV nicardipine", "Oral labetalol", "Oral immediate-release nifedipine"], correctIndex: 0,
    rationale: "Two severe readings 15 minutes apart require urgent treatment, and ACOG's first-line options are IV labetalol, IV hydralazine, and oral immediate-release nifedipine. With IV access already established, IV is preferred over oral. Immediate-release nifedipine is a reasonable oral option, but it can cause reflex tachycardia, headache, and flushing, and with IV access already in place IV labetalol works faster to titrate. Nicardipine is not an ACOG first-line agent for acute severe hypertension",
    source: "ACOG Committee Opinion 767: Emergent Therapy for Acute-Onset, Severe Hypertension During Pregnancy and the Postpartum Period (2019)", updated: "2026-11" },

  { id: "pe24-085", domain: "special", difficulty: 3, tags: ["Pregnancy", "Refractory Hypertension"],
    stem: "SD, 37 years old at 18 weeks 3/7 days gestation, presented with blood pressure 223/117 mm Hg. She has received three intermittent IV boluses of labetalol and three of hydralazine with minimal response; blood pressure is now 199/110. New labs: BUN 56 mg/dL, serum creatinine 1.9 mg/dL. What agent and blood pressure goal do you recommend?",
    options: ["Nicardipine IV infusion at 5 mg/hr titrated to effect, goal 140-150/90-100 mm Hg", "Nitroprusside IV infusion at 0.1 mcg/kg/min titrated to effect, goal 140-150/90-100 mm Hg", "Labetalol IV infusion at 1 mg/min titrated to effect, goal below 150/100 mm Hg", "Hydralazine 20 mg IV every 20 minutes titrated to effect, goal below 150/100 mm Hg"], correctIndex: 0,
    rationale: "She failed intermittent boluses of both first-line agents, so a rapidly titratable continuous infusion is the logical next step — and repeating either failed drug is unlikely to help. Nicardipine has a good safety record in pregnancy. Nitroprusside is last-line here because renal dysfunction increases cyanide and thiocyanate accumulation. ACOG's goal is not normal BP but 140-150/90-100, avoiding precipitous drops that could reduce placental perfusion",
    source: "ACOG Committee Opinion 767 (2019)", updated: "2026-11" },

  { id: "pe24-086", domain: "special", difficulty: 3, tags: ["Pregnancy", "Preeclampsia", "Magnesium"],
    stem: "SD, at 18 weeks 3/7 days gestation with severe hypertension (200/110 mm Hg), reports a headache despite labetalol boluses and a nicardipine infusion. BUN is 56 mg/dL and serum creatinine 1.9 mg/dL. After starting additional antihypertensive therapy, what is the most appropriate next step?",
    options: ["Start IV magnesium sulfate with a 4-g load followed by 1 g/hr, because she has preeclampsia with severe features", "Start IV valproic acid 500 mg for the headache and eclampsia prophylaxis", "Order urine protein, platelet count, and liver function tests to confirm preeclampsia with severe features before starting magnesium", "Order urine protein, platelet count, and liver function tests to evaluate for HELLP syndrome before starting magnesium"], correctIndex: 0,
    rationale: "Severe-range hypertension plus a creatinine above 1.1 mg/dL already establishes preeclampsia with severe features, so seizure prophylaxis with magnesium (4-g load, then 1 g/hr) should not wait on further labs. Those additional tests are worth sending to characterize the disease and detect HELLP, but they must not delay magnesium. Valproic acid is a teratogen and has no role here." },

  { id: "pe24-087", domain: "special", difficulty: 2, tags: ["Pregnancy", "Pulmonary Embolism", "Imaging"],
    stem: "Which statement about ventilation/perfusion scans versus CT pulmonary angiography for evaluating pregnant patients with suspected pulmonary embolism is correct, per ACOG and ATS guidance?",
    options: ["V/Q scans are associated with the same fetal radiation exposure but lower maternal radiation exposure compared with CTPA", "V/Q scans are associated with higher fetal radiation exposure but the same maternal exposure compared with CTPA", "V/Q scans are associated with lower fetal radiation exposure but higher maternal exposure compared with CTPA", "V/Q scans are associated with the same fetal radiation exposure but higher maternal exposure compared with CTPA"], correctIndex: 0,
    rationale: "The counterintuitive point is that FETAL dose is essentially the same for both modalities; the difference is MATERNAL exposure, which is lower with V/Q — relevant because CTPA delivers substantial dose to breast tissue. Neither test has clearly superior diagnostic performance for PE in pregnancy, so the choice often turns on availability and chest radiograph findings." },

  { id: "pe24-088", domain: "special", difficulty: 3, tags: ["Pregnancy", "VTE", "Anticoagulation"],
    stem: "DR is a 35-year-old woman at 25 weeks 5/7 days gestation with asthma, presenting with fatigue and lower extremity swelling. Height 5'3\", weight 148 lb, HR 98, BP 135/76, RR 18-20, SpO2 95% on room air. BUN 14 mg/dL, creatinine 1.3 mg/dL. Lower extremity Doppler confirms a non-occlusive DVT in the left lower leg, and the team is concerned about pulmonary embolism. What is most appropriate now?",
    options: ["Initiate subcutaneous enoxaparin 1 mg/kg every 12 hours without further imaging", "Image the chest to rule out PE and start subcutaneous enoxaparin 1 mg/kg every 12 hours while awaiting results", "Image the chest to rule out PE and start oral apixaban 5 mg twice daily while awaiting results", "Initiate oral apixaban 5 mg twice daily without further imaging"], correctIndex: 0,
    rationale: "The DVT is already confirmed and treatment would be identical whether or not a PE is also present, so chest imaging adds radiation without changing management — and she is hemodynamically stable, so there is no concern for massive PE requiring thrombolysis. Direct oral anticoagulants such as apixaban are recommended AGAINST in pregnancy by both ACCP and ACOG because of limited data and fetal risk." },

  { id: "pe24-089", domain: "special", difficulty: 2, tags: ["Pregnancy", "VTE", "Anticoagulation"],
    stem: "Which statement about choosing between low molecular weight heparin and unfractionated heparin for prophylaxis and treatment of venous thromboembolism in pregnancy is correct, per ACCP and ACOG guidelines?",
    options: ["LMWH is preferred because of its fewer side effects", "UFH is preferred because aPTT or anti-Xa levels can be monitored for therapeutic efficacy", "UFH is preferred because of its fewer side effects", "LMWH is preferred because anti-Xa levels can be monitored for therapeutic efficacy"], correctIndex: 0,
    rationale: "LMWH is preferred, and the reason is its side effect and convenience profile — less bleeding, heparin-induced thrombocytopenia, and osteoporosis than UFH, and once- or twice-daily dosing versus up to three times daily (neither heparin crosses the placenta). The monitoring-based rationales are backwards: needing routine anti-Xa or aPTT monitoring is a DISADVANTAGE of UFH, and routine monitoring is not required with LMWH in pregnancy",
    source: "ACOG Practice Bulletin 196: Thromboembolism in Pregnancy; ASH 2018 VTE in pregnancy guideline", updated: "2026-11" },

  { id: "pe24-090", domain: "endo", difficulty: 3, tags: ["DKA", "Insulin", "Potassium"],
    stem: "JR is a 62-year-old man with malaise, polydipsia, and palpitations. History includes type 2 diabetes, hypertension, hyperthyroidism, and hyperlipidemia. Vitals: BP 132/88, HR 145, RR 24. Labs: glucose 650 mg/dL, Na 148, K 2.5 mmol/L, creatinine 2.3 mg/dL, bicarbonate 10 mEq/L, anion gap 22, pH 7.1, beta-hydroxybutyrate 14 mmol/L. In addition to IV fluid resuscitation, what is the most appropriate initial management?",
    options: ["Replete potassium to above 3.5 mmol/L, then start regular insulin IV at 0.1 units/kg/hr titrated to lower glucose about 50 mg/dL/hr", "Replete potassium to above 3.5 mmol/L, then start regular insulin IV at 1 unit/kg/hr titrated to lower glucose about 50 mg/dL/hr", "Start regular insulin IV at 1 unit/kg/hr titrated to lower glucose about 50 mg/dL/hr", "Start regular insulin IV at 0.1 units/kg/hr titrated to lower glucose about 50 mg/dL/hr"], correctIndex: 0,
    rationale: "This is DKA (hyperglycemia, pH below 7.3, bicarbonate below 18, beta-hydroxybutyrate of 3 mmol/L or more). Two things must both be right: the potassium of 2.5 must be corrected above 3.5 BEFORE insulin (the 2024 consensus threshold; the 2009 statement used 3.3), because insulin drives potassium intracellularly and can precipitate life-threatening hypokalemia and arrhythmia; and the infusion rate is 0.1 units/kg/hr, not 1 unit/kg/hr, which would be a tenfold overdose",
    source: "Umpierrez GE, et al. Hyperglycemic crises in adults with diabetes: a consensus report (ADA/EASD/JBDS/AACE/DTS). Diabetes Care 2024", updated: "2026-11" },

  { id: "pe24-091", domain: "endo", difficulty: 2, tags: ["DKA", "Bicarbonate"],
    stem: "For the same patient JR, with DKA and a pH of 7.1, a resident asks about starting a sodium bicarbonate IV infusion. What is the most appropriate response?",
    options: ["Do not start sodium bicarbonate, because his pH is 7.0 or higher", "Do not start sodium bicarbonate, because his pH is greater than 6.9", "Start sodium bicarbonate 150 mEq in 1 L of sterile water at 100 mL/hr", "Start sodium bicarbonate 150 mEq in 1 L of dextrose 5% in water at 100 mL/hr"], correctIndex: 0,
    rationale: "The 2024 consensus recommends against routine bicarbonate and reserves it for severe acidosis with pH below 7.0; his pH is 7.1, so it is not indicated. The 'greater than 6.9' option cites the older 2009 threshold (pH below 6.9), which the 2024 report replaced. Fluids and insulin correct the acidosis",
    source: "Umpierrez GE, et al. Hyperglycemic crises in adults with diabetes: a consensus report. Diabetes Care 2024", updated: "2026-11" },

  { id: "pe24-092", domain: "endo", difficulty: 3, tags: ["Thyroid Storm", "Thionamides"],
    stem: "OM is a 28-year-old woman presenting with chest pain, epigastric pain, and mild dyspnea unrelieved by breathing treatments, plus 40-50 lb weight loss over 3-4 months. HR 155, BP 94/70, RR 24, temp 100.5°F, with an enlarged non-tender thyroid. TSH is undetectable and T3 is 18.5 pg/mL; pH 7.465, lactate 2.1 mmol/L. Burch-Wartofsky score is 45. Which oral therapy should be given INITIALLY for her thyrotoxicosis?",
    options: ["Propylthiouracil 400 mg x 1", "Potassium iodide (1 g/mL) 5 drops x 1", "Carvedilol 6.25 mg x 1", "Acetaminophen 650 mg x 1"], correctIndex: 0,
    rationale: "Sequence is everything in thyroid storm: a thionamide such as propylthiouracil must come FIRST to block new hormone synthesis, because giving iodine first would supply substrate and worsen the storm. Iodine follows about an hour later. Beta-blockade is part of therapy but propranolol or esmolol are the agents used, not carvedilol. Acetaminophen treats fever but not the underlying process." },

  { id: "pe24-093", domain: "endo", difficulty: 3, tags: ["Thyroid Storm", "Atrial Fibrillation"],
    stem: "OM, the 28-year-old with suspected thyroid storm (Burch-Wartofsky 45), has been in the ED 20 minutes when her rhythm changes to atrial fibrillation at 160 bpm with blood pressure 108/64 mm Hg. Which intervention is most appropriate?",
    options: ["Esmolol IV infusion starting at 50 mcg/kg/min, titrated in 25-mcg/kg/min increments every 10 minutes to a maximum of 300 mcg/kg/min", "Esmolol IV infusion starting at 5 mcg/kg/min, titrated in 25-mcg/kg/min increments every 10 minutes to a maximum of 300 mcg/kg/min", "Amiodarone 150 mg IV over 10 minutes, then 1 mg/min for 6 hours and 0.5 mg/min for 18 hours", "Amiodarone 300 mg IV over 10 minutes, then 1 mg/min for 6 hours and 0.5 mg/min for 18 hours"], correctIndex: 0,
    rationale: "Esmolol is ideal for thyrotoxic atrial fibrillation with borderline blood pressure because its rapid on-off kinetics allow retreat if she destabilizes; the correct starting rate is 50 mcg/kg/min, targeting a heart rate below 110. Amiodarone must be avoided in thyrotoxicosis regardless of dose — it is iodine-rich and can fuel further thyroid hormone production." },

  { id: "pe24-094", domain: "endo", difficulty: 3, tags: ["DKA", "Subcutaneous Insulin"],
    stem: "A 50-year-old man is diagnosed with moderate diabetic ketoacidosis. ED staff are unable to obtain venous access. Which subcutaneous insulin regimen is most appropriate?",
    options: ["Insulin aspart 0.3 unit/kg x 1 dose, then 0.1 unit/kg every hour", "Insulin aspart 1 unit/kg x 1 dose, then 0.1 unit/kg every hour", "Regular insulin 0.3 unit/kg x 1 dose, then 0.1 unit/kg every hour", "Regular insulin 1 unit/kg x 1 dose, then 0.1 unit/kg every hour"], correctIndex: 0,
    rationale: "Subcutaneous protocols for mild-to-moderate DKA use a RAPID-acting analog such as aspart; regular insulin given subcutaneously has a long enough tail that hourly dosing stacks and overtreats. The loading dose is 0.3 unit/kg followed by 0.1 unit/kg hourly — the 1 unit/kg options are more than triple the appropriate load. The 2024 consensus recommends subcutaneous rapid-acting insulin for most uncomplicated mild-to-moderate DKA",
    source: "Umpierrez GE, et al. Diabetes Care 2024 (hyperglycemic crises consensus)", updated: "2026-11" },

  { id: "pe24-095", domain: "endo", difficulty: 2, tags: ["Gastroparesis", "Counseling"],
    stem: "Which represents appropriate treatment plus counseling for a patient with diabetic gastroparesis?",
    options: ["Metoclopramide 10 mg orally four times daily; smaller, more frequent meals and decreased dietary fat", "Metoclopramide 10 mg orally four times daily; smaller, more frequent meals and increased dietary fat", "Erythromycin 500 mg orally four times daily; larger, less frequent meals and decreased dietary fat", "Erythromycin 500 mg orally four times daily; smaller, more frequent meals and increased dietary fat"], correctIndex: 0,
    rationale: "Either metoclopramide or erythromycin is acceptable pharmacologically — evidence does not favor one — so the discriminator is the lifestyle advice. Correct counseling is smaller, MORE frequent meals with REDUCED dietary fat, since fat delays gastric emptying further. Any option pairing increased fat or larger meals is wrong regardless of the drug named." },

  { id: "pe24-096", domain: "endo", difficulty: 2, tags: ["Gastroparesis", "Continuity of Care"],
    stem: "A 20-year-old man came to the ED with nausea and vomiting and was found to have diabetic gastroparesis. The attending started metoclopramide 5 mg orally three times daily and discharged him. Reviewing discharge prescriptions, what is the most appropriate step to improve his continuity of care and quality of life?",
    options: ["Contact the patient to provide follow-up education about potential metoclopramide adverse effects and answer questions", "Check prescription records to verify he filled the prescription", "Contact the attending and recommend adding erythromycin to metoclopramide", "Contact the attending and recommend erythromycin instead, as the preferred agent for long-term use"], correctIndex: 0,
    rationale: "Metoclopramide carries meaningful risks including tardive dyskinesia, and proactive counseling about what to watch for supports both adherence and quality of life. Adding a second agent is premature when he has not failed the first. Neither drug is preferred for LONG-term use — both should be limited to the shortest effective course. Verifying a fill is a weaker intervention since refills may not even be needed." },

  { id: "pe24-097", domain: "neuro", difficulty: 3, tags: ["Headache", "Diagnosis"],
    stem: "PK is a 54-year-old man presenting with a headache that started 8 hours ago. No medical history or allergies. Vitals: HR 84, BP 134/68, RR 12, temp 98.4°F. He denies neck stiffness. Non-contrast head CT is negative for intracranial processes. Lumbar puncture shows WBC 0 cells/mcL, RBC 3 cells/mcL, protein 15 mg/dL, glucose 86 mg/dL, clear appearance. What is the most likely cause of his visit?",
    options: ["Migraine headache", "Meningitis", "Subarachnoid hemorrhage", "Subdural hematoma"], correctIndex: 0,
    rationale: "This is a diagnosis of exclusion built from negative findings. A completely normal CSF with no pleocytosis and no fever or neck stiffness argues against meningitis. Subarachnoid hemorrhage is unlikely with an RBC count of 3 (well below the ~2000 threshold) and no xanthochromia. Subdural hematoma would have shown on CT. What remains is migraine." },

  { id: "pe24-098", domain: "neuro", difficulty: 2, tags: ["Migraine"],
    stem: "PM is a 32-year-old woman presenting with a migraine that started 3 hours ago. She normally takes sumatriptan but has run out. No other medical history or allergies. Which is most appropriate for initial treatment?",
    options: ["Metoclopramide 10 mg IV", "Haloperidol 2.5 mg IV", "Morphine 4 mg IV", "Acetaminophen 1000 mg IV"], correctIndex: 0,
    rationale: "IV metoclopramide is a first-line parenteral option for acute migraine in the ED per American Headache Society evidence assessment. Haloperidol and acetaminophen are second-line. Opioids such as morphine should be avoided for routine migraine because of poor efficacy, recurrence, and medication-overuse headache risk." },

  { id: "pe24-099", domain: "neuro", difficulty: 3, tags: ["Migraine", "Refractory"],
    stem: "JW is a 54-year-old man in the ED with migraine. He received prochlorperazine 10 mg IV and diphenhydramine 50 mg IV without pain relief. His only history is hypertension treated with amlodipine. Per the 2016 American Headache Society evidence assessment, which therapy is most appropriate now?",
    options: ["Valproic acid 1000 mg IV", "Ketamine 0.3 mg/kg IV", "Propofol 1 mg/kg IV", "0.9% sodium chloride 1000 mL IV over 1 hour"], correctIndex: 0,
    rationale: "AHS states IV valproic acid 500-1000 mg may be offered when first-line therapy fails. The society made 'no recommendation' for ketamine or propofol because evidence was insufficient. A randomized trial specifically found that 1000 mL of saline added no analgesic benefit over 10 mL/hr in migraine patients given prochlorperazine and diphenhydramine." },

  { id: "pe24-100", domain: "neuro", difficulty: 2, tags: ["Migraine", "Pediatrics"],
    stem: "KW is a 13-year-old girl (35 kg) with a history of migraines, brought in by her mother for a migraine. She takes no routine medications. Her mother gave 350 mg of oral ibuprofen about 1 hour ago as previously advised by the pediatrician, but the headache persists at 10/10. Which therapy is most appropriate now?",
    options: ["Rizatriptan 5 mg orally", "Acetaminophen 350 mg orally", "Ibuprofen 400 mg orally", "0.9% sodium chloride 1000 mL IV over 1 hour"], correctIndex: 0,
    rationale: "Pediatric migraine guidelines recommend escalating to a triptan when an NSAID has already failed, and she had an appropriate 10 mg/kg ibuprofen dose an hour ago. Repeating ibuprofen so soon is inappropriate, acetaminophen is not preferred over a triptan at this stage, and IV fluids are not routinely recommended for pediatric headache." },

  { id: "pe24-101", domain: "cv", difficulty: 2, tags: ["Asymptomatic Hypertension", "Discharge Planning"],
    stem: "RP is a 54-year-old man referred from urgent care for a blood pressure of 190/130 mm Hg. He is asymptomatic. He has hypertension prescribed amlodipine 5 mg daily but has not taken it for a month after an insurance change left him without a primary care provider. Per the 2025 ACEP clinical policy on asymptomatic elevated blood pressure, what is most appropriate?",
    options: ["Give amlodipine 5 mg orally once in the ED, counsel on adherence, and provide a medication supply and outpatient referral", "Provide an outpatient referral without administering any antihypertensive in the ED", "Perform a stat head CT to rule out hemorrhagic stroke", "Give labetalol 10 mg IV and admit for blood pressure management"], correctIndex: 0,
    rationale: "The 2025 ACEP policy suggests considering starting (or restarting) outpatient antihypertensive medication for patients discharged with asymptomatic elevated blood pressure, plus referral for follow-up — and this man lost his prescriber and has been off therapy for a month. Referral alone misses that opportunity. Imaging is unwarranted in an asymptomatic patient, and IV therapy plus admission is overtreatment for markedly elevated blood pressure without target-organ damage (the term AHA now uses instead of 'hypertensive urgency')",
    source: "ACEP Clinical Policy: Outpatient Management of Asymptomatic Elevated Blood Pressure (Ann Emerg Med 2025)", updated: "2026-11" },

  { id: "pe24-102", domain: "neuro", difficulty: 2, tags: ["Migraine", "Recurrence Prevention"],
    stem: "JT is a 44-year-old man presenting with migraine. He has a remote migraine history and is on no treatment. Other history includes hypertension, dyslipidemia, and diabetes with an A1C of 11.4% two months ago. He received prochlorperazine and diphenhydramine with relief and is preparing for discharge. Which therapy is most appropriate for him to take if the headache recurs after discharge?",
    options: ["Naproxen", "Dexamethasone", "Prochlorperazine", "Magnesium"], correctIndex: 0,
    rationale: "Naproxen 500 mg is an effective take-home rescue: in a randomized trial of headache that recurred after ED discharge, it worked as well as sumatriptan. Dexamethasone is the one ED therapy shown to REDUCE recurrence (AHS, Level B) and would otherwise be a strong choice, but his A1C of 11.4% makes a glucose-raising steroid a poor choice — the comorbidity is the discriminator. Neither continued prochlorperazine nor oral magnesium has evidence after discharge",
    source: "Friedman BW, et al. Ann Emerg Med 2010 (naproxen vs sumatriptan for post-ED headache); American Headache Society ED evidence assessment (2016)", updated: "2026-11" },

  { id: "pe24-103", domain: "neuro", difficulty: 2, tags: ["Migraine", "Akathisia"],
    stem: "TW is a 30-year-old man who received prochlorperazine 10 mg IV for migraine in the ED. About 30 minutes later he complains of restlessness and 'not feeling right.' Which is most appropriate to give now?",
    options: ["Diphenhydramine 50 mg IV", "Epinephrine 0.3 mg IM", "Droperidol 2.5 mg IV", "Metoclopramide 10 mg IV"], correctIndex: 0,
    rationale: "Restlessness shortly after a dopamine antagonist is akathisia, and diphenhydramine treats it effectively. This is not anaphylaxis, so epinephrine is inappropriate. Both droperidol and metoclopramide are themselves dopamine antagonists and would worsen the very symptom being treated — recognizing that shared mechanism is the point of the question." },

  { id: "pe24-104", domain: "tox", difficulty: 3, tags: ["Opioid Reversal", "Naloxone"],
    stem: "A 56-year-old woman presents with increased back pain from a recently expanded spinal tumor. She receives hydromorphone 4 mg IV. Shortly after, the nurse finds her very somnolent with a respiratory rate of 9, and a container of 30-mg immediate-release oxycodone tablets prescribed to her on her lap. What is the most appropriate way to administer naloxone?",
    options: ["Give 0.04 mg IV, titrating subsequent doses to effect", "Give 4 mg intranasally, repeating as needed to effect", "Give 2 mg IV, titrating subsequent doses to effect", "Give 2 mg/hr by continuous IV infusion titrated to effect"], correctIndex: 0,
    rationale: "She is opioid-tolerant on chronic therapy for cancer pain, so the goal is restoring respiratory drive WITHOUT fully reversing analgesia or precipitating withdrawal — hence starting at 0.04 mg and titrating. A 2-mg IV dose would almost certainly cause complete reversal. Intranasal dosing suits the prehospital setting, not a monitored patient with IV access. An infusion may follow, but only once the effective wake-up dose is known." },

  { id: "pe24-105", domain: "psych", difficulty: 3, tags: ["Agitation", "Geriatrics", "Parkinson Disease"],
    stem: "A 77-year-old man with Parkinson's disease, prostate cancer, and atrial fibrillation on warfarin presents after a fall from standing with head strike and loss of consciousness. He regained consciousness and is agitated and hypertensive but denies pain. The team wants a prompt head CT for suspected intracranial hemorrhage. Which initial IV therapy is most appropriate to calm him for imaging?",
    options: ["Lorazepam 1 mg", "Dexmedetomidine 0.2 mcg/kg/hr", "Haloperidol 2.5 mg", "Olanzapine 5 mg"], correctIndex: 0,
    rationale: "Expert consensus for the agitated older adult needing urgent imaging favors a low dose of a short-acting benzodiazepine. Haloperidol is specifically contraindicated by his PARKINSON'S DISEASE, since dopamine blockade worsens the movement disorder. Dexmedetomidine needs slow titration and risks bradycardia and hypotension, and olanzapine has slower onset and weaker sedation than lorazepam here." },

  { id: "pe24-106", domain: "psych", difficulty: 3, tags: ["Agitation", "Stimulants"],
    stem: "A 34-year-old woman is brought in by EMS after her roommate reported visual hallucinations and erratic behavior; the roommate reports a history of amphetamine use. She received midazolam 10 mg IM en route 8 minutes ago. In the ED she has disorganized, rapidly cycling speech and will not allow assessment. Which IM medication is most appropriate to facilitate care?",
    options: ["Haloperidol 5 mg", "Lorazepam 5 mg", "Midazolam 5 mg", "Olanzapine 10 mg"], correctIndex: 0,
    rationale: "Adding an ANTIPSYCHOTIC to the benzodiazepine already given is the recommended approach for drug-induced psychosis, and haloperidol has evidence in amphetamine-type stimulant psychosis. The timing detail matters: midazolam given 8 minutes ago has not peaked, so more midazolam or lorazepam risks dose stacking, oversedation, and cardiorespiratory depression. Olanzapine combined with a recent parenteral benzodiazepine carries added sedation and hypotension risk." },

  { id: "pe24-107", domain: "psych", difficulty: 3, tags: ["Opioid Use Disorder", "Buprenorphine"],
    stem: "A 28-year-old man presented after a fentanyl overdose reversed with intranasal naloxone by police. He has been monitored 4 hours with no signs of overdose or withdrawal and wants to leave, but is interested in starting buprenorphine/naloxone with addiction clinic follow-up. Your ED provides 8 mg/2 mg 'to-go' kits of six sublingual films. What instruction about timing of initiation should you give?",
    options: ["Initiate it when in mild-to-moderate withdrawal", "Initiate it as soon as possible at discharge to avoid withdrawal", "Initiate it when in moderate-to-severe withdrawal", "Initiate it when in mild withdrawal in combination with fentanyl"], correctIndex: 0,
    rationale: "Buprenorphine is a partial agonist with high receptor affinity, so giving it before withdrawal has begun displaces full agonists and PRECIPITATES withdrawal — which can drive relapse and lasting aversion to treatment. Waiting for mild-to-moderate withdrawal avoids that while still relieving symptoms; waiting for moderate-to-severe is needless suffering. Co-administration with fentanyl describes the Bernese micro-dosing method, which is not feasible with 8 mg/2 mg films." },

  { id: "pe24-108", domain: "id", difficulty: 2, tags: ["Skin and Soft Tissue Infection", "Cellulitis"],
    stem: "A 19-year-old woman with no significant history or allergies presents with pain and redness of her left lateral lower leg after sliding on the floor playing indoor basketball. What she thought was a floor burn has become progressively red and painful. She has no systemic signs of infection. Exam shows a 4 x 5 inch area of erythema with superficial abrasions and no exudate. Per IDSA guidelines, which antibiotic regimen is most appropriate?",
    options: ["Cephalexin 500 mg orally every 6 hours", "Clindamycin 300 mg orally every 8 hours", "Cephalexin 500 mg orally every 6 hours plus trimethoprim/sulfamethoxazole 800/160 mg twice daily", "Cefazolin 1 g IV every 8 hours"], correctIndex: 0,
    rationale: "This is mild, NON-PURULENT cellulitis, where beta-hemolytic streptococci predominate and cephalexin alone is recommended. IDSA advises against adding TMP-SMX absent suspicion of MRSA — purulence is what would raise that suspicion, and there is none. Clindamycin is reserved for true penicillin allergy given its adverse effect profile, and IV cefazolin implies admission this mild infection does not warrant." },

  { id: "pe24-109", domain: "psych", difficulty: 3, tags: ["Alcohol Withdrawal", "Phenobarbital"],
    stem: "A 66-year-old man presents in alcohol withdrawal after trying to detoxify at home. He drinks 10-12 beers daily; last drink about 18 hours ago. He is diaphoretic and tremulous with HR 112 and BP 176/88. CIWA-Ar is 24. He receives diazepam 40 mg IV within the first half hour and his CIWA-Ar remains above 20 with no CNS or respiratory depression. The team worries he is becoming more altered and may seize. What do you recommend?",
    options: ["Give phenobarbital 10 mg/kg IV", "Give diazepam 40 mg IV", "Give phenobarbital 130 mg IV", "Intubate to facilitate starting propofol"], correctIndex: 0,
    rationale: "This is benzodiazepine-refractory severe withdrawal, where phenobarbital is favored because it acts on BOTH pathways involved — enhancing GABA and inhibiting glutamate — rather than GABA alone. The appropriate load is 10 mg/kg; 130 mg is far too small (a reasonable smaller starting bolus would be about 260 mg). He is still protecting his airway, so phenobarbital should be tried before intubation." },

  { id: "pe24-110", domain: "pain", difficulty: 2, tags: ["Buprenorphine", "Analgesia"],
    stem: "What is the most appropriate dosing interval for sublingual buprenorphine when used for PAIN management?",
    options: ["Every 6 hours", "Every 4 hours", "Every 12 hours", "Every 24 hours"], correctIndex: 0,
    rationale: "Buprenorphine's ANALGESIC effect lasts only 6-8 hours even though its opioid use disorder dosing is once daily — that divergence is exactly what this question tests. So the total daily dose is divided every 6 hours for pain (sublingually; oral bioavailability is poor). Twelve- or 24-hour intervals leave breakthrough pain, while every 4 hours risks accumulation and toxicity",
    source: "Buprenorphine sublingual prescribing information (given sublingually; swallowing sharply reduces bioavailability)", updated: "2026-11" },

  { id: "pe24-111", domain: "id", difficulty: 3, tags: ["Necrotizing Infection", "Antibiotics"],
    stem: "A 38-year-old woman presents with significant left arm pain near a recent surgical debridement for a third-degree burn. The area is markedly red with purulence and taut skin. The team starts empiric vancomycin and piperacillin/tazobactam and obtains a CT for possible compartment syndrome. CT shows soft-tissue thickening and GAS along the fascial planes. Would you change the empiric regimen?",
    options: ["Yes, add clindamycin to improve coverage for gas-forming bacteria", "No, vancomycin and piperacillin/tazobactam cover all organisms of concern", "Yes, change vancomycin to daptomycin to improve coverage for gas-forming bacteria", "Yes, change piperacillin/tazobactam to meropenem because of concern for ESBL-producing organisms"], correctIndex: 0,
    rationale: "Gas along fascial planes indicates a necrotizing soft tissue infection with gas-forming organisms such as Clostridium species, and clindamycin is added both for that coverage and for its antitoxin effect via protein synthesis inhibition. Daptomycin offers no advantage over vancomycin against clostridia — and is inactivated by surfactant, making it a poor general substitute. Nothing here suggests ESBL organisms." },

  { id: "pe24-112", domain: "tox", difficulty: 2, tags: ["Opioid Overdose", "Naloxone", "ACLS"],
    stem: "Police find a middle-aged man face down on the sidewalk, unresponsive, without a carotid pulse, with pinpoint pupils. They begin CPR, apply an AED, call 911, and give 2 mg intranasal naloxone. There is no response after 4 minutes. What should they do next?",
    options: ["Give a second 2-mg intranasal naloxone dose while continuing CPR", "Give 0.2 mg of intravenous flumazenil", "Give 2 mg of intravenous epinephrine", "Pause CPR until the naloxone takes effect"], correctIndex: 0,
    rationale: "Naloxone can be repeated when there is no response (intranasal products are labeled for repeat doses every 2–3 minutes), but in a pulseless patient CPR and the AED come first — naloxone is an adjunct that never replaces or pauses compressions. Flumazenil reverses benzodiazepines, has no role in arrest, and is hazardous in mixed overdose. Epinephrine belongs to advanced care at 1 mg IV every 3–5 minutes, so a 2-mg dose is wrong, and police cannot give IV drugs",
    source: "2023 AHA Focused Update on Cardiac Arrest or Life-Threatening Toxicity Due to Poisoning (opioids); naloxone nasal spray prescribing information", updated: "2026-11" },

  { id: "pe24-113", domain: "pain", difficulty: 3, tags: ["Hyperalgesia", "Ketamine", "Opioid Use Disorder"],
    stem: "A 49-year-old woman with opioid use disorder on maintenance methadone presents after a car accident with a broken radius. The team has given fentanyl 25-50 mcg IV every 30-60 minutes for 3 hours. Orthopedics splinted the arm with initial pain reduction, but she now reports increased pain despite higher fentanyl doses. What strategy do you recommend?",
    options: ["Switch fentanyl to ketamine", "Switch fentanyl to hydromorphone", "Switch methadone to buprenorphine", "Increase the fentanyl dosage"], correctIndex: 0,
    rationale: "Escalating opioid doses producing WORSENING pain suggests opioid-induced hyperalgesia, where ketamine (an NMDA antagonist) has demonstrated benefit. Rotating to another full agonist does not address the underlying NMDA-mediated mechanism, and pushing the fentanyl dose higher would aggravate it. Switching her maintenance methadone to buprenorphine addresses neither the acute fracture pain nor the hyperalgesia." },

  { id: "pe24-114", domain: "tox", difficulty: 2, tags: ["Toxidromes"],
    stem: "AA is a 76-year-old man presenting with agitation and flushing. Vitals: BP 139/75, HR 121, RR 21, temp 101.4°F (38.6°C). He has obvious skin flushing WITHOUT perspiration and reports nausea. His partner states he has had a cold and taken multiple over-the-counter medications. Which toxidrome is he most likely exhibiting?",
    options: ["Anticholinergic", "Opioid", "Cholinergic", "Sympathomimetic"], correctIndex: 0,
    rationale: "Agitation, flushing, tachycardia, hyperthermia, and DRY skin is the anticholinergic picture — common with over-the-counter cold preparations containing antihistamines. The absence of sweating is the pivotal finding: sympathomimetic toxicity looks similar but produces diaphoresis. Opioid toxicity causes bradycardia and respiratory depression, and cholinergic toxicity causes bradycardia with salivation and diarrhea." },

  { id: "pe24-115", domain: "tox", difficulty: 2, tags: ["Toxidromes", "Antidotes"],
    stem: "BH is a 25-year-old woman found unconscious at a gas station. EMS vitals: BP 103/54, HR 41, RR 7, temp 98.5°F. She has shallow breathing and only groans to sternal rub. Exam shows pinpoint pupils and hypoactive bowel sounds. EMS reports she has a known seizure history. Which antidote is most appropriate?",
    options: ["Naloxone", "Flumazenil", "Physostigmine", "Cyproheptadine"], correctIndex: 0,
    rationale: "Bradycardia, pinpoint pupils, and respiratory depression are the hallmarks of opioid toxicity, treated with naloxone. Flumazenil is doubly wrong: the picture fits opioids better than benzodiazepines, and her seizure history makes flumazenil dangerous because it can precipitate refractory seizures. Physostigmine treats anticholinergic toxicity and cyproheptadine treats serotonin toxicity — neither presentation is present." },

  { id: "pe24-116", domain: "psych", difficulty: 2, tags: ["Agitation", "Ketamine"],
    stem: "A 44-year-old man presents with disorientation and aggressive behavior, RASS +4. Reducing noise, light, and physical stimulation has not helped. Vitals: BP 128/75, HR 78, RR 15, temp 99.1°F. Staff cannot obtain an ECG or IV access. Which medication should be given IM for prompt sedation?",
    options: ["Ketamine", "Lorazepam", "Haloperidol", "Ziprasidone"], correctIndex: 0,
    rationale: "Speed is the deciding factor when a patient is too agitated to allow assessment: IM ketamine sedates in roughly 2 minutes, versus 20-60 minutes for haloperidol, 20-30 for ziprasidone, and 30-60 for lorazepam. He has no contraindication to ketamine. Note also that no ECG is available, which further disfavors QT-prolonging antipsychotics." },

  { id: "pe24-117", domain: "tox", difficulty: 3, tags: ["Toxic Alcohols", "Fomepizole"],
    stem: "A 38-year-old man presents with disorientation after ingesting windshield wiper fluid in a self-harm attempt. Vitals: BP 138/85, HR 88, RR 18, temp 98.1°F. Labs: sodium 149, potassium 3.5, chloride 103, bicarbonate 5 mEq/L, BUN 15, creatinine 1.4, glucose 99. Fomepizole will be started for suspected toxic alcohol poisoning. Which IV loading and maintenance regimen is most appropriate?",
    options: ["15 mg/kg IV bolus, then 10 mg/kg every 12 hours x 4 doses, then 15 mg/kg every 12 hours", "15 mg/kg IV bolus, then 15 mg/kg every 12 hours x 4 doses, then 10 mg/kg every 12 hours", "10 mg/kg IV bolus, then 15 mg/kg every 12 hours x 4 doses, then 10 mg/kg every 12 hours", "10 mg/kg IV bolus, then 10 mg/kg every 12 hours x 4 doses, then 15 mg/kg every 12 hours"], correctIndex: 0,
    rationale: "Fomepizole loads at 15 mg/kg, drops to 10 mg/kg every 12 hours for four doses (48 hours), then INCREASES back to 15 mg/kg every 12 hours. The escalation is the memorable part and the reason is pharmacokinetic: fomepizole induces its own metabolism over about 48 hours, so the maintenance dose must rise to keep concentrations therapeutic." },

  { id: "pe24-118", domain: "tox", difficulty: 3, tags: ["Salicylate Toxicity"],
    stem: "A 71-year-old woman presented after waking with left-sided weakness; she has prior ischemic stroke with an associated seizure disorder and denies recent seizures. In the ED she became acutely confused with tinnitus, shortness of breath, and blurred vision. MRI is negative for acute stroke. She reports excessive use of a salicylate for the past 2-3 weeks. A serum salicylate level is pending. Which management strategy is most appropriate now?",
    options: ["Sodium bicarbonate by IV infusion", "Wait for the serum salicylate level before initiating treatment", "Sodium chloride with potassium chloride by IV infusion", "Calcium chloride by IV push"], correctIndex: 0,
    rationale: "Tinnitus, tachypnea, and confusion are enough to treat empirically — serum salicylate levels correlate poorly with toxicity, especially in chronic ingestion, so waiting on the level delays care. Sodium bicarbonate for urinary alkalinization comes first; potassium repletion follows because alkalinization fails without it. Her new confusion also meets EXTRIP criteria for hemodialysis (altered mental status), so arrange it now rather than waiting for the level. Calcium is given only if hypocalcemia develops as a consequence of alkalinization",
    source: "Juurlink DN, et al. EXTRIP recommendations for salicylate poisoning. Ann Emerg Med 2015", updated: "2026-11" },

  { id: "pe24-119", domain: "tox", difficulty: 3, tags: ["Acetaminophen", "Acetylcysteine"],
    stem: "AG is a 49-year-old man admitted for suspected chronic acetaminophen toxicity, reporting about ninety-six 650-mg tablets over 7 days for intractable back pain. Vitals are unremarkable. Labs: BUN 51 mg/dL, creatinine 2.2 mg/dL, ALT 2046 units/L, AST 1058 units/L. Which treatment is most appropriate now?",
    options: ["Acetylcysteine", "Activated charcoal", "Sodium chloride infusion", "Hemodialysis"], correctIndex: 0,
    rationale: "Chronic ingestion above 4 g/day with elevated transaminases is an indication for acetylcysteine — his intake averages roughly 8.9 g/day and his ALT is over 2000. Activated charcoal only helps within 1-2 hours of an ACUTE ingestion. He is not hypotensive, so crystalloid is not the priority. Hemodialysis is reserved for massive ingestion complicated by coma or hypotension." },

  { id: "pe24-120", domain: "tox", difficulty: 3, tags: ["Acetaminophen", "High-Risk Ingestion"],
    stem: "A 35-year-old man was admitted for suspected acetaminophen overdose, having taken fifty 500-mg tablets (25 g) about 5 hours ago. His acetaminophen concentration 5 hours after ingestion was 200 mcg/mL and the standard IV acetylcysteine regimen was started. The resident asks whether the size of the ingestion calls for a higher acetylcysteine dose. What do you recommend?",
    options: ["Continue standard dosing; this is not a high-risk ingestion by dose or by level", "Increase the rate of infusion of the first bag", "Increase the rate of infusion of the second bag", "Add fomepizole and plan hemodialysis"], correctIndex: 0,
    rationale: "The 2023 US/Canada consensus defines a HIGH-RISK ingestion as at least 30 g, or a concentration above the high-risk line (starting at 300 mcg/mL at 4 hours, about 250 mcg/mL at 5 hours). At 25 g with a level of 200 mcg/mL he meets neither, so the standard regimen is appropriate: at least 300 mg/kg over the first 20–24 hours, continued until stopping criteria are met. For a true high-risk ingestion, a larger acetylcysteine dose may be warranted with poison center input (no single dose is standardized), and activated charcoal may be warranted even beyond 4 hours. Hemodialysis (alongside acetylcysteine) is reserved for levels of 900 mcg/mL or more with acidosis or altered consciousness, and the panel found the data too thin to recommend fomepizole as standard treatment",
    source: "Dart RC, et al. Management of Acetaminophen Poisoning in the US and Canada: A Consensus Statement. JAMA Netw Open 2023", updated: "2026-11" },

  { id: "pe24-121", domain: "safety", difficulty: 2, tags: ["Antidote Stocking", "Emergency Preparedness"],
    stem: "Per ACEP expert consensus guidelines for stocking antidotes in hospitals that provide emergency care, which antidote should be IMMEDIATELY available?",
    options: ["Dantrolene", "Acetylcysteine", "Cyproheptadine", "Dimercaprol"], correctIndex: 0,
    rationale: "The guidelines tier antidotes by required availability. Dantrolene must be immediately available, and stocked wherever anesthesia is provided, because malignant hyperthermia kills within minutes. Acetylcysteine and dimercaprol need only be obtainable within 60 minutes, and cyproheptadine simply needs to be stocked somewhere in the institution." },

  { id: "pe24-122", domain: "safety", difficulty: 2, tags: ["Antidote Stocking", "Emergency Preparedness"],
    stem: "What adult weight in kilograms is used as the basis for calculating antidote stocking quantities in the ACEP expert consensus guidelines for stocking antidotes in hospitals that provide emergency care?",
    options: ["100", "70", "80", "90"], correctIndex: 0,
    rationale: "The guidelines use 100 kg, which per NHANES data corresponds to about the 75th percentile for men and the 90th-95th percentile for women — deliberately generous so that stock suffices for most adults. The familiar textbook 70 kg would only cover roughly the 15th percentile of men, leaving most patients under-supplied." },

  { id: "pe24-123", domain: "safety", difficulty: 2, tags: ["Policy Development", "Antidotes"],
    stem: "The director of pharmacy asks the ED pharmacist team to formulate a policy and procedure for stocking and storage of all antidotes, reversal agents, and rescue agents at the institution. Which assessment tool is most appropriate for developing this policy?",
    options: ["Hazard vulnerability assessment", "ISMP Medication Safety Self-Assessment for High-Alert Medications", "The Joint Commission Guide to Risk Assessment", "AHRQ Emergency Severity Index"], correctIndex: 0,
    rationale: "A hazard vulnerability assessment systematically identifies the hazards a facility might face and whether it can meet the resulting demand, and it specifically addresses stocking and storage of antidotes and rescue agents. The ISMP self-assessment covers high-alert medications broadly but not antidote stocking. The Joint Commission guide describes generic risk assessment methodology. The ESI is a triage acuity algorithm with no bearing on stocking." },

  { id: "pe24-124", domain: "tox", difficulty: 3, tags: ["Unknown Ingestion", "Pediatrics", "Sympathomimetic"],
    stem: "An 11-year-old boy with attention deficit disorder on guanfacine arrives at 13:00 after poison control referral. He told the school nurse he took a handful of his mother's medications between 05:00 and 06:00 because he 'didn't want to go to school'; the identity of her medications is unknown, but he says 'she takes stuff for her bad moods.' Exam: mydriasis, slight diaphoresis, present bowel sounds, mild tremor without clonus or hyperreflexia, anxious, complains of stomachache. Vitals: HR 117, BP 157/70, RR 22, temp 98.9°F, SpO2 99%. ECG: PR 135 ms, QRS 90 ms, QTc 450 ms. Which therapy is most appropriate now?",
    options: ["A benzodiazepine for anxiety and to reduce sympathetic outflow", "A beta-blocker to normalize the heart rate", "Whole bowel irrigation to minimize further absorption", "Physostigmine for anticholinergic tachycardia and anxiety"], correctIndex: 0,
    rationale: "Tachycardia, hypertension, tremor, DIAPHORESIS, and anxiety describe a sympathomimetic/serotonergic picture, most consistent with an SNRI or bupropion — and benzodiazepines are the primary treatment for both. Diaphoresis with present bowel sounds argues against an anticholinergic toxidrome, so physostigmine could be harmful, particularly if a proconvulsant was taken. Beta-blockade risks unopposed alpha stimulation and can mask impending seizure. Whole bowel irrigation is too aggressive for an unidentified ingestion 7-8 hours old." },

  { id: "pe24-125", domain: "tox", difficulty: 3, tags: ["Bupropion", "Pediatrics"],
    stem: "The 11-year-old boy who ingested an unidentified maternal medication 7-8 hours ago received lorazepam 2 mg IV 30 minutes ago and is becoming progressively more tachycardic and agitated. Metabolic panel and CBC are unremarkable; urine drug screen is positive for amphetamine; acetaminophen and salicylate undetectable. Vitals: HR 132, BP 145/80, RR 26. Repeat ECG: PR 135 ms, QRS 75 ms, QTc 432 ms. Poison control reports the mother takes bupropion XL 300 mg daily and amlodipine 5 mg daily. What is most appropriate now?",
    options: ["Administer additional benzodiazepine therapy for agitation and persistent tachycardia", "No therapy is needed, because symptoms should resolve given the time since ingestion", "Begin serum alkalinization with IV sodium bicarbonate", "Administer intravenous lipid emulsion to prevent decompensation"], correctIndex: 0,
    rationale: "Bupropion explains everything here — including the positive amphetamine screen, since bupropion is structurally related and cross-reacts. Its hallmark toxicity is SEIZURES, and with extended-release products onset is delayed (mean about 7.9 hours, up to 24), so observation alone is unsafe at 7-8 hours. More benzodiazepine is indicated because the first dose was inadequate. Alkalinization targets a wide QRS, and his is 75 ms. Lipid emulsion is reserved for severe conduction delay or peri-arrest." },

  { id: "pe24-126", domain: "tox", difficulty: 3, tags: ["TCA Overdose", "Pediatrics", "Sodium Bicarbonate"],
    stem: "A 3-year-old girl presents with somnolence. She was at her grandmother's home; the grandmother found her playing with a tablet of medicine and took it away. Somnolence increased a few hours later, with fewer wet diapers. The grandmother has diabetes, peripheral neuropathy, and anemia. Exam: minimally interactive, slight mydriasis with sluggish light reaction, dry white tongue, no clonus, hyperreflexia, or diaphoresis. Vitals: HR 167, BP 75/60, RR 22, temp 100°F. ECG: PR 135 ms, QRS 123 ms, QTc 450 ms, 3-mm R wave in aVR. Glucose 82 mg/dL. IV fluids are started. Which intervention is most appropriate?",
    options: ["Sodium bicarbonate", "Activated charcoal", "Naloxone", "Dopamine"], correctIndex: 0,
    rationale: "Anticholinergic features (dry mouth, mydriasis, reduced urination, tachycardia), hypotension from alpha blockade, and sodium channel blockade (QRS 123 ms with a tall R wave in aVR) point to a tricyclic antidepressant — plausible given the grandmother's neuropathy. Hypertonic sodium bicarbonate overcomes the sodium channel blockade and alkalinizes the serum. Charcoal is unsafe in a somnolent child hours post-ingestion. Pupils are dilated with tachycardia, so this is not opioid toxicity. If a pressor is needed, TCA-induced shock responds better to norepinephrine than dopamine, whose effect depends on norepinephrine release that TCAs blunt." },

  { id: "pe24-127", domain: "tox", difficulty: 3, tags: ["NMS", "Serotonin Syndrome", "Pediatrics"],
    stem: "A 7-year-old girl with Freeman-Sheldon syndrome, OCD, and generalized anxiety presents with 3 days of regurgitation and vomiting and worsening fever. Three days ago she started empiric antibiotics plus metoclopramide and ondansetron. Home medications include fluvoxamine 50 mg daily. Exam: extreme irritability, generalized RIGIDITY, slow movements, normal reflexes, NO ankle clonus. Vitals: HR 171, BP 95/60, RR 32, temp 105°F. Which assessment is most consistent with her presentation?",
    options: ["Neuroleptic malignant syndrome; give a benzodiazepine for agitation and active external cooling for hyperthermia, monitoring electrolytes and creatine kinase", "Serotonin syndrome; give a benzodiazepine for agitation and cyproheptadine for hyperthermia, monitoring electrolytes and creatine kinase", "Neuroleptic malignant syndrome; give bromocriptine for agitation, a dopamine infusion for motor insufficiency, and dantrolene for hyperthermia", "Serotonin syndrome; give a benzodiazepine for agitation and active external cooling for hyperthermia, monitoring electrolytes and creatine kinase"], correctIndex: 0,
    rationale: "Both syndromes are plausible given fluvoxamine plus metoclopramide, but the MOTOR exam distinguishes them: rigidity and bradykinesia with ABSENT clonus and normal reflexes indicate NMS, whereas serotonin syndrome produces clonus and hyperreflexia. Onset over days after starting a dopamine blocker also fits NMS. Treatment is supportive: benzodiazepines first line and active external cooling for temperature — antipyretics do not work, because the heat comes from muscle activity rather than a reset hypothalamic set point. Bromocriptine and dantrolene are adjuncts, and a dopamine infusion for 'peripheral dopamine blockade' is not a real intervention",
    source: "Boyer EW, Shannon M. The serotonin syndrome. NEJM 2005; NMS international expert consensus criteria (2011)", updated: "2026-11" },

  { id: "pe24-128", domain: "env", difficulty: 3, tags: ["Envenomation", "Antivenom", "Regulatory"],
    stem: "A regional zoo housing gaboon vipers and deathstalker scorpions asks your hospital to be its designated treatment facility. No FDA-approved antivenom exists in the US for these species, though non-US products are available. You are consulted on a guideline for safely administering these non-FDA-approved antivenoms. Which statement is INCORRECT?",
    options: ["The antivenom products should be stored only at the healthcare facility to ensure appropriate storage conditions", "A Biologic Based Investigational New Drug application should be completed, submitted to the FDA, and maintained by the facility storing the antivenom", "Contacting a regional poison control center should be part of the treatment process", "An emergency IRB approval process should be established in advance at the institution administering the antivenom"], correctIndex: 0,
    rationale: "ACMT guidelines permit storage at EITHER the designated healthcare facility or the facility housing the animals, provided manufacturer and pharmacy storage conditions are met — so restricting storage to the hospital is the false statement. The others are all correct: non-approved antivenom is an experimental drug requiring a BB-IND (form 1572), poison centers source products through the antivenom index and provide toxicologist consultation, and because envenomation cannot wait, an emergency IRB pathway must exist beforehand." },

  { id: "pe24-129", domain: "tox", difficulty: 3, tags: ["Calcium Channel Blocker", "Pediatrics", "Shock"],
    stem: "HL is a 9-year-old girl brought in with bradycardia and lethargy after a fight with her foster parents the previous night. Paramedics found her slurring words, minimally responsive, bradycardic and hypotensive; atropine had no effect. Medications at home include the mother's amlodipine, lisinopril, aspirin, atorvastatin, citalopram and the father's propranolol, bupropion, gabapentin. Vitals: HR 34, BP 82/40. ECG: PR 260 ms, QRS 95 ms. Glucose 342 mg/dL. Bedside ultrasound shows poor ventricular squeeze; chest X-ray shows mild pulmonary vascular engorgement. What is most appropriate now?",
    options: ["IV norepinephrine, IV dobutamine, and high-dose insulin euglycemia", "IV epinephrine, IV dobutamine, and IV glucagon", "IV fluids, IV calcium gluconate, and oral activated charcoal", "IV epinephrine, IV dobutamine, and a single dose of intravenous lipid emulsion"], correctIndex: 0,
    rationale: "HYPERGLYCEMIA of 342 mg/dL is the clue pointing to calcium channel blocker rather than beta-blocker overdose, since blockade of pancreatic calcium channels inhibits insulin release. With cardiogenic shock and poor squeeze, treatment is a vasopressor plus inotrope plus high-dose insulin euglycemia. Aggressive fluids risk worsening the pulmonary congestion already present, and charcoal is unsafe with a compromised airway. Glucagon is not routinely recommended in CCB overdose, and lipid emulsion is reserved for refractory or peri-arrest patients." },

  { id: "pe24-130", domain: "tox", difficulty: 3, tags: ["Calcium Channel Blocker", "Beta-blocker", "Refractory Shock"],
    stem: "HL, the 9-year-old with apparent calcium channel blocker overdose, is intubated on norepinephrine and high-dose insulin euglycemia, plus dobutamine, epinephrine, vasopressin, and calcium gluconate. Her father reports tablets missing from BOTH his amlodipine and the mother's propranolol. After 6 hours her MAP has declined and she had two brief self-resolving runs of ventricular tachycardia. ECG now: HR 49, PR 140 ms, QRS 130 ms (was PR 260 ms, QRS 95 ms). Lactate 6.3, arterial pH 7.2, ejection fraction 34%. In addition to increasing the insulin to 5 units/kg/hr, what is most appropriate?",
    options: ["Initiate glucagon, administer 50 mEq sodium bicarbonate, and consider lipid emulsion 1.5 mL/kg if refractory", "Initiate dopamine and administer 50 mEq sodium bicarbonate", "Initiate dopamine", "Initiate glucagon"], correctIndex: 0,
    rationale: "Two new facts change management: propranolol is now implicated, and the QRS has widened from 95 to 130 ms, indicating sodium channel blockade that calls for a sodium bicarbonate bolus. Glucagon, second line in beta-blocker overdose, is warranted now that she is vasopressor-refractory. Lipid emulsion is the reasonable next consideration in deterioration despite maximal therapy. Dopamine is the wrong addition — guidelines advise against it as a pressor here, and it could worsen the ventricular ectopy she is already showing." },

  { id: "pe24-131", domain: "env", difficulty: 3, tags: ["Envenomation", "Antivenom", "Pediatrics"],
    stem: "A 4-year-old boy is brought in with arm pain and swelling after camping in the southeastern United States about 4 hours ago; a small amount of blood was noted on the skin. Exam: two small puncture wounds on the right arm with soft tissue edema, bruising, erythema, and muscle fasciculation. Vitals: BP 87/42, HR 121, RR 22. Platelets 87,000/L. The demarcation line has advanced 4.3 cm in 30 minutes and he is breathing more rapidly. What is the most appropriate course of action?",
    options: ["Give crotalinae antivenom (Anavip or CroFab) after poison control consultation, starting the infusion slowly and increasing as tolerated over 1 hour", "Give North American Coral Snake antivenom, injecting the first 1-2 mL over 3-5 minutes watching for hypersensitivity", "Give Centruroides scorpion-specific F(ab')2 antivenom every 30-60 minutes until pain is controlled, with platelets for thrombocytopenia", "Give calcium, benzodiazepines, and opioids, then Latrodectus antivenom at a reduced pediatric dose with platelets for thrombocytopenia"], correctIndex: 0,
    rationale: "Puncture wounds with rapidly progressive local tissue destruction plus thrombocytopenia is the crotaline (pit viper) pattern, and the rapid progression with respiratory change justifies antivenom. Coral snake envenomation instead causes delayed NEUROTOXICITY without prominent local injury. Centruroides scorpions live in the southwest and cause pain and cranial nerve findings, not coagulopathy. Latrodectus causes pain and autonomic symptoms; note also that antivenom doses treat the VENOM, so pediatric dose reduction is never appropriate." },

  { id: "pe24-132", domain: "tox", difficulty: 3, tags: ["Clonidine", "Pediatrics", "Naloxone"],
    stem: "A 2-year-old girl (15 kg) is brought in for lethargy. The babysitter found her accessing her older brother's ADHD medications about 5 hours ago; the containers were not brought and the medications are unknown. Exam: unconscious, MIOSIS, bradypnea, minimal response to tactile stimuli. Vitals: HR 32, BP 145/70, RR 6, SpO2 92% on room air. What is the most appropriate course of action?",
    options: ["Administer high-dose naloxone (10 mg IV)", "Administer 0.3 mg of atropine", "Administer 2 mg of physostigmine", "Place an endotracheal tube for hypoventilation"], correctIndex: 0,
    rationale: "Bradycardia, bradypnea, and miosis after an ADHD medication point to an alpha-2 agonist such as clonidine or guanfacine; the early HYPERTENSION fits peripheral alpha stimulation. Naloxone can reverse the CNS and respiratory depression and often averts intubation, but standard doses frequently fail. In a poison-center series, 13 of 20 somnolent, bradycardic children given a 10-mg IV bolus woke up, and no adverse events followed any naloxone dose; other poison centers start at 0.1 mg/kg (up to 2 mg a dose) and escalate to a 10-mg total. Bradycardia from alpha-2 agonists is usually tolerated while perfusion is adequate, so atropine is reserved for bradycardia with poor perfusion. Physostigmine would worsen bradycardia and miosis. She is still breathing, so intubating before attempting reversal is premature",
    source: "Seger DL, Loden JK. Naloxone reversal of clonidine toxicity: dose, dose, dose. Clin Toxicol 2018", updated: "2026-11" },

  { id: "pe24-133", domain: "env", difficulty: 3, tags: ["Frostbite", "Drug Shortage"],
    stem: "You work at a certified stroke center during a critical alteplase shortage. A 16-year-old was lost on a nighttime hike without gloves and rescued 72 hours later with severe digital frostbite. After bilateral hand rewarming at 38°C, the physician notes numerous lesions on the proximal phalanges (grade 3 frostbite) and asks whether alteplase should be started. What is the most appropriate response?",
    options: ["Recommend wound care, tetanus prophylaxis, and surgical consultation", "Await bone scan results and try to obtain tenecteplase for intra-arterial use, reserving alteplase for stroke", "Await bone scan results and give alteplase if perfusion loss proximal to the distal phalanx is demonstrated", "Start alteplase now, because proximal phalanx lesions carry a high amputation rate and awaiting the scan is inappropriate"], correctIndex: 0,
    rationale: "Thrombolysis can salvage digits in deep (Cauchy grade 3-4) frostbite with an imaging-confirmed perfusion deficit, but the benefit is time-critical: WMS 2024 places tPA within 24 hours, and in early series patients frozen for more than 24 hours, or with freeze-thaw cycles, did not respond, so screening tools require cold exposure under 24 hours. After 72 hours outdoors he is very unlikely to benefit, so wound care and surgical follow-up are appropriate, and the scarce alteplase stays available for patients who can benefit. Iloprost (FDA-approved for severe frostbite in 2024) is a non-thrombolytic option to discuss with a burn center",
    source: "Wilderness Medical Society Clinical Practice Guidelines for Frostbite: 2024 Update; Twomey JA, et al. J Trauma 2005; Handford C, et al. Extreme Physiol Med 2014", updated: "2026-11" },

  { id: "pe24-134", domain: "tox", difficulty: 3, tags: ["Serotonin Syndrome", "NMS"],
    stem: "Which statement about serotonin syndrome or neuroleptic malignant syndrome is correct?",
    options: ["A well-validated scoring tool is available for the diagnosis of serotonin syndrome", "The role of serotonin antagonists in treating serotonin syndrome is well established with clear dosing recommendations", "Dantrolene should be prioritized over other therapies in NMS to immediately reduce severity and duration", "Severe manifestations of both syndromes include refractory hypothermia, vasoplegia, and seizure"], correctIndex: 0,
    rationale: "The Hunter Serotonin Toxicity Criteria were validated against toxicologist bedside diagnoses and outperform the older Sternbach criteria. By contrast, cyproheptadine's efficacy rests largely on case reports with no consensus on agent or dose. Dantrolene acts peripherally on ryanodine receptors, while NMS hyperthermia is centrally mediated, so it is not prioritized. And both syndromes cause HYPERthermia, not hypothermia — along with acidosis, rhabdomyolysis, and renal failure." },

  { id: "pe24-135", domain: "pain", difficulty: 3, tags: ["Buprenorphine", "Sickle Cell"],
    stem: "NP is a 30-year-old man presenting with acute-on-chronic pain from a sickle cell vaso-occlusive crisis. He usually takes about 35 mg/day of oral oxycodone but ran out 2 days ago. His COWS score is 9. The team wants to switch him to buprenorphine. Per the ACEP Buprenorphine Use in the Emergency Department tool, which initial sublingual dose is most appropriate?",
    options: ["4 mg", "10 mg", "16 mg", "20 mg"], correctIndex: 0,
    rationale: "A COWS above 8 confirms he is in withdrawal, so buprenorphine can be started without precipitating it. The ACEP tool ties the initial dose to prior opioid exposure: below 40 mg/day of oxycodone or hydrocodone starts at 4 mg sublingually, and his 35 mg/day falls under that. Larger doses may follow after assessing response, but starting high risks oversedation." },

  { id: "pe24-136", domain: "pain", difficulty: 2, tags: ["Buprenorphine", "Drug Interactions"],
    stem: "JK is a 28-year-old woman started on 8 mg/day sublingual buprenorphine in the ED for sickle cell pain and opioid withdrawal. Home medications include alprazolam as needed for anxiety, bupropion for smoking cessation, loratadine for seasonal allergies, and ondansetron as needed for nausea. Which should you advise discontinuing while she takes buprenorphine after discharge?",
    options: ["Alprazolam", "Bupropion", "Loratadine", "Ondansetron"], correctIndex: 0,
    rationale: "Benzodiazepines combined with buprenorphine produce additive sedation and respiratory depression, the interaction of greatest consequence here. Bupropion is non-serotonergic, so it does not carry the serotonin-related caution that applies to SSRIs and SNRIs. Loratadine is a second-generation antihistamine with minimal sedation or anticholinergic effect. Ondansetron does not interact adversely and may actually help with buprenorphine-related nausea." },

  { id: "pe24-137", domain: "pain", difficulty: 2, tags: ["Buprenorphine", "Dosing Interval"],
    stem: "EP is a 35-year-old woman who presented with acute-on-chronic sickle cell pain and withdrawal symptoms. She received a sublingual buprenorphine 4 mg tablet in the ED. If she does NOT experience withdrawal symptoms, how soon after the first dose may a second dose be given for pain management?",
    options: ["60-90 minutes", "15-30 minutes", "30-45 minutes", "45-60 minutes"], correctIndex: 0,
    rationale: "Sublingual buprenorphine peaks around 30-60 minutes, but repeat dosing waits until 60-90 minutes have elapsed so the full effect of the prior dose can be judged. Redosing sooner risks stacking before the peak is seen. Provided no withdrawal appears, doses may then be repeated at that interval until pain is controlled." },

  { id: "pe24-138", domain: "cv", difficulty: 2, tags: ["Pulmonary Embolism", "Risk Stratification"],
    stem: "JP is a 50-year-old woman presenting with right lower leg swelling and cough with red-tinged sputum. She had a left lower leg DVT 4 weeks ago and underwent bilateral salpingo-oophorectomy 3 weeks ago. Heart rate is 110 bpm and oxygen saturation is 93% on room air. Using the Wells criteria, what is her pretest probability of pulmonary embolism?",
    options: ["High", "Moderate", "Low", "Cannot be assigned until a D-dimer results"], correctIndex: 0,
    rationale: "Wells points: clinical signs of DVT (unilateral leg swelling) 3, heart rate above 100 1.5, surgery within 4 weeks 1.5, prior DVT 1.5, and hemoptysis 1 — 8.5 points before even adding 3 if PE is the most likely diagnosis. More than 6 points is HIGH probability, so she goes straight to CT pulmonary angiography; a D-dimer adds nothing at high pretest probability. The PERC rule cannot assign a probability: it applies only to patients already judged LOW probability, and she fails seven of its eight criteria",
    source: "Wells PS, et al. Thromb Haemost 2000; 2026 AHA/ACC Acute Pulmonary Embolism Guideline", updated: "2026-11" },

  { id: "pe24-139", domain: "cv", difficulty: 3, tags: ["VTE", "Anticoagulation"],
    stem: "DK is a 40-year-old woman presenting with shortness of breath and left lower leg swelling, with no significant medical history. She lives alone and has issues with hand dexterity. Vitals and labs: BP 110/80, HR 90, weight 140 lb, height 5'0\", serum creatinine 1.3 mg/dL. CT imaging is positive for acute pulmonary embolism. Per the 2026 AHA/ACC pulmonary embolism guideline, which anticoagulant is most appropriate to start?",
    options: ["Oral apixaban", "Oral vitamin K antagonist", "Oral dabigatran", "Subcutaneous enoxaparin"], correctIndex: 0,
    rationale: "DOACs are recommended over vitamin K antagonists unless contraindicated (2026 AHA/ACC, as in CHEST 2021). Her HAND DEXTERITY problem is the discriminator: she cannot self-administer subcutaneous injections, which rules out enoxaparin AND dabigatran, since dabigatran requires 5 days of parenteral lead-in. Apixaban starts orally with no parenteral lead-in, making it the only fully oral, single-drug option among these choices for a hemodynamically stable PE (rivaroxaban, not listed, works the same way)",
    source: "2026 AHA/ACC Acute Pulmonary Embolism Guideline; CHEST 2021 VTE guideline", updated: "2026-11" },

  { id: "pe24-140", domain: "cv", difficulty: 2, tags: ["Pulmonary Embolism", "Disposition"],
    stem: "PT is a 60-year-old man presenting with signs and symptoms of pulmonary embolism, confirmed by V/Q scan. He has hypertension. He lives alone with his dog and would prefer discharge home for treatment. The resident is debating whether to base the home-treatment decision on the simplified Pulmonary Embolism Severity Index or the Hestia criteria. What do you recommend?",
    options: ["Use either the sPESI or the Hestia criteria to make the decision", "Use only the sPESI", "Use only the Hestia criteria", "Do not consider home treatment regardless of either tool"], correctIndex: 0,
    rationale: "The HOME-PE randomized trial found the Hestia rule and sPESI similar in efficacy and safety for triaging acute PE patients to home treatment, so either is acceptable and neither is mandated over the other. Home treatment of appropriately selected low-risk PE is well supported and offers considerable cost savings, so ruling it out categorically is wrong; the 2026 AHA/ACC guideline likewise calls outpatient treatment reasonable for low-severity patients (categories A and B) selected with Hestia, PESI, or sPESI",
    source: "HOME-PE trial (Eur Heart J 2021); 2026 AHA/ACC Acute Pulmonary Embolism Guideline", updated: "2026-11" },

  { id: "pe24-141", domain: "pmr", difficulty: 2, tags: ["Medication Access", "Adherence"],
    stem: "OP is a 35-year-old woman being discharged from the ED with a prescription for a brand-name direct oral anticoagulant to treat deep vein thrombosis. She is currently between jobs and has no health insurance. Which is most likely to help her afford and adhere to the prescribed medication?",
    options: ["Manufacturer assistance program enrollment", "Health insurance enrollment", "Case management appointment", "Primary care physician follow-up visit"], correctIndex: 0,
    rationale: "The need is immediate: she must fill this prescription today, and a brand-name DOAC costs hundreds of dollars a month without insurance. The manufacturer's programs are the fastest route: a free 30-day trial card can be used with or without insurance, and patient assistance programs serve uninsured, low-income patients. A standard copay card would not help, because it requires commercial insurance. Insurance enrollment will not be active in time, and a case management appointment or primary care visit is a future event that does not solve today's cost barrier. (Generic dabigatran is the lower-cost exception if switching is appropriate.)",
    source: "Eliquis (Bristol Myers Squibb-Pfizer) co-pay card and free 30-day trial eligibility terms", updated: "2026-11" },

  { id: "pe24-142", domain: "renal", difficulty: 3, tags: ["Hyponatremia", "Hypertonic Saline"],
    stem: "A 62-year-old man with atrial fibrillation, arthritis, and alcohol use disorder (two 750-mL bottles of vodka daily) presents with dizziness, nausea, and extreme fatigue, denying vomiting or trauma. Medications include metoprolol succinate 100 mg daily and ibuprofen as needed. Vitals: BP 134/96, HR 99, RR 16. Labs: sodium 110 mEq/L, potassium 3.2, creatinine 1.1, AST 1114, ALT 1342, bilirubin 2.4, INR 1.6. What is the most appropriate treatment for his hyponatremia?",
    options: ["3% NaCl 30 mL/hr as a continuous IV infusion via a peripheral vein, with serum sodium every 4 hours", "3% NaCl 100-150 mL/hr as a continuous IV infusion via central line, with serum sodium every 4 hours", "3% NaCl 100-mL IV boluses over 10-20 minutes x 3 as needed until symptoms resolve, with hourly sodium", "Discontinue metoprolol and limit free water to less than daily urine output, with weekly sodium checks"], correctIndex: 0,
    rationale: "A sodium of 110 with moderate symptoms (nausea, dizziness, profound fatigue, but no seizures or coma) calls for a slow, closely monitored hypertonic saline infusion; boluses are reserved for severe symptoms. He is at very high risk of osmotic demyelination: alcohol use disorder, hypokalemia, liver injury, and probable malnutrition, and a low-solute drinker can autocorrect quickly once he eats. So aim for a rise of about 4-6 and no more than 8 mEq/L in 24 hours, checking sodium often; 100-150 mL/hr is far too fast. Metoprolol is not a recognized cause of hyponatremia, and fluid restriction with weekly checks ignores a dangerous sodium of 110. 3% saline can run through a peripheral vein; a central line is not required",
    source: "Verbalis JG, et al. Hyponatremia treatment guidelines: expert panel recommendations. Am J Med 2013; Spasovski G, et al. European clinical practice guideline on hyponatraemia. Eur J Endocrinol 2014", updated: "2026-11" },

  { id: "pe24-143", domain: "gi", difficulty: 3, tags: ["Hepatic Encephalopathy", "Lactulose"],
    stem: "KP is a 32-year-old man presenting with altered mental status after excessive alcohol consumption, intubated for airway protection due to combativeness. Ammonia is 240 micromol/L; AST 2546 IU/L and ALT 1243 IU/L. Multiple attempts at nasogastric tube placement have failed. Which retention enema is most appropriate for his encephalopathy?",
    options: ["Lactulose 200 g in 700 mL of 0.9% sodium chloride, retained as long as possible and repeated every 6 hours", "Lactulose 30 g in 500 mL of 0.9% sodium chloride, retained as long as possible and repeated every 6 hours", "Rifaximin 1200 mg in 700 mL of 0.9% sodium chloride, retained as long as possible every 8 hours", "Tap water retained as long as possible and repeated every 6 hours"], correctIndex: 0,
    rationale: "The studied lactulose enema formulation is 200 g in 700 mL of saline — far larger than the familiar 30 g oral dose, which is the trap in this question. A randomized double-blind trial showed acidifying lactulose enemas significantly outperformed non-acidifying tap water enemas in acute portal-systemic encephalopathy. Rifaximin enemas have not been studied for this indication." },

  { id: "pe24-144", domain: "id", difficulty: 3, tags: ["C. difficile", "Guidelines"],
    stem: "Per the 2021 IDSA/SHEA guidelines for Clostridioides difficile infection, which is recommended for a patient's FIRST recurrent episode (initial plus 1 recurrence) of NON-SEVERE CDI?",
    options: ["Fidaxomicin 200 mg by mouth every 12 hours x 10 days", "Vancomycin 500 mg by mouth every 6 hours plus metronidazole 500 mg IV every 8 hours x 10 days", "Rectal vancomycin retention enema 500 mg in 100 mL normal saline every 6 hours x 10 days", "Fecal microbiota transplant"], correctIndex: 0,
    rationale: "For a first recurrence the 2021 update suggests fidaxomicin (standard 10-day or extended-pulsed) over a standard vancomycin course; a tapered-pulsed vancomycin regimen or a standard vancomycin course are acceptable alternatives. Vancomycin followed by rifaximin and fecal microbiota transplant are reserved for MULTIPLE recurrences. The other distractors treat FULMINANT CDI: oral vancomycin plus IV metronidazole without ileus, and a vancomycin retention enema with ileus. Bezlotoxumab, once an add-on for recurrence, has been discontinued",
    source: "Johnson S, et al. 2021 IDSA/SHEA focused update on C. difficile infection in adults", updated: "2026-11" },

  { id: "pe24-145", domain: "renal", difficulty: 2, tags: ["Hypokalemia", "Electrolytes"],
    stem: "JR is a 45-year-old man (85 kg) with hypertension and heart failure (ejection fraction 14%) presenting with palpitations. ECG shows flattened T waves and bradycardia in the 40s; BP 117/86. He admits nonadherence with his diuretic. Exam shows anasarca, rales, and 3+ edema. Labs: Na 130, K 2.2 mEq/L, Cl 97, HCO3 30. After 40 mEq of potassium chloride IV and 40 mEq orally, repeat potassium is 2.4 mEq/L. What additional lab would you order?",
    options: ["Serum magnesium", "Serum albumin", "Serum phosphorus", "Urine osmolality"], correctIndex: 0,
    rationale: "Potassium that barely moves after substantial repletion is the classic signature of untreated HYPOMAGNESEMIA, since magnesium depletion promotes renal potassium wasting and must be corrected before potassium will hold. Albumin is used to correct calcium, phosphorus is unrelated to refractory hypokalemia, and urine osmolality helps evaluate sodium disorders — his sodium of 130 is near normal." },

  { id: "pe24-146", domain: "gi", difficulty: 2, tags: ["Cirrhosis", "SBP", "Albumin"],
    stem: "Which outcome has been shown to be significantly reduced by the use of albumin in patients with cirrhosis and spontaneous bacterial peritonitis?",
    options: ["90-day mortality", "Need for renal replacement therapy", "Hospital length of stay", "90-day hospital readmission rate"], correctIndex: 0,
    rationale: "In the landmark trial of 126 patients, adding albumin to ceftriaxone significantly reduced renal impairment, in-hospital mortality, and 90-day mortality. The other three outcomes listed were simply not evaluated in that trial — note the distinction between reduced renal IMPAIRMENT, which was shown, and need for renal REPLACEMENT therapy, which was not." },

  { id: "pe24-147", domain: "gi", difficulty: 3, tags: ["Cirrhosis", "Coagulopathy", "GI Bleed"],
    stem: "YR is a 56-year-old man (5'11\", 50 kg) with alcohol use disorder, cirrhosis, and peptic ulcer disease, presenting with 2 days of bloody vomiting and a week of diarrhea. He is grossly intoxicated with GCS 10. Hemoglobin 8.2 g/dL, INR 1.9, Rockall score 2. BP 105/72, HR 86. Octreotide and ceftriaxone are started and endoscopy is planned. The gastroenterologist asks you to reverse the INR. What do you recommend?",
    options: ["Vitamin K 10 mg IV x 1 and thromboelastography", "Vitamin K 10 mg orally x 1 and thromboelastography", "Fresh frozen plasma 4 units by IV infusion", "Four-factor prothrombin complex concentrate 3000 units IV over 10 minutes"], correctIndex: 0,
    rationale: "A raised INR in cirrhosis usually reflects reduced factor synthesis rather than true anticoagulation, but his BMI of about 15 and week of diarrhea make genuine vitamin K deficiency plausible, so a single dose plus thromboelastography to characterize the actual defect is the measured approach. Oral vitamin K is poorly absorbed in cirrhosis, so IV is preferred. FFP risks volume overload, and 3000 units of PCC in a 50-kg man is 60 units/kg — above the accepted 25-50 units/kg range, and unwarranted without true coagulopathy." },

  { id: "pe24-148", domain: "onc", difficulty: 3, tags: ["Hypercalcemia of Malignancy"],
    stem: "IP is a 76-year-old woman with osteosarcoma and stage III chronic kidney disease presenting with progressively worsening fatigue over 2 weeks. Total serum calcium is markedly elevated with ionized calcium 1.9 mmol/L. After 6 hours of 0.9% sodium chloride at 200 mL/hr plus furosemide 20 mg IV push, her calcium remains elevated. Which treatment is most appropriate?",
    options: ["Calcitonin 4 units/kg SC every 12 hours and zoledronic acid 4 mg IV over 15 minutes", "Calcitonin 4 units/kg SC every 12 hours and zoledronic acid 5 mg IV over 15 minutes", "Hemodialysis", "Bumetanide 2 mg IV push"], correctIndex: 0,
    rationale: "For severe hypercalcemia of malignancy the Endocrine Society suggests calcitonin plus an antiresorptive. Calcitonin lowers calcium within hours but loses effect (tachyphylaxis) within about 48 hours, so zoledronic acid or denosumab provides durable control. Calcitonin-salmon is dosed in units, 4 units/kg SC or IM every 12 hours, not in milligrams by IV push. Zoledronic acid 4 mg is the hypercalcemia-of-malignancy dose; 5 mg is the osteoporosis and Paget's dose. Switching loop diuretics adds little, and dialysis is premature while drug therapy is untried. With her CKD, denosumab is a reasonable alternative to zoledronic acid, with close calcium monitoring",
    source: "El-Hajj Fuleihan G, et al. Treatment of hypercalcemia of malignancy in adults: Endocrine Society guideline. J Clin Endocrinol Metab 2023; Miacalcin (calcitonin-salmon) injection and Zometa prescribing information", updated: "2026-11" },

  { id: "pe24-149", domain: "resus", difficulty: 3, tags: ["Vasopressors", "Infusion Calculation"],
    stem: "A 68-year-old woman (dosing weight 92 kg) arrives from an outside hospital on a norepinephrine infusion of 8 mg in 250 mL normal saline running at 86 mL/hr. Your facility's standard peripheral concentration is 4 mg in 250 mL. Her MAP was 68-72 mm Hg en route and is currently 67 mm Hg. What do you recommend?",
    options: ["Program the pump to start at 0.5 mcg/kg/min", "Program the pump to start at 0.05 mcg/kg/min", "Program the pump to start at 0.25 mcg/kg/min", "Withhold norepinephrine because the MAP is at goal"], correctIndex: 0,
    rationale: "Convert using the concentration she is ACTUALLY receiving: 86 mL/hr x (8 mg/250 mL) x 1000 mcg/mg ÷ 60 min ÷ 92 kg ≈ 0.5 mcg/kg/min. Using the receiving facility's 4 mg/250 mL in the calculation halves the answer to 0.25 and would cut her dose in half — the central trap. Starting at the textbook 0.05 mcg/kg/min or stopping the drug entirely would drop a patient already borderline at MAP 67 into frank hypotension." },

  { id: "pe24-150", domain: "resus", difficulty: 3, tags: ["Septic Shock", "Vasopressors"],
    stem: "A 72-year-old woman (60 kg) presents with altered mental status and abdominal pain. History includes atrial fibrillation, hypertension, and type 2 diabetes. Vitals: BP 90/62, HR 120, RR 26, temp 38.9°C. She receives 2000 mL of lactated Ringer's and empiric piperacillin/tazobactam. On reassessment she has crackles on lung exam, BP 85/54, HR 110, and lactate 5 mmol/L. Which IV therapy is most appropriate next?",
    options: ["Norepinephrine 0.05 mcg/kg/min", "Vasopressin 0.03 units/min", "Lactated Ringer's 500 mL bolus", "Normal saline 1000 mL bolus"], correctIndex: 0,
    rationale: "She has received 2000 mL, about 33 mL/kg, meeting the initial resuscitation target, and remains hypotensive with a rising lactate — that is septic shock requiring a vasopressor, and norepinephrine is first line per Surviving Sepsis. New crackles signal developing fluid overload, so further boluses would do harm. Vasopressin (usually 0.03 units/min) is the SECOND-line add-on, not the initial agent",
    source: "Surviving Sepsis Campaign adult guidelines 2021", updated: "2026-11" },

  { id: "pe24-151", domain: "resus", difficulty: 3, tags: ["Septic Shock", "Vasopressors"],
    stem: "A 54-year-old man with septic shock is receiving norepinephrine 0.5 mcg/kg/min with MAP 55 mm Hg, RR 26, and HR 150 bpm. He has received appropriate antimicrobials and 6 L of lactated Ringer's over 4 hours. What is the most appropriate next step?",
    options: ["Add IV vasopressin 0.03 units/min", "Titrate norepinephrine up by 0.1 mcg/kg/min every 5 minutes", "Add hydrocortisone 100 mg IV every 6 hours", "Add IV epinephrine 1 mcg/kg/min"], correctIndex: 0,
    rationale: "He is below his MAP goal on a moderate-to-high norepinephrine dose AND is tachycardic at 150 — likely beta-1 effect from the norepinephrine — so adding a drug with a DIFFERENT mechanism is preferable to pushing the same one higher. Vasopressin (usually 0.03 units/min) is the guideline second agent, typically added once norepinephrine reaches 0.25–0.5 mcg/kg/min. Epinephrine would worsen the tachycardia. Corticosteroids are reasonable in ongoing vasopressor requirement, but the dose is 200 mg/day total; 100 mg every 6 hours is 400 mg/day",
    source: "Surviving Sepsis Campaign adult guidelines 2021", updated: "2026-11" },

  { id: "pe24-152", domain: "id", difficulty: 3, tags: ["Pyelonephritis", "Empiric Therapy"],
    stem: "A 54-year-old woman presents with lethargy, vomiting, weakness, and fever after cystoscopy with bilateral ureteral stent exchange and clamping of nephrostomy tubes. Vitals: BP 85/46, HR 123, RR 24, temp 39.9°C. History includes pancreatic cancer on chemotherapy and C. difficile infection 2 months ago. She recently received two courses of empiric antibiotics; cultures grew only Enterococcus faecalis. Urinalysis shows over 10 WBC/hpf with positive nitrites and leukocyte esterase. Which empiric IV therapy would you start?",
    options: ["Piperacillin/tazobactam 4.5 g", "Ceftriaxone 2 g", "Cefazolin 2 g", "Tobramycin 7 mg/kg"], correctIndex: 0,
    rationale: "Urinary hardware, immunosuppression from chemotherapy, multiple recent antibiotic courses, and critical illness all demand broad coverage INCLUDING Pseudomonas and the Enterococcus already isolated — piperacillin/tazobactam covers both. Ceftriaxone misses Enterococcus and Pseudomonas; cefazolin is far too narrow. Tobramycin covers gram-negatives but risks nephrotoxicity in someone with likely obstructive acute kidney injury when better options exist." },

  { id: "pe24-153", domain: "pmr", difficulty: 2, tags: ["SEP-1", "Quality Measures"],
    stem: "You are establishing emergency medicine pharmacist services and the ED wants to improve compliance with the CMS SEP-1 core measure. For patients presenting with SEPTIC SHOCK, which goal should be targeted?",
    options: ["Blood cultures drawn prior to antibiotic administration and within 3 hours after presentation", "Broad-spectrum antibiotics administered within 1 hour after presentation", "Vasopressors administered within 3 hours after presentation", "Repeat lactate measurement within 3 hours if the initial lactate was elevated"], correctIndex: 0,
    rationale: "SEP-1 sets blood cultures before antibiotics and within 3 hours. The distractors all cite real SEP-1 elements with the WRONG clock: antibiotics are within 3 hours (not 1 — that 1-hour figure comes from Surviving Sepsis, not SEP-1), vasopressors within 6 hours if hypotension persists, and repeat lactate within 6 hours. Knowing which measure attaches to which interval is the whole point." },

  { id: "pe24-154", domain: "id", difficulty: 2, tags: ["Pyelonephritis", "Risk Stratification"],
    stem: "For which patient with pyelonephritis would broad-spectrum antimicrobial therapy be most appropriate because of the complicated, high-risk nature of the infection?",
    options: ["A 74-year-old woman with a renal transplant 6 years ago", "A 24-year-old woman with poorly controlled type 1 diabetes", "A 46-year-old woman with well-controlled HIV and new acute kidney injury from dehydration", "A 58-year-old woman with two UTIs in the past year, last treated 3 months ago, without multidrug-resistant organisms"], correctIndex: 0,
    rationale: "Renal transplant recipients are immunosuppressed AND have altered urinary anatomy, placing them at high risk of complications and resistant organisms. Poorly controlled diabetes alone, well-controlled HIV, and dehydration-related AKI do not by themselves justify broad coverage. Recurrent UTIs matter only when resistant organisms have actually been isolated or antibiotic exposure is very recent — neither applies here." },

  { id: "pe24-155", domain: "pmr", difficulty: 2, tags: ["Order Sets", "Quality Improvement"],
    stem: "You are developing a sepsis medication order set in the electronic medical record as a quality initiative. Your ED has historically used normal saline for resuscitation and you want to shift toward balanced fluids. What is the most appropriate approach?",
    options: ["Include both normal saline and lactated Ringer's in the order set, with instructions on when one fluid may be preferred", "Include only lactated Ringer's to limit prescribers to the preferred fluid", "Include lactated Ringer's, Plasma-Lyte, and normal saline, with education delivered separately about their differences", "Make no change, because evidence favoring balanced fluids is not strong enough"], correctIndex: 0,
    rationale: "Embedding decision support at the point of ordering guides practice while preserving clinical judgment. Restricting to lactated Ringer's alone would create problems — for example incompatibility with certain antibiotics could delay therapy. Education delivered separately from the order set is less effective than guidance at the moment of decision. And evidence does show a modest mortality and renal benefit for balanced fluids, so declining to change is not supportable." },

  { id: "pe24-156", domain: "id", difficulty: 3, tags: ["Sepsis", "Antibiotic Sequencing"],
    stem: "An 82-year-old man presents with altered mental status, fever, and hypotension; initial lactate is 5 mmol/L. History includes hypertension, peripheral arterial disease, diabetes, and recent admission for community-acquired pneumonia. Broad-spectrum therapy is planned but no source is identified; lungs are clear and urinalysis is negative. He has only ONE venous access point. Which IV antimicrobial dose should be given FIRST?",
    options: ["Cefepime 2 g", "Tobramycin 7 mg/kg", "Vancomycin 25 mg/kg", "Azithromycin 500 mg"], correctIndex: 0,
    rationale: "With a single line the sequence matters, and cefepime has the broadest spectrum of the four, covering both gram-positives and gram-negatives including Pseudomonas. Observational data show giving a beta-lactam BEFORE vancomycin improves survival in bloodstream infection. Vancomycin alone leaves gram-negatives uncovered, tobramycin is an adjunct rather than a first dose, and azithromycin targets atypicals in a respiratory source that is unlikely here." },

  { id: "pe24-157", domain: "id", difficulty: 3, tags: ["MRSA", "Empiric Coverage"],
    stem: "For which patient would empiric MRSA coverage be warranted per the 2021 Surviving Sepsis Campaign and IDSA guidelines?",
    options: ["A 38-year-old man with redness surrounding a dialysis catheter, fever, altered mental status, and tachypnea", "A 50-year-old woman with normal urinary anatomy presenting with altered mental status and fever from a urinary source, without septic shock", "A 29-year-old man with community-acquired pneumonia and a leg abscess caused by MSSA 5 years ago", "A 22-year-old woman with septic shock due to ruptured appendicitis"], correctIndex: 0,
    rationale: "An infected INDWELLING DEVICE plus signs of sepsis is a classic MRSA risk factor requiring empiric coverage. A urinary source with normal anatomy does not warrant it. A remote MSSA abscess is not a MRSA risk factor — the distinction between the two organisms is the trap. Community-acquired intra-abdominal infection such as ruptured appendicitis does not require anti-MRSA therapy." },

  { id: "pe24-158", domain: "id", difficulty: 3, tags: ["Cystitis", "Culture Follow-up"],
    stem: "A 29-year-old woman was discharged from the ED with ciprofloxacin 500 mg twice daily for 3 days for cystitis. Her urine culture returns 2 days later with more than 100,000 CFU/mL of E. coli resistant to ciprofloxacin and trimethoprim/sulfamethoxazole but susceptible to other agents. You call her: she is not pregnant, has NO prescription drug insurance, no allergies, and no features suggesting pyelonephritis. Which oral regimen do you recommend?",
    options: ["Nitrofurantoin 100 mg every 12 hours for 5 days", "Cefdinir 300 mg every 12 hours for 7 days", "Fosfomycin 3 g once", "Cephalexin 500 mg every 6 hours for 3 days"], correctIndex: 0,
    rationale: "Nitrofurantoin is guideline-recommended first line for uncomplicated cystitis, narrow-spectrum, correctly dosed at 5 days, and inexpensive — which matters because she has no drug coverage. Cefdinir is unnecessarily broad and costly. Fosfomycin is also first line but is costly and slightly less effective. Cephalexin is cheap, but beta-lactams are second line for cystitis (less effective) and are usually given for 5–7 days, so a 3-day course is too short",
    source: "IDSA/ESCMID guideline for acute uncomplicated cystitis and pyelonephritis in women (2010)", updated: "2026-11" },

  { id: "pe24-159", domain: "id", difficulty: 3, tags: ["Syphilis", "Staging"],
    stem: "JB is a 34-year-old man who requested STI testing after a recent exposure of concern. He has NO symptoms and physical examination is normal. Six months ago all syphilis testing was non-reactive/negative. Today: gonorrhea and chlamydia not detected, Trichomonas negative, TP-PA REACTIVE, syphilis IgG/IgM positive, RPR titer 1:64, HIV non-reactive. What is the most accurate diagnosis to report to the state health department?",
    options: ["Early latent syphilis", "Primary syphilis", "Secondary syphilis", "Late latent syphilis"], correctIndex: 0,
    rationale: "Diagnosis requires both a treponemal (TP-PA) and non-treponemal (RPR) test to be positive, which they now are. Staging then rests on symptoms and timing: he has NO symptoms, so neither primary (chancre) nor secondary (rash on trunk, palms, soles) applies. Latent disease is 'early' when seroconversion occurred within the previous 12 months — his documented negative test 6 months ago proves that, distinguishing it from late latent." },

  { id: "pe24-160", domain: "id", difficulty: 3, tags: ["Sexual Assault", "Hepatitis B Prophylaxis"],
    stem: "HM is a 21-year-old woman presenting about 2 hours after a sexual assault. The assailant's history and whereabouts are unknown. Her records confirm a completed hepatitis B vaccine series, but she has never had antibody titers checked. She wants all available post-exposure treatment. Per CDC guidelines, what is the most appropriate hepatitis B post-exposure prophylaxis?",
    options: ["Administer HBV vaccine x 1 dose", "Administer HBV vaccine x 1 dose and schedule follow-up to complete a three-dose series", "Administer hepatitis B immunoglobulin and HBV vaccine x 1 dose, with follow-up to complete a three-dose series", "Give neither vaccine nor immunoglobulin, because she is already vaccinated"], correctIndex: 0,
    rationale: "Her vaccination status drives the answer. Because she has a documented vaccine series but no post-vaccination titers, CDC recommends a single BOOSTER dose when the assailant's status is unknown. A full three-dose series is for survivors who are UNvaccinated. Hepatitis B immunoglobulin is added for unvaccinated survivors when the assailant is known to be HBV positive, and here the assailant's status is unknown. Doing nothing ignores her unverified immunity",
    source: "CDC Sexually Transmitted Infections Treatment Guidelines, 2021 (hepatitis B postexposure prophylaxis)", updated: "2026-11" },

  { id: "pe24-161", domain: "id", difficulty: 3, tags: ["Genital Herpes", "Antivirals"],
    stem: "KR is a 33-year-old woman with 3 days of external genital pain worsened by urination. Exam shows numerous painful pustules and ulcers on the labia; the rest of the exam is unremarkable. She has never had these symptoms or an STI diagnosis, and reports a new sexual contact about 10 days ago. Pregnancy test, urinalysis, gonorrhea, chlamydia, and trichomoniasis are all negative; HSV swab is pending. What is the most appropriate treatment?",
    options: ["Valacyclovir 1000 mg by mouth twice daily for 7 days", "Acyclovir 800 mg by mouth twice daily for 5 days", "Famciclovir 500 mg by mouth three times daily for 7 days", "Withhold treatment until diagnostic results are available"], correctIndex: 0,
    rationale: "Antiviral therapy works best within 7 days of symptom onset and should be started EMPIRICALLY on characteristic findings rather than waiting for confirmation. For a primary outbreak the correct regimens are valacyclovir 1000 mg twice daily, famciclovir 250 mg (not 500) three times daily, or acyclovir 400 mg three times daily (not 800 mg twice daily) — the two wrong options name the right drugs at the wrong doses. Duration is 7-10 days." },

  { id: "pe24-162", domain: "id", difficulty: 3, tags: ["HIV PEP", "Counseling"],
    stem: "SA is a 35-year-old woman starting HIV post-exposure prophylaxis after a sexual assault with tenofovir disoproxil fumarate, emtricitabine, and raltegravir. Which counseling point is most appropriate?",
    options: ["You should receive repeat HIV testing in 6 weeks and 3 months", "You may stop these medications if your HIV test result is negative", "You should take these medications together once daily at the same time each day", "You should not take this regimen if you become pregnant"], correctIndex: 0,
    rationale: "Follow-up serologic testing at 6 weeks and 3 months is standard after PEP. The other statements invert the facts: a NEGATIVE baseline test is the reason to COMPLETE the full 28-day course, not stop it. Raltegravir is dosed TWICE daily even though tenofovir and emtricitabine are once daily. And pregnancy is not a reason to stop it: raltegravir is compatible with pregnancy. The 2025 CDC nPEP update now prefers bictegravir/emtricitabine/tenofovir alafenamide or a dolutegravir-based regimen for most adults; raltegravir regimens remain alternatives, and follow-up testing is at 4–6 and 12 weeks",
    source: "CDC nPEP guidelines 2025 (MMWR Recomm Rep 2025;74(1))", updated: "2026-11" },

  { id: "pe24-163", domain: "id", difficulty: 3, tags: ["Gonorrhea", "Weight-Based Dosing"],
    stem: "CB is a 21-year-old man presenting with penile discharge that began a day ago. He has no significant history or allergies and reports a weight of 346 lb. Results: Neisseria gonorrhoeae DETECTED, Chlamydia trachomatis not detected, Trichomonas not detected, syphilis non-reactive, HIV non-reactive. Per CDC guidelines, what is the most appropriate treatment?",
    options: ["Ceftriaxone 1000 mg intramuscularly x 1 dose", "Doxycycline 100 mg by mouth twice daily for 7 days", "Ceftriaxone 500 mg intramuscularly x 1 dose plus doxycycline 100 mg twice daily for 7 days", "Azithromycin 2000 mg by mouth x 1 dose"], correctIndex: 0,
    rationale: "Two decisions combine. Because chlamydia testing is available and NEGATIVE, ceftriaxone monotherapy is correct — routine dual therapy is no longer recommended when chlamydia is excluded. Then weight determines the dose: 346 lb is about 157 kg, above the 150-kg threshold, so 1000 mg rather than the usual 500 mg. Doxycycline treats chlamydia, and azithromycin monotherapy is no longer recommended for gonorrhea." },

  { id: "pe24-164", domain: "id", difficulty: 3, tags: ["Asymptomatic Bacteriuria", "Stewardship"],
    stem: "CD is a 19-year-old woman evaluated for pelvic pain, denying urinary urgency, frequency, or dysuria. Vitals and exam are normal except adnexal tenderness. Pregnancy test negative; moderate clue cells and positive Trichomonas antigen were treated at discharge. On culture follow-up, urine grows pan-susceptible coagulase-negative Staphylococcus. Urinalysis: WBC 34/hpf, RBC 0/hpf, leukocyte esterase 1+, nitrites negative, squamous cells 27/hpf. What antimicrobial recommendation is most appropriate?",
    options: ["No antibiotic therapy is needed based on these results", "Nitrofurantoin 100 mg by mouth twice daily for 5 days", "Sulfamethoxazole/trimethoprim 800/160 mg by mouth twice daily for 3 days", "Ciprofloxacin 250 mg by mouth twice daily for 3 days"], correctIndex: 0,
    rationale: "She has no urinary symptoms, so this is asymptomatic bacteriuria, which does not warrant treatment in a healthy non-pregnant woman. Two further clues confirm the specimen is unreliable: 27 squamous cells/hpf indicates skin contamination, and coagulase-negative Staphylococcus is a typical contaminant. Treating would expose her to needless antibiotics — a core stewardship point." },

  { id: "pe24-165", domain: "id", difficulty: 3, tags: ["Cystitis", "Men", "Culture Follow-up"],
    stem: "TR is a 54-year-old man with hypertension presenting with 2 days of severe dysuria and burning. Ultrasound is normal, he is afebrile, and has no abdominal, testicular, or flank pain. Urinalysis: 3+ WBC, 3+ leukocyte esterase, 3+ nitrites. Culture: more than 100,000 CFU E. coli — resistant to ampicillin, INTERMEDIATE to ampicillin/sulbactam and gentamicin, susceptible to cefazolin, ceftriaxone, ciprofloxacin, nitrofurantoin, and trimethoprim/sulfamethoxazole. What treatment is most appropriate?",
    options: ["Sulfamethoxazole/trimethoprim 800/160 mg by mouth twice daily for 7 days", "Nitrofurantoin 100 mg by mouth twice daily for 5 days", "Amoxicillin/clavulanic acid 875 mg by mouth twice daily for 10 days", "Ciprofloxacin 500 mg by mouth twice daily for 14 days"], correctIndex: 0,
    rationale: "He has simple cystitis, but being MALE changes two things: nitrofurantoin is generally avoided because it does not penetrate prostatic tissue, and duration extends to about 7 days. TMP-SMX is susceptible and appropriately dosed. The isolate is only INTERMEDIATE to ampicillin/sulbactam, making amoxicillin/clavulanate a poor choice. Ciprofloxacin is susceptible but fluoroquinolones should be avoided in uncomplicated cystitis when alternatives exist, and 14 days is unnecessarily long." },

  { id: "pe24-166", domain: "id", difficulty: 3, tags: ["Rhinosinusitis", "Stewardship"],
    stem: "NF is a 29-year-old woman with 2 weeks of facial pain, pressure, and purulent nasal discharge. Symptoms began about 3 weeks ago with 'the flu'; she initially improved, then progressively worsened. Antihistamines have not helped. She is otherwise healthy, last took antibiotics 6 months ago, and has no primary care physician. Which oral treatment is most appropriate?",
    options: ["Amoxicillin/clavulanate 875/125 mg twice daily for 7 days", "Levofloxacin 500 mg once daily for 7 days", "Azithromycin 500 mg once daily for 5 days", "Withhold antibiotics and provide supportive care with intranasal saline and analgesia"], correctIndex: 0,
    rationale: "Two features indicate bacterial rather than viral rhinosinusitis: symptoms beyond 10 days AND the 'double worsening' pattern of initial improvement followed by decline. Watchful waiting would be reasonable except that she has no reliable follow-up. Amoxicillin/clavulanate is preferred over amoxicillin because of beta-lactamase-producing H. influenzae. Macrolides face high resistance, and fluoroquinolones are alternatives to avoid when other options exist." },

  { id: "pe24-167", domain: "id", difficulty: 3, tags: ["Otitis Media", "Pediatrics"],
    stem: "RJ is a 4-year-old boy with acute otitis media and otorrhea. He has no medical history, takes no medications, has never had antibiotics, and is home schooled. His mother says RJ's brother had a severe allergic reaction to amoxicillin and adamantly refuses amoxicillin for RJ. Which oral treatment is most appropriate?",
    options: ["Cefdinir 14 mg/kg/day in 2 divided doses", "Sulfamethoxazole/trimethoprim 8 mg/kg/day of the trimethoprim component in 2 divided doses", "Cephalexin 25 mg/kg/day in 2 divided doses", "Clindamycin 30 mg/kg/day in 3 divided doses"], correctIndex: 0,
    rationale: "He is a candidate for amoxicillin with no resistance risk factors, but the parent refuses it, so the preferred alternative is an oral cephalosporin — cefdinir 14 mg/kg/day, cefuroxime, or cefpodoxime. Note a SIBLING's reaction is not the patient's allergy, so education is warranted even as you accommodate. Cephalexin is not recommended for otitis media, clindamycin lacks H. influenzae activity, and TMP-SMX faces high pneumococcal resistance." },

  { id: "pe24-168", domain: "id", difficulty: 3, tags: ["Strep Pharyngitis", "Pediatrics", "Dosing"],
    stem: "JS is a 5-year-old girl (25 kg) brought in with sore throat and fever. She has had typical childhood respiratory illnesses, last took antibiotics about 18 months ago, has no medical history, and takes a liquid multivitamin. Rapid antigen testing is positive for streptococcal pharyngitis. Which 10-day oral amoxicillin regimen is most appropriate?",
    options: ["Amoxicillin 500 mg twice daily", "Amoxicillin 300 mg twice daily", "Amoxicillin 625 mg twice daily", "Amoxicillin 1000 mg twice daily"], correctIndex: 0,
    rationale: "The regimen is 25 mg/kg per dose twice daily, capped at 500 mg per dose. For 25 kg the arithmetic gives 625 mg — which is exactly why 625 mg appears as a distractor — but that exceeds the maximum, so the dose is capped at 500 mg twice daily. Remembering the ceiling, not just the weight-based math, is what this question tests." },

  { id: "pe24-169", domain: "onc", difficulty: 2, tags: ["Hypercalcemia of Malignancy", "Medication Review"],
    stem: "BP is a 52-year-old woman with a month of weakness, nausea, vomiting, constipation, and back pain. Imaging 3 weeks ago showed a sacral mass with lytic bone lesions; cancer is suspected and oncology follow-up is next week. Labs: calcium 13.5 mg/dL, albumin 3.8 g/dL, creatinine 1.4 mg/dL, potassium 3.4 mEq/L, INR 1.3. Home medications: amlodipine, apixaban, hydrochlorothiazide, pantoprazole, trazodone, hydrocodone/acetaminophen. Which should be discontinued because of her probable hypercalcemia of malignancy?",
    options: ["Hydrochlorothiazide", "Apixaban", "Trazodone", "It is safe to continue all of her home medications"], correctIndex: 0,
    rationale: "Thiazide diuretics reduce renal calcium excretion and are a classic contributor to hypercalcemia, so hydrochlorothiazide should be held — her blood pressure can be managed by increasing amlodipine if needed. Apixaban does not affect calcium and there is no bleeding risk or invasive procedure planned. Trazodone has no role in calcium homeostasis." },

  { id: "pe24-170", domain: "onc", difficulty: 3, tags: ["Hypercalcemia of Malignancy", "Treatment"],
    stem: "BP, now diagnosed with multiple myeloma, has stable vital signs and today's labs show calcium 12.8 mg/dL, albumin 3.8 g/dL, creatinine 1.3 mg/dL (previous values unknown), and INR 1.5. She has had mild symptoms for about a month. Which intervention should be started promptly for her hypercalcemia of malignancy?",
    options: ["0.9% NaCl intravenously", "Zoledronic acid intravenously", "Calcitonin subcutaneously", "Furosemide intravenously"], correctIndex: 0,
    rationale: "Aggressive isotonic fluid is the mainstay: these patients are volume depleted, and saline restores perfusion and promotes calciuresis — which may also explain and improve her elevated creatinine. Zoledronic acid is first-line pharmacotherapy but should follow hydration given renal concerns, and takes 48-72 hours to work. Calcitonin is reserved for severe symptoms needing rapid reduction. Loop diuretics in a volume-depleted patient worsen renal function." },

  { id: "pe24-171", domain: "onc", difficulty: 2, tags: ["Tumor Lysis Syndrome"],
    stem: "RB is a 47-year-old man with newly diagnosed acute myeloid leukemia, reporting weeks of feeling unwell with lower extremity weakness and frequent nosebleeds. Labs: WBC 267 x 10^9/L, hemoglobin 6.5 g/dL, platelets 22 x 10^9/L, sodium 139, potassium 6.3 mEq/L, CO2 15, BUN 77 mg/dL, creatinine 5.65 mg/dL, glucose 146, calcium 9.6, phosphorus 8.5 mg/dL, uric acid 14.5 mg/dL, LDH 1292 units/L. Which abnormalities are consistent with tumor lysis syndrome?",
    options: ["Hyperkalemia, hyperuricemia, hyperphosphatemia", "Hyponatremia, hypoglycemia, uremia", "Hyperuricemia, hyperglycemia, hyperkalemia", "Uremia, hyperphosphatemia, hyponatremia"], correctIndex: 0,
    rationale: "Lysing tumor cells dump intracellular potassium, phosphorus, and nucleic acids that become uric acid — so potassium, phosphate, and urate all rise, and calcium typically falls as it binds phosphate. Uremia follows from renal injury. Sodium and glucose are NOT part of the syndrome, and indeed his sodium is normal and glucose near normal, which eliminates every option containing them." },

  { id: "pe24-172", domain: "onc", difficulty: 3, tags: ["Tumor Lysis Syndrome", "Hyperkalemia"],
    stem: "RB, the 47-year-old with AML and tumor lysis syndrome, has potassium 6.3 mEq/L, phosphorus 8.5 mg/dL, calcium 9.6 mg/dL, creatinine 5.65 mg/dL, and an unremarkable ECG. Which therapy is most appropriate to use INITIALLY for his hyperkalemia?",
    options: ["Insulin and dextrose", "Furosemide", "Calcium gluconate", "Renal replacement therapy"], correctIndex: 0,
    rationale: "Insulin with dextrose shifts potassium intracellularly within about 15 minutes, buying time while definitive therapy is arranged. Calcium is normally the first move in hyperkalemia, but here it should be AVOIDED absent ECG changes because a high calcium-phosphate product risks precipitation in renal tubules. Loop diuretics are hazardous in a volume-depleted patient with renal failure, and dialysis takes time to initiate." },

  { id: "pe24-173", domain: "onc", difficulty: 3, tags: ["Febrile Neutropenia", "Empiric Therapy"],
    stem: "SA is an 18-year-old man with B-cell ALL on hyper-CVAD, day 8 of cycle 4, presenting with worsening rectal pain and subjective fever. He has a history of hemorrhoids and rectal abscess and was recently hospitalized for MRSA bacteremia. Vitals: BP 89/56, HR 119, temp 39.1°C, RR 16. Labs: WBC 0.4 x 10^9/L, hemoglobin 7.1, platelets 3 x 10^9/L, creatinine 1.4 mg/dL (baseline 0.7). Home medications include levofloxacin, posaconazole, and valacyclovir. Which empiric IV regimen is most appropriate?",
    options: ["Cefepime + metronidazole + vancomycin", "Cefepime + caspofungin", "Cefepime + metronidazole + caspofungin", "Cefepime + vancomycin"], correctIndex: 0,
    rationale: "Three needs stack: an antipseudomonal beta-lactam for febrile neutropenia (cefepime), ANAEROBIC coverage for a perirectal source (cefepime alone is inadequate, so metronidazole), and MRSA coverage given his recent MRSA bacteremia and skin involvement (vancomycin). An antifungal is not needed now because he is already on posaconazole, an anti-mold agent — though a non-azole antifungal could be considered if fever persists to day 4." },

  { id: "pe24-174", domain: "onc", difficulty: 3, tags: ["Febrile Neutropenia", "ESBL"],
    stem: "AW is a 70-year-old man with multiple myeloma 2 months post stem cell transplant, residing in a nursing home, who developed febrile neutropenia with abdominal pain and diarrhea 3 days ago. IV cefepime and metronidazole were started without improvement and fever persists. Vitals today are stable. Records show blood cultures from 3 days ago grew ESBL-producing Klebsiella pneumoniae susceptible only to carbapenems and amikacin; the C. difficile DNA assay was negative. What change should be made?",
    options: ["Discontinue both cefepime and metronidazole and start meropenem", "Continue cefepime but discontinue metronidazole", "Continue both and add amikacin", "Continue both cefepime and metronidazole"], correctIndex: 0,
    rationale: "Carbapenems are the treatment of choice for ESBL producers, and cefepime should not be relied on despite any in vitro result. With a negative C. difficile assay and no ongoing anaerobic indication, metronidazole can also stop. Adding amikacin for double gram-negative coverage is reserved for critically ill or clinically deteriorating patients, and his vital signs are now stable." },

  { id: "pe24-175", domain: "onc", difficulty: 2, tags: ["Tumor Lysis Syndrome", "G6PD"],
    stem: "Which medication should NOT be used in patients with tumor lysis syndrome and glucose-6-phosphate dehydrogenase deficiency because of the potential for methemoglobinemia and hemolytic anemia?",
    options: ["Rasburicase", "Allopurinol", "Febuxostat", "Sevelamer"], correctIndex: 0,
    rationale: "Rasburicase converts uric acid to allantoin and generates hydrogen peroxide as a byproduct; without G6PD to regenerate reduced glutathione, that peroxide causes hemolysis and methemoglobinemia — so G6PD deficiency is a contraindication. Allopurinol and febuxostat are safe in G6PD deficiency though less effective for established TLS, and the phosphate binder sevelamer is unaffected." },

  { id: "pe24-176", domain: "resus", difficulty: 3, tags: ["RSI", "Hyperkalemia"],
    stem: "JD is a 65-year-old man (about 70 kg) brought in by EMS for shortness of breath worsening over 12 hours, now unarousable. EMS reported initial SpO2 74%. On arrival: BP 178/109, HR 105, SpO2 97% on non-rebreather, temp 37.1°C. History includes COPD and end-stage renal disease on dialysis — he has MISSED his last two dialysis sessions. The team is preparing to intubate. Which induction sedative and paralytic combination is most appropriate?",
    options: ["Etomidate 20 mg and rocuronium 80 mg", "Etomidate 20 mg and succinylcholine 100 mg", "Ketamine 120 mg and rocuronium 50 mg", "Ketamine 120 mg and succinylcholine 80 mg"], correctIndex: 0,
    rationale: "Two missed dialysis sessions make hyperkalemia likely, and succinylcholine is contraindicated in hyperkalemia — with no potassium available, it must be avoided, eliminating two options. Etomidate 20 mg is just under 0.3 mg/kg and rocuronium 80 mg is about 1.1 mg/kg, both appropriate. Ketamine could worsen his blood pressure of 178/109, and the 50-mg rocuronium dose (0.7 mg/kg) would be inadequate for RSI." },

  { id: "pe24-177", domain: "safety", difficulty: 2, tags: ["Automated Dispensing Cabinets", "Anaphylaxis"],
    stem: "Pharmacy leadership is reviewing automated dispensing cabinet workflow. Currently all ED cabinet medications are available on override. Your input is sought on override access for medications used to treat anaphylaxis. What is the most appropriate response?",
    options: ["Epinephrine should be kept available by override, because rapid access is essential and arrest can occur within minutes without prompt treatment", "Epinephrine should be removed from override because multiple concentrations and routes could contribute to medication errors", "Methylprednisolone should be kept available by override because its onset takes hours, making delays critical", "Methylprednisolone should be removed from override because it worsens hyperglycemia and causes psychiatric disturbances"], correctIndex: 0,
    rationale: "Override access is justified when minutes matter, and anaphylaxis can kill within minutes — so epinephrine stays on override even though concentration and route confusion are real risks, because the benefit outweighs them. Corticosteroids are the mirror image: their onset takes hours and no benefit from early administration has been shown, so there is no time-critical reason for override — not because of hyperglycemia or psychiatric effects, which are minor with short courses." },

  { id: "pe24-178", domain: "resus", difficulty: 3, tags: ["Post-Intubation", "Hypotension"],
    stem: "MR is a 44-year-old woman intubated 5 minutes ago with etomidate and rocuronium for respiratory distress and hypoxia, likely from a viral respiratory illness. Before intubation her BP was 155/102 with HR 105; now BP is 81/48 with HR 116. Which strategy is most appropriate for her blood pressure change and post-intubation needs?",
    options: ["Administer a crystalloid IV fluid bolus immediately followed by post-intubation analgesia and sedation", "Initiate a norepinephrine infusion but withhold analgesia and sedation until blood pressure normalizes", "Initiate a norepinephrine infusion immediately followed by post-intubation analgesia and sedation", "Administer a crystalloid bolus but withhold analgesia and sedation until blood pressure normalizes"], correctIndex: 0,
    rationale: "Her MAP is about 59, so hypotension needs treating — and with no sign of fluid intolerance, crystalloid comes before a vasopressor. The critical half of the answer is that sedation must NOT be delayed: rocuronium lasts 30-60 minutes while etomidate lasts only 5-7, so withholding sedation leaves her paralyzed but AWARE. Both options that defer sedation are wrong for that reason alone." },

  { id: "pe24-179", domain: "resp", difficulty: 2, tags: ["Anaphylaxis", "Drug Allergy"],
    stem: "HM is a 35-year-old woman recently prescribed sulfamethoxazole/trimethoprim for a urinary tract infection. About 15 minutes after her first dose she developed diffuse rash, urticaria, and wheezing, and vomited twice while being loaded into the ambulance. Based on the Gell and Coombs classification, which category of immunologic drug reaction is she experiencing?",
    options: ["Type I", "Type II", "Type III", "Type IV"], correctIndex: 0,
    rationale: "Onset within minutes with urticaria, wheezing, and vomiting is IgE-mediated immediate hypersensitivity — Type I, the anaphylaxis category. Type II is IgG/IgM cytotoxic, producing anemia and cytopenias. Type III involves immune complexes causing vasculitis and serum sickness. Type IV is T-cell mediated and delayed, presenting with contact dermatitis or bullous and pustular rashes." },

  { id: "pe24-180", domain: "resp", difficulty: 3, tags: ["Anaphylaxis", "Refractory", "Glucagon"],
    stem: "HM presents to the ED about 10 minutes after paramedics arrived. She received two 0.3-mg IM epinephrine doses to the anterolateral thigh during transport, the last 3 minutes ago, and has peripheral IV access. Her diffuse rash and urticaria WORSENED during transport; she has audible wheezes and reports her throat feels like it is closing. Her only history is paroxysmal atrial tachycardia treated with metoprolol succinate 50 mg daily. Which pharmacologic intervention is most appropriate now?",
    options: ["Glucagon 3 mg by slow IV push", "Epinephrine 0.5 mg by IM injection", "Famotidine 20 mg by slow IV push", "Methylprednisolone 60 mg by slow IV push"], correctIndex: 0,
    rationale: "Her BETA-BLOCKER is the key detail: metoprolol blunts epinephrine's effect, which explains why two doses have failed. Glucagon bypasses the adrenergic receptor entirely, activating adenylyl cyclase to raise cyclic AMP, and is recommended for anaphylaxis refractory to epinephrine or in beta-blockade. A third IM epinephrine dose is unlikely to succeed. H2 blockers have not improved anaphylaxis outcomes, and corticosteroids take at least 4 hours." },

  { id: "pe24-181", domain: "pmr", difficulty: 2, tags: ["Pharmacist Role", "Intubation"],
    stem: "Your institution is starting emergency medicine pharmacy services and will collect data on EM pharmacist involvement during intubations. Based on available literature, what is the most likely benefit of EM pharmacist involvement in intubation and post-intubation management?",
    options: ["Decreased time to sedative and analgesic administration", "Decreased mortality", "Decreased time to extubation", "Decreased hospital length of stay"], correctIndex: 0,
    rationale: "Multiple studies show EM pharmacist presence shortens time to post-intubation sedation and analgesia and reduces the proportion of patients left without analgesia, improving PADIS guideline compliance. The literature has NOT demonstrated reductions in mortality, ventilator duration, or length of stay — claiming those would overstate the evidence when setting programmatic expectations." },

  { id: "pe24-182", domain: "resus", difficulty: 3, tags: ["Post-Intubation Sedation"],
    stem: "TP is a 67-year-old woman (about 75 kg) with COPD intubated for impending respiratory failure, having received etomidate 20 mg and rocuronium 80 mg about 5 minutes ago. Current BP is 155/102 with HR 88. Which IV strategy is most appropriate for post-intubation management?",
    options: ["Initiate fentanyl bolus, fentanyl infusion, and propofol infusion", "Initiate fentanyl bolus and midazolam infusion", "Initiate fentanyl bolus and dexmedetomidine infusion", "Initiate fentanyl bolus, fentanyl infusion, and midazolam infusion"], correctIndex: 0,
    rationale: "Because infusions take time to reach effect, a BOLUS is needed immediately — etomidate lasts 5-7 minutes while rocuronium lasts 30-60, so she is at risk of awareness during paralysis. Infusions then maintain moderate-to-deep sedation. Dexmedetomidine cannot reliably achieve deep sedation. Midazolam can, but is associated with delayed extubation and delirium, making propofol preferable, and her blood pressure is high enough to tolerate it." },

  { id: "pe24-183", domain: "id", difficulty: 3, tags: ["Community-Acquired Pneumonia"],
    stem: "RB is a 67-year-old man (80 kg) with 3 days of productive cough, shortness of breath, weakness, and fatigue. History includes poorly controlled hypertension and type 2 diabetes. Chest X-ray shows bilateral interstitial infiltrates and a dense left lower lobe opacity. He is afebrile with WBC 13.4 K/microliter, BUN 24 mg/dL, creatinine 1.1 mg/dL, and SpO2 85% on room air requiring 4 L/min. Vitals: BP 155/98, HR 85, temp 36.9°C, RR 31. Rapid influenza test is negative. Which empiric therapy do you recommend?",
    options: ["Ceftriaxone 1 g IV daily and azithromycin 500 mg IV daily", "Oseltamivir 75 mg orally every 12 hours", "Amoxicillin/clavulanate 875/125 mg orally every 12 hours", "Cefepime 2 g IV every 8 hours and doxycycline 100 mg IV every 12 hours"], correctIndex: 0,
    rationale: "His CURB-65 of 3 (age, respiratory rate, BUN) plus multilobar infiltrates means severe pneumonia requiring admission and COMBINATION therapy — a beta-lactam plus a macrolide (or respiratory fluoroquinolone). Beta-lactam monotherapy is therefore inadequate. He has no Pseudomonas or MRSA risk factors, so the antipseudomonal cefepime is unnecessarily broad. A negative influenza test with a lobar opacity argues against oseltamivir." },

  { id: "pe24-184", domain: "resp", difficulty: 2, tags: ["Asthma", "Pediatrics", "Protocol"],
    stem: "The pediatric and emergency departments are creating an asthma protocol to prevent unnecessary hospital admission of pediatric patients presenting with asthma exacerbations. Which therapy should be included to achieve that goal?",
    options: ["Intravenous magnesium sulfate", "Oral montelukast", "Inhaled corticosteroid plus inhaled long-acting beta2-agonist combinations", "Intravenous aminophylline"], correctIndex: 0,
    rationale: "IV magnesium sulfate has demonstrated reduced hospital admission rates in pediatric patients with severe asthma, which is precisely the protocol's stated goal. Montelukast is not recommended for exacerbations. Inhaled corticosteroid plus long-acting beta-agonist combinations have an unclear role in acute exacerbations — systemic corticosteroids are what reduce admissions. Methylxanthines such as aminophylline are no longer recommended given limited benefit and a narrow therapeutic index." },

  { id: "pe24-185", domain: "pmr", difficulty: 2, tags: ["Drug Information Resources", "IV Compatibility"],
    stem: "LB is a 56-year-old man intubated in the ED for altered mental status and rising PaCO2 from a COPD exacerbation, having received ketamine and rocuronium 10 minutes ago. Pending orders include ceftriaxone 1 g IV, azithromycin 500 mg IV, fentanyl infusion, propofol infusion, methylprednisolone 125 mg IV, and lactated Ringer's. He has only two peripheral IV lines, and the nurse asks whether a third is needed. Which resource is most appropriate to answer this?",
    options: ["ASHP Injectable Drug Information", "The Sanford Guide to Antimicrobial Therapy", "AHFS Drug Information", "Drug Information: A Guide for Pharmacists"], correctIndex: 0,
    rationale: "The question is one of IV COMPATIBILITY, and ASHP Injectable Drug Information covers compounding, stability, and compatibility — as do Trissel's databases and the King Guide. The Sanford Guide addresses antimicrobial selection and dosing. AHFS provides monographs and therapeutic guidance but not specific IV compatibility. The last option teaches how to answer drug information questions rather than supplying drug-specific data." }

];
